def fmt_time(ts):
    if not ts:
        return "-"
    try:
        return datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone().strftime("%H:%M:%S")
    except Exception:
        return str(ts)

def fmt_datetime(ts):
    if not ts:
        return "-"
    try:
        return datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone().strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return str(ts)

def pretty_name(name):
    if not name:
        return "-"
    s = str(name)
    if s.startswith("$") and s.endswith(";"):
        s = s[1:-1]
    s = s.replace("_Name", "").replace("_", " ")
    return s

def pct(value):
    if value is None:
        return "-"
    try:
        v = float(value)
        if v <= 1.0:
            v *= 100
        return f"{v:.1f}%"
    except Exception:
        return str(value)

def money(value):
    if value is None:
        return "-"
    try:
        return f"{int(value):,} CR"
    except Exception:
        return str(value)

def parse_ts(ts):
    if not ts:
        return None
    try:
        return datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
    except Exception:
        return None

def seconds_between(a, b):
    da, db = parse_ts(a), parse_ts(b)
    if not da or not db:
        return None
    return (db - da).total_seconds()

def compact_fields(event):
    parts = []
    for k, v in event.items():
        if k in ("timestamp", "event"):
            continue
        if isinstance(v, (dict, list)):
            try:
                v = json.dumps(v, ensure_ascii=False, separators=(",", ":"))
            except Exception:
                v = str(v)
        text = str(v)
        if len(text) > 160:
            text = text[:157] + "..."
        parts.append(f"{k}={text}")
    return " | ".join(parts)

class TradeLedger:
    """
    FIFO trade ledger reconstructed from the current journal.
    Purchases create lots. Sales consume those lots FIFO.
    If the bridge cannot find a matching recorded purchase, profit is marked unknown.
    """
    def __init__(self):
        self.lots = defaultdict(deque)
        self.rows = []
        self.total_realized_profit = 0
        self.known_profit_rows = 0

    def buy(self, event):
        commodity = pretty_name(event.get("Type_Localised") or event.get("Type"))
        key = commodity.lower()
        count = int(event.get("Count", 0) or 0)
        unit = int(event.get("BuyPrice", 0) or 0)
        total = int(event.get("TotalCost", count * unit) or 0)
        station = event.get("StationName") or "-"
        system = event.get("StarSystem") or "-"
        ts = event.get("timestamp")
        if count > 0:
            self.lots[key].append({
                "commodity": commodity,
                "count": count,
                "unit": unit,
                "station": station,
                "system": system,
                "timestamp": ts,
            })
        self.rows.append({
            "timestamp": ts,
            "time": fmt_time(ts),
            "type": "BUY",
            "commodity": commodity,
            "qty": count,
            "unit": unit,
            "total": total,
            "profit": None,
            "station": station,
            "system": system,
        })

    def sell(self, event):
        commodity = pretty_name(event.get("Type_Localised") or event.get("Type"))
        key = commodity.lower()
        count = int(event.get("Count", 0) or 0)
        unit = int(event.get("SellPrice", 0) or 0)
        total = int(event.get("TotalSale", count * unit) or 0)
        station = event.get("StationName") or "-"
        system = event.get("StarSystem") or "-"
        ts = event.get("timestamp")

        remaining = count
        fifo_cost_basis = 0
        known_qty = 0
        source_parts = []

        while remaining > 0 and self.lots[key]:
            lot = self.lots[key][0]
            take = min(remaining, lot["count"])
            fifo_cost_basis += take * lot["unit"]
            known_qty += take
            source_parts.append({
                "qty": take,
                "unit": lot["unit"],
                "station": lot.get("station") or "-",
                "system": lot.get("system") or "-",
                "timestamp": lot.get("timestamp"),
            })
            lot["count"] -= take
            remaining -= take
            if lot["count"] <= 0:
                self.lots[key].popleft()

        # Frontier supplies AvgPricePaid on MarketSell. Prefer it for realized
        # P/L because it describes the cargo actually sold, even if the bridge
        # was restarted after the purchase and our reconstructed FIFO is incomplete.
        try:
            event_avg_buy = float(event.get("AvgPricePaid", 0) or 0)
        except Exception:
            event_avg_buy = 0.0

        profit = None
        avg_buy = None
        margin_pct = None
        cost_basis_source = "unknown"

        if count > 0 and event_avg_buy > 0:
            avg_buy = event_avg_buy
            cost_basis = event_avg_buy * count
            profit = int(round(total - cost_basis))
            margin_pct = (profit / cost_basis) * 100.0 if cost_basis > 0 else None
            cost_basis_source = "MarketSell.AvgPricePaid"
        elif known_qty == count and count > 0 and fifo_cost_basis > 0:
            avg_buy = fifo_cost_basis / count
            profit = total - fifo_cost_basis
            margin_pct = (profit / fifo_cost_basis) * 100.0
            cost_basis_source = "FIFO journal reconstruction"

        if profit is not None:
            self.total_realized_profit += int(profit)
            self.known_profit_rows += 1

        source_station = "-"
        source_system = "-"
        if source_parts:
            by_endpoint = defaultdict(int)
            for part in source_parts:
                by_endpoint[(part["system"], part["station"])] += int(part["qty"])
            (source_system, source_station), _ = max(
                by_endpoint.items(), key=lambda kv: kv[1]
            )

        row = {
            "timestamp": ts,
            "time": fmt_time(ts),
            "type": "SELL",
            "commodity": commodity,
            "qty": count,
            "unit": unit,
            "total": total,
            "profit": profit,
            "avg_buy": avg_buy,
            "margin_pct": margin_pct,
            "cost_basis_source": cost_basis_source,
            "source_station": source_station,
            "source_system": source_system,
            "source_breakdown": source_parts,
            "station": station,
            "system": system,
        }
        self.rows.append(row)
        return row


class PowerplayTracker:
    """Correlate commodity sales with actual journal PowerplayMerits events."""
    def __init__(self):
        self.sales = []
        self.merit_events = []
        self.rank_events = []
        self.last_merit_event = None
        self.last_rank_event = None

    def add_sale(self, trade_row, system, station):
        rec = {
            "timestamp": trade_row.get("timestamp"),
            "time": trade_row.get("time"),
            "commodity": trade_row.get("commodity"),
            "qty": trade_row.get("qty"),
            "sell_unit": trade_row.get("unit"),
            "profit": trade_row.get("profit"),
            "margin_pct": trade_row.get("margin_pct"),
            "avg_buy": trade_row.get("avg_buy"),
            "cost_basis_source": trade_row.get("cost_basis_source"),
            "source_system": trade_row.get("source_system") or "-",
            "source_station": trade_row.get("source_station") or "-",
            "system": system or trade_row.get("system") or "-",
            "station": station or trade_row.get("station") or "-",
            "merit_status": "WAITING",
            "merit_display": "waiting",
            "merit_event": None,
            "seconds_to_merit": None,
        }
        self.sales.append(rec)
        return rec

    def _display_merits(self, event):
        for key in ("MeritsGained", "MeritGain", "MeritsAwarded", "AwardedMerits", "Merits", "Amount"):
            val = event.get(key)
            if isinstance(val, (int, float)):
                return f"+{int(val):,}"
        nums = [(k, v) for k, v in event.items()
                if k not in ("timestamp", "event") and isinstance(v, (int, float))]
        if nums:
            return ", ".join(f"{k}={v:,}" for k, v in nums[:3])
        return "event seen"

    def add_merit_event(self, event):
        raw = dict(event)
        self.merit_events.append(raw)
        self.last_merit_event = raw

        for sale in reversed(self.sales):
            if sale["merit_event"] is not None:
                continue
            delta = seconds_between(sale["timestamp"], event.get("timestamp"))
            if delta is None:
                continue
            if 0 <= delta <= 30:
                sale["merit_event"] = raw
                sale["seconds_to_merit"] = delta
                sale["merit_status"] = "AWARDED"
                sale["merit_display"] = self._display_merits(event)
                return sale
            if delta > 30:
                break
        return None

    def add_rank_event(self, event):
        self.rank_events.append(dict(event))
        self.last_rank_event = dict(event)

    def finalize(self, wait_seconds=20):
        now = datetime.now(timezone.utc)
        newly_finalized = []
        for sale in self.sales:
            if sale["merit_status"] != "WAITING":
                continue
            ts = parse_ts(sale["timestamp"])
            if ts and (now - ts).total_seconds() >= wait_seconds:
                sale["merit_status"] = "NO EVENT"
                sale["merit_display"] = "0 / none"
                newly_finalized.append(sale)
        return newly_finalized

    def no_event_streak(self):
        streak = 0
        for sale in reversed(self.sales):
            if sale["merit_status"] == "NO EVENT":
                streak += 1
            elif sale["merit_status"] == "WAITING":
                continue
            else:
                break
        return streak

