class SuggestionCombobox(ttk.Combobox):
    """Editable ttk combobox with lightweight predictive filtering.

    The provider receives the current text and returns display strings. The box
    remains fully editable so an unknown procedural system name is never blocked
    just because the local cache has not seen it yet.
    """

    _NAV_KEYS = {
        "Up", "Down", "Left", "Right", "Home", "End", "Prior", "Next",
        "Return", "Escape", "Tab", "Shift_L", "Shift_R", "Control_L",
        "Control_R", "Alt_L", "Alt_R",
    }

    def __init__(self, master, *, textvariable=None, suggestion_provider=None,
                 on_value_changed=None, **kwargs):
        kwargs.setdefault("state", "normal")
        super().__init__(master, textvariable=textvariable, **kwargs)
        self._suggestion_provider = suggestion_provider
        self._on_value_changed = on_value_changed
        self.configure(postcommand=self._refresh_suggestions)
        self.bind("<KeyRelease>", self._on_key_release, add="+")
        self.bind("<<ComboboxSelected>>", self._on_selected, add="+")
        self.bind("<FocusIn>", lambda _e: self._refresh_suggestions(), add="+")
        self.bind("<FocusOut>", self._on_focus_out, add="+")

    def _provider_values(self):
        if not self._suggestion_provider:
            return []
        try:
            text = self.get()
            values = self._suggestion_provider(text) or []
            seen = set()
            out = []
            for value in values:
                value = str(value or "").strip()
                key = value.casefold()
                if value and key not in seen:
                    seen.add(key)
                    out.append(value)
            return out
        except Exception:
            return []

    def _refresh_suggestions(self):
        values = self._provider_values()
        self.configure(values=values)
        return values

    def _notify_changed(self):
        if self._on_value_changed:
            try:
                self._on_value_changed()
            except Exception:
                pass

    def _on_key_release(self, event):
        if event.keysym in self._NAV_KEYS:
            return
        typed = self.get()
        try:
            cursor_at_end = self.index(tk.INSERT) == len(typed)
        except Exception:
            cursor_at_end = True
        values = self._refresh_suggestions()
        self._notify_changed()

        # Classic inline autocomplete: keep what the user typed and select only
        # the predicted suffix. Continuing to type replaces that suffix, while
        # Backspace/Delete remain normal editing operations. The drop arrow still
        # shows the filtered candidate list.
        if (
            typed.strip() and values and cursor_at_end
            and event.keysym not in {"BackSpace", "Delete"}
        ):
            first = next(
                (v for v in values if v.casefold().startswith(typed.casefold())),
                None,
            )
            if first and first.casefold() != typed.casefold():
                self.set(first)
                try:
                    self.selection_range(len(typed), tk.END)
                    self.icursor(len(typed))
                except Exception:
                    pass

    def _on_selected(self, _event):
        self._notify_changed()

    def _on_focus_out(self, _event):
        self._notify_changed()


def market_age_seconds(timestamp):
    dt = parse_ts(timestamp)
    if not dt:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return max(0.0, (datetime.now(timezone.utc) - dt.astimezone(timezone.utc)).total_seconds())


def market_age_text(timestamp):
    seconds = market_age_seconds(timestamp)
    if seconds is None:
        return "?"
    seconds = int(seconds)
    if seconds < 60:
        return f"{seconds}s"
    if seconds < 3600:
        return f"{seconds // 60}m"
    if seconds < 86400:
        return f"{seconds // 3600}h"
    days = seconds // 86400
    hours = (seconds % 86400) // 3600
    return f"{days}d {hours}h" if hours else f"{days}d"


def _market_int(value, default=0):
    try:
        return int(value)
    except Exception:
        return default


def _market_float(value, default=None):
    try:
        return float(value)
    except Exception:
        return default


def _market_timestamp_newer(candidate, existing):
    c = parse_ts(candidate)
    e = parse_ts(existing)
    if c and not e:
        return True
    if not c:
        return False
    if not e:
        return True
    if c.tzinfo is None:
        c = c.replace(tzinfo=timezone.utc)
    if e.tzinfo is None:
        e = e.replace(tzinfo=timezone.utc)
    return c.astimezone(timezone.utc) > e.astimezone(timezone.utc)


class EDDNMarketCache:
    """Persistent cache of live EDDN commodity snapshots."""

    def __init__(self, path):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.lock = threading.RLock()
        self.conn = sqlite3.connect(self.path, check_same_thread=False, timeout=10)
        self.conn.execute("PRAGMA journal_mode=WAL")
        self.conn.execute("PRAGMA synchronous=NORMAL")
        self._init_schema()

    def _init_schema(self):
        with self.lock, self.conn:
            self.conn.execute("""
                CREATE TABLE IF NOT EXISTS markets (
                    market_id INTEGER PRIMARY KEY,
                    system_name TEXT NOT NULL,
                    station_name TEXT NOT NULL,
                    market_timestamp TEXT,
                    received_at TEXT NOT NULL,
                    uploader_software TEXT,
                    uploader_version TEXT,
                    schema_ref TEXT
                )
            """)
            self.conn.execute("""
                CREATE TABLE IF NOT EXISTS commodities (
                    market_id INTEGER NOT NULL,
                    commodity_name TEXT NOT NULL,
                    commodity_key TEXT,
                    buy_price INTEGER,
                    sell_price INTEGER,
                    mean_price INTEGER,
                    stock INTEGER,
                    demand INTEGER,
                    stock_bracket INTEGER,
                    demand_bracket INTEGER,
                    PRIMARY KEY (market_id, commodity_name)
                )
            """)

            cols = {row[1] for row in self.conn.execute("PRAGMA table_info(commodities)")}
            if "commodity_key" not in cols:
                self.conn.execute("ALTER TABLE commodities ADD COLUMN commodity_key TEXT")

            missing = self.conn.execute(
                "SELECT market_id, commodity_name FROM commodities WHERE commodity_key IS NULL OR commodity_key=''"
            ).fetchall()
            if missing:
                self.conn.executemany(
                    "UPDATE commodities SET commodity_key=? WHERE market_id=? AND commodity_name=?",
                    [(market_commodity_key(name), mid, name) for mid, name in missing]
                )

            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_commodity_key ON commodities(commodity_key)")
            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_market_timestamp ON markets(market_timestamp)")
            self.conn.execute("CREATE INDEX IF NOT EXISTS idx_market_system ON markets(system_name)")

    def upsert_packet(self, packet):
        message = packet.get("message") or {}
        header = packet.get("header") or {}
        market_id = message.get("marketId")
        system_name = message.get("systemName") or message.get("StarSystem")
        station_name = message.get("stationName") or message.get("StationName")
        timestamp = message.get("timestamp")
        commodities = message.get("commodities") or []

        if market_id is None or not system_name or not station_name or not isinstance(commodities, list):
            return False, 0
        try:
            market_id = int(market_id)
        except Exception:
            return False, 0

        rows = []
        for item in commodities:
            if not isinstance(item, dict):
                continue
            name = item.get("name")
            if not name:
                continue
            rows.append((
                market_id,
                str(name),
                market_commodity_key(name),
                _market_int(item.get("buyPrice"), 0),
                _market_int(item.get("sellPrice"), 0),
                _market_int(item.get("meanPrice"), 0),
                _market_int(item.get("stock"), 0),
                _market_int(item.get("demand"), 0),
                _market_int(item.get("stockBracket"), 0),
                _market_int(item.get("demandBracket"), 0),
            ))

        received_at = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        schema_ref = str(packet.get("$schemaRef") or "")
        software = str(header.get("softwareName") or "")
        software_version = str(header.get("softwareVersion") or "")

        with self.lock, self.conn:
            old = self.conn.execute(
                "SELECT market_timestamp FROM markets WHERE market_id=?", (market_id,)
            ).fetchone()
            if old and old[0] and timestamp and not _market_timestamp_newer(timestamp, old[0]):
                # Equal timestamps are harmless duplicates; older packets must not roll the cache back.
                if parse_ts(timestamp) != parse_ts(old[0]):
                    return False, 0

            self.conn.execute("""
                INSERT INTO markets (
                    market_id, system_name, station_name, market_timestamp,
                    received_at, uploader_software, uploader_version, schema_ref
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(market_id) DO UPDATE SET
                    system_name=excluded.system_name,
                    station_name=excluded.station_name,
                    market_timestamp=excluded.market_timestamp,
                    received_at=excluded.received_at,
                    uploader_software=excluded.uploader_software,
                    uploader_version=excluded.uploader_version,
                    schema_ref=excluded.schema_ref
            """, (
                market_id, str(system_name), str(station_name), timestamp,
                received_at, software, software_version, schema_ref,
            ))
            self.conn.execute("DELETE FROM commodities WHERE market_id=?", (market_id,))
            if rows:
                self.conn.executemany("""
                    INSERT OR REPLACE INTO commodities (
                        market_id, commodity_name, commodity_key,
                        buy_price, sell_price, mean_price, stock, demand,
                        stock_bracket, demand_bracket
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, rows)
        return True, len(rows)

    def counts(self):
        with self.lock:
            markets = self.conn.execute("SELECT COUNT(*) FROM markets").fetchone()[0]
            rows = self.conn.execute("SELECT COUNT(*) FROM commodities").fetchone()[0]
        return markets, rows

    def commodity_for_market_ids(self, market_ids, commodity_key):
        ids = [int(x) for x in market_ids if x is not None]
        if not ids:
            return {}
        found = {}
        with self.lock:
            for start in range(0, len(ids), 400):
                chunk = ids[start:start+400]
                marks = ",".join("?" for _ in chunk)
                sql = f"""
                    SELECT m.market_id, m.system_name, m.station_name, m.market_timestamp,
                           m.received_at, m.uploader_software,
                           c.commodity_name, c.buy_price, c.sell_price,
                           c.stock, c.demand, c.stock_bracket, c.demand_bracket
                    FROM commodities c
                    JOIN markets m ON m.market_id=c.market_id
                    WHERE c.commodity_key=? AND m.market_id IN ({marks})
                """
                params = [commodity_key] + chunk
                for row in self.conn.execute(sql, params):
                    found[int(row[0])] = {
                        "market_id": int(row[0]), "system": row[1], "station": row[2],
                        "updated_at": row[3] or row[4], "source_software": row[5] or "EDDN",
                        "commodity": row[6], "buy_price": _market_int(row[7]),
                        "sell_price": _market_int(row[8]), "stock": _market_int(row[9]),
                        "demand": _market_int(row[10]), "stock_bracket": _market_int(row[11]),
                        "demand_bracket": _market_int(row[12]),
                    }
        return found

    def commodity_in_system(self, system_name, commodity_key):
        rows = []
        with self.lock:
            cur = self.conn.execute("""
                SELECT m.market_id, m.system_name, m.station_name, m.market_timestamp,
                       m.received_at, m.uploader_software,
                       c.commodity_name, c.buy_price, c.sell_price,
                       c.stock, c.demand, c.stock_bracket, c.demand_bracket
                FROM commodities c
                JOIN markets m ON m.market_id=c.market_id
                WHERE c.commodity_key=? AND lower(m.system_name)=lower(?)
            """, (commodity_key, system_name))
            for row in cur:
                rows.append({
                    "market_id": int(row[0]), "system": row[1], "station": row[2],
                    "updated_at": row[3] or row[4], "source_software": row[5] or "EDDN",
                    "commodity": row[6], "buy_price": _market_int(row[7]),
                    "sell_price": _market_int(row[8]), "stock": _market_int(row[9]),
                    "demand": _market_int(row[10]), "stock_bracket": _market_int(row[11]),
                    "demand_bracket": _market_int(row[12]),
                })
        return rows

    def suggest_commodities(self, text="", limit=120):
        """Return commodity names seen in the local live cache."""
        term = str(text or "").strip().casefold()
        with self.lock:
            if term:
                cur = self.conn.execute(
                    """SELECT commodity_name, COUNT(*) AS n
                       FROM commodities
                       WHERE lower(commodity_name) LIKE ?
                       GROUP BY lower(commodity_name), commodity_name
                       ORDER BY n DESC, commodity_name COLLATE NOCASE
                       LIMIT ?""",
                    (term + "%", int(limit)),
                )
            else:
                cur = self.conn.execute(
                    """SELECT commodity_name, COUNT(*) AS n
                       FROM commodities
                       GROUP BY lower(commodity_name), commodity_name
                       ORDER BY n DESC, commodity_name COLLATE NOCASE
                       LIMIT ?""",
                    (int(limit),),
                )
            return [row[0] for row in cur if row and row[0]]

    def suggest_systems(self, text="", limit=35):
        """Return recently updated market systems matching an editable prefix."""
        term = str(text or "").strip().casefold()
        with self.lock:
            if term:
                cur = self.conn.execute(
                    """SELECT system_name, MAX(COALESCE(market_timestamp, received_at)) AS latest
                       FROM markets
                       WHERE lower(system_name) LIKE ?
                       GROUP BY lower(system_name), system_name
                       ORDER BY CASE WHEN lower(system_name)=? THEN 0 ELSE 1 END,
                                latest DESC, system_name COLLATE NOCASE
                       LIMIT ?""",
                    (term + "%", term, int(limit)),
                )
            else:
                cur = self.conn.execute(
                    """SELECT system_name, MAX(COALESCE(market_timestamp, received_at)) AS latest
                       FROM markets
                       GROUP BY lower(system_name), system_name
                       ORDER BY latest DESC, system_name COLLATE NOCASE
                       LIMIT ?""",
                    (int(limit),),
                )
            return [row[0] for row in cur if row and row[0]]

    def suggest_stations(self, system_name, text="", limit=50):
        """Return stations from the cache for one exact system."""
        system = str(system_name or "").strip()
        if not system:
            return []
        term = str(text or "").strip().casefold()
        with self.lock:
            params = [system]
            where = "lower(system_name)=lower(?)"
            if term:
                where += " AND lower(station_name) LIKE ?"
                params.append(term + "%")
            params.append(int(limit))
            cur = self.conn.execute(
                f"""SELECT station_name, MAX(COALESCE(market_timestamp, received_at)) AS latest
                    FROM markets
                    WHERE {where}
                    GROUP BY lower(station_name), station_name
                    ORDER BY latest DESC, station_name COLLATE NOCASE
                    LIMIT ?""",
                tuple(params),
            )
            return [row[0] for row in cur if row and row[0]]


class EDDNListener:
    """Background read-only EDDN ZeroMQ subscriber."""

    def __init__(self, cache):
        self.cache = cache
        self.stop_event = threading.Event()
        self.thread = None
        self.lock = threading.Lock()
        self.connected = False
        self.status = "Not started"
        self.total_messages = 0
        self.commodity_messages = 0
        self.decode_errors = 0
        self.last_market = "-"
        self.last_error = ""
        try:
            self.cached_markets, self.cached_rows = self.cache.counts()
        except Exception:
            self.cached_markets, self.cached_rows = 0, 0

    def _set(self, **values):
        with self.lock:
            for key, value in values.items():
                setattr(self, key, value)

    def snapshot(self):
        with self.lock:
            return {
                "available": ZMQ_AVAILABLE,
                "connected": self.connected,
                "status": self.status,
                "total_messages": self.total_messages,
                "commodity_messages": self.commodity_messages,
                "decode_errors": self.decode_errors,
                "last_market": self.last_market,
                "last_error": self.last_error,
                "cached_markets": self.cached_markets,
                "cached_rows": self.cached_rows,
            }

    def start(self):
        if not ZMQ_AVAILABLE:
            self._set(status=f"pyzmq unavailable: {ZMQ_IMPORT_ERROR}", last_error=ZMQ_IMPORT_ERROR)
            return
        if self.thread and self.thread.is_alive():
            return
        self.stop_event.clear()
        self.thread = threading.Thread(target=self._run, daemon=True, name="EDDNListener")
        self.thread.start()

    def stop(self):
        self.stop_event.set()

    def _run(self):
        while not self.stop_event.is_set():
            context = None
            socket = None
            try:
                self._set(status=f"Connecting to {EDDN_ENDPOINT}", connected=False)
                context = zmq.Context()
                socket = context.socket(zmq.SUB)
                socket.setsockopt(zmq.SUBSCRIBE, b"")
                socket.setsockopt(zmq.RCVTIMEO, 1000)
                socket.setsockopt(zmq.LINGER, 0)
                socket.connect(EDDN_ENDPOINT)
                self._set(status="Listening live", connected=True, last_error="")

                while not self.stop_event.is_set():
                    try:
                        raw = socket.recv()
                    except zmq.Again:
                        continue

                    with self.lock:
                        self.total_messages += 1

                    try:
                        packet = json.loads(zlib.decompress(raw).decode("utf-8"))
                    except Exception as exc:
                        with self.lock:
                            self.decode_errors += 1
                            self.last_error = str(exc)
                        continue

                    schema_ref = str(packet.get("$schemaRef") or "").lower()
                    if "/commodity/" not in schema_ref:
                        continue

                    stored, item_count = self.cache.upsert_packet(packet)
                    message = packet.get("message") or {}
                    if stored:
                        with self.lock:
                            self.commodity_messages += 1
                            self.last_market = (
                                f"{message.get('stationName') or '?'} / "
                                f"{message.get('systemName') or '?'} ({item_count} items)"
                            )
                            count = self.commodity_messages
                        if count % 10 == 0:
                            try:
                                markets, rows = self.cache.counts()
                                self._set(cached_markets=markets, cached_rows=rows)
                            except Exception:
                                pass

            except Exception as exc:
                self._set(status=f"Reconnect after error: {exc}", connected=False, last_error=str(exc))
                if self.stop_event.wait(3):
                    break
            finally:
                if socket is not None:
                    try:
                        socket.close(0)
                    except Exception:
                        pass
                if context is not None:
                    try:
                        context.term()
                    except Exception:
                        pass
        self._set(status="Stopped", connected=False)


class EDDataMarketClient:
    """Anonymous REST client for EDData commodity endpoints.

    v0.10.1 deliberately avoids a redundant system-info request before every
    market search. Elite already gives us the current system's StarPos in the
    journal, so we use that as the origin coordinate when EDData results need
    local distance calculation.

    EDData's nearby commodity query can occasionally take longer than 15 sec,
    so transient read timeouts are retried once with a longer timeout.
    """

    def __init__(self, base=EDDATA_BASE, source_label="EDData"):
        self.base = base.rstrip("/")
        self.source_label = source_label

    def _get_json(self, path, params=None, timeouts=(30, 60)):
        url = self.base + path
        if params:
            url += "?" + urllib.parse.urlencode(params)

        last_error = None
        for attempt, timeout in enumerate(timeouts, start=1):
            req = urllib.request.Request(
                url,
                headers={
                    "User-Agent": "Elite-AI-Bridge/0.12.14",
                    "Accept": "application/json",
                },
                method="GET",
            )
            try:
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    data = json.loads(resp.read().decode("utf-8", errors="replace"))

                # EDData may return HTTP 200 with a structured unavailable/error
                # response, so surface that instead of silently treating it as
                # an empty result set.
                if isinstance(data, dict) and str(data.get("status", "")).lower() in ("error", "unavailable"):
                    msg = data.get("message") or data.get("info") or "EDData service unavailable"
                    raise RuntimeError(str(msg))
                return data

            except urllib.error.HTTPError as exc:
                try:
                    body = exc.read().decode("utf-8", errors="replace")[:300]
                except Exception:
                    body = ""
                raise RuntimeError(
                    f"EDData HTTP {exc.code} on {path}: {body or exc.reason}"
                ) from exc

            except urllib.error.URLError as exc:
                last_error = f"EDData connection failed on {path}: {exc.reason}"

            except TimeoutError:
                last_error = (
                    f"EDData timed out on {path} after {timeout}s "
                    f"(attempt {attempt}/{len(timeouts)})"
                )

            except OSError as exc:
                # Some Windows/Python socket read timeouts surface as OSError
                # instead of TimeoutError.
                if "timed out" in str(exc).lower():
                    last_error = (
                        f"EDData timed out on {path} after {timeout}s "
                        f"(attempt {attempt}/{len(timeouts)})"
                    )
                else:
                    raise

            if attempt < len(timeouts):
                time.sleep(0.75)

        raise RuntimeError(last_error or f"EDData request failed on {path}")

    @staticmethod
    def _records(data):
        if isinstance(data, list):
            return data
        if isinstance(data, dict):
            for key in ("results", "data", "orders", "items", "stations", "markets"):
                if isinstance(data.get(key), list):
                    return data[key]
        return []

    def system_info(self, system_name):
        system = urllib.parse.quote(str(system_name), safe="")
        data = self._get_json(f"/system/name/{system}", timeouts=(10, 20))
        return data if isinstance(data, dict) else {}

    def stations_in_system(self, system_name, timeout=6):
        system = urllib.parse.quote(str(system_name), safe="")
        data = self._get_json(f"/system/name/{system}/stations", timeouts=(timeout,))
        return self._records(data)

    def nearby_commodity(
        self,
        system_name,
        commodity,
        mode,
        min_volume,
        max_distance,
        max_days,
        exclude_carriers,
        origin_coords=None,
    ):
        system = urllib.parse.quote(str(system_name), safe="")
        commodity_key = market_commodity_key(commodity)
        if not commodity_key:
            raise RuntimeError("Commodity name is empty.")

        endpoint = "exports" if mode == "BUY" else "imports"
        commodity_path = urllib.parse.quote(commodity_key, safe="")
        params = {
            "minVolume": int(min_volume),
            "maxDistance": int(max_distance),
            "maxDaysAgo": int(max_days),
        }
        if exclude_carriers:
            params["fleetCarriers"] = "false"

        # The expensive call comes first. In v0.10.0 we did a separate system
        # lookup before this, which doubled the number of REST calls and created
        # another chance to timeout.
        data = self._get_json(
            f"/system/name/{system}/commodity/name/{commodity_path}/nearby/{endpoint}",
            params=params,
            timeouts=(30, 60),
        )

        # Prefer the StarPos supplied by Elite itself. Only ask EDData for the
        # origin coordinates if Elite has not supplied them yet.
        ox = oy = oz = None
        if isinstance(origin_coords, (list, tuple)) and len(origin_coords) >= 3:
            try:
                ox, oy, oz = map(float, origin_coords[:3])
            except Exception:
                ox = oy = oz = None

        records_raw = self._records(data)

        # Determine whether any record actually needs us to calculate distance.
        need_origin = False
        for raw in records_raw:
            if not isinstance(raw, dict):
                continue
            distance = _market_float(
                raw.get("distance", raw.get("systemDistance", raw.get("distanceLy")))
            )
            if distance is None:
                need_origin = True
                break

        if need_origin and None in (ox, oy, oz):
            try:
                origin = self.system_info(system_name)
                ox = _market_float(origin.get("systemX"))
                oy = _market_float(origin.get("systemY"))
                oz = _market_float(origin.get("systemZ"))
            except Exception:
                # Search results remain usable even if distance metadata cannot
                # be calculated; the UI will display ? for LY.
                ox = oy = oz = None

        records = []
        for raw in records_raw:
            if not isinstance(raw, dict):
                continue

            sx = _market_float(raw.get("systemX"))
            sy = _market_float(raw.get("systemY"))
            sz = _market_float(raw.get("systemZ"))
            distance = _market_float(
                raw.get("distance", raw.get("systemDistance", raw.get("distanceLy")))
            )
            if distance is None and None not in (ox, oy, oz, sx, sy, sz):
                distance = math.sqrt((sx-ox)**2 + (sy-oy)**2 + (sz-oz)**2)

            market_id = raw.get("marketId")
            try:
                market_id = int(market_id) if market_id is not None else None
            except Exception:
                market_id = None

            records.append({
                "market_id": market_id,
                "system": str(raw.get("systemName") or "?"),
                "station": str(raw.get("stationName") or "?"),
                "station_type": str(raw.get("stationType") or ""),
                "pad": str(raw.get("maxLandingPadSize") or "?"),
                "arrival_ls": _market_float(raw.get("distanceToArrival")),
                "distance_ly": distance,
                "system_x": sx,
                "system_y": sy,
                "system_z": sz,
                # ED market quote semantics:
                # buyPrice  = price to purchase FROM the market
                # sellPrice = price offered when selling TO the market
                "buy_price": _market_int(raw.get("buyPrice"), 0),
                "sell_price": _market_int(raw.get("sellPrice"), 0),
                "stock": _market_int(raw.get("stock"), 0),
                "demand": _market_int(raw.get("demand"), 0),
                "stock_bracket": _market_int(raw.get("stockBracket"), 0),
                "demand_bracket": _market_int(raw.get("demandBracket"), 0),
                "updated_at": raw.get("updatedAt"),
                "source": self.source_label,
            })
        return records


class MarketSearchEngine:
    """Shared market search layer for UI and the AI tool layer.

    Provider order:
      1. EDData
      2. Ardent Insight API (same v2 commodity API shape)
      3. Current-system EDDN/Market.json fallback if both REST services fail

    EDDN is always used as a freshness overlay when market IDs match.
    """

    def __init__(self, clients, cache):
        self.clients = list(clients)
        self.cache = cache
        self.last_provider = "-"
        self.last_provider_errors = []
        self.last_note = ""

    @staticmethod
    def _apply_overlay(base, overlay, source_label):
        if not overlay:
            return base
        if not _market_timestamp_newer(overlay.get("updated_at"), base.get("updated_at")):
            return base
        for key in (
            "system", "station", "buy_price", "sell_price", "stock", "demand",
            "stock_bracket", "demand_bracket", "updated_at"
        ):
            if key in overlay and overlay.get(key) is not None:
                base[key] = overlay.get(key)
        base["source"] = source_label
        return base

    @staticmethod
    def _qualify(record, mode, min_volume, max_distance, max_days):
        if record.get("distance_ly") is not None and record["distance_ly"] > max_distance + 1e-6:
            return False

        age = market_age_seconds(record.get("updated_at"))
        if age is not None and age > max_days * 86400:
            return False

        # Normalize the confusing raw field names into explicit commander-facing
        # semantics in ONE place. Do not reinterpret these elsewhere:
        #
        #   buy_price  -> price to BUY the commodity FROM the market
        #   sell_price -> price OFFERED when SELLING the commodity TO the market
        #
        # This is also what the live journal transactions demonstrated:
        # MarketBuy.BuyPrice is the commander purchase price and
        # MarketSell.SellPrice is the commander sale receipt price.
        record["buy_from_station_price"] = _market_int(record.get("buy_price"), 0)
        record["sell_to_station_price"] = _market_int(record.get("sell_price"), 0)

        if mode == "BUY":
            price = record["buy_from_station_price"]
            volume = _market_int(record.get("stock"), 0)
            infinite = False
        else:
            price = record["sell_to_station_price"]
            volume = _market_int(record.get("demand"), 0)
            infinite = volume == 0 and _market_int(record.get("demand_bracket"), 0) > 0

        if price <= 0:
            return False
        if not infinite and volume < min_volume:
            return False

        record["price"] = price
        record["volume"] = volume
        record["infinite_volume"] = infinite
        record["age_seconds"] = age
        return True

    def _current_system_live_rows(self, system_name, commodity_key):
        rows = []
        for overlay in self.cache.commodity_in_system(system_name, commodity_key):
            rows.append({
                "market_id": overlay.get("market_id"),
                "system": overlay.get("system") or system_name,
                "station": overlay.get("station") or "?",
                "station_type": "",
                "pad": "?",
                "arrival_ls": None,
                "distance_ly": 0.0,
                "buy_price": overlay.get("buy_price", 0),
                "sell_price": overlay.get("sell_price", 0),
                "stock": overlay.get("stock", 0),
                "demand": overlay.get("demand", 0),
                "stock_bracket": overlay.get("stock_bracket", 0),
                "demand_bracket": overlay.get("demand_bracket", 0),
                "updated_at": overlay.get("updated_at"),
                "source": "EDDN live",
            })
        return rows

    def search(
        self, system_name, commodity, mode, min_volume, max_distance, max_days,
        exclude_carriers, local_market=None, origin_coords=None
    ):
        commodity_key = market_commodity_key(commodity)
        self.last_provider = "-"
        self.last_provider_errors = []
        self.last_note = ""

        baseline = None
        for client in self.clients:
            try:
                baseline = client.nearby_commodity(
                    system_name, commodity, mode, min_volume, max_distance, max_days,
                    exclude_carriers, origin_coords=origin_coords
                )
                self.last_provider = client.source_label
                break
            except Exception as exc:
                self.last_provider_errors.append(f"{client.source_label}: {exc}")

        remote_available = baseline is not None
        if baseline is None:
            baseline = []
            self.last_provider = "EDDN local fallback"
            self.last_note = (
                "Both galaxy-wide REST providers were unavailable. "
                "Showing qualifying live data from your current system only."
            )

        by_market = {}
        no_market = []
        for row in baseline:
            mid = row.get("market_id")
            if mid is None:
                no_market.append(row)
            else:
                by_market[mid] = row

        # Overlay the REST baseline with fresher EDDN values where market IDs match.
        live = self.cache.commodity_for_market_ids(by_market.keys(), commodity_key)
        for mid, overlay in live.items():
            if mid in by_market:
                self._apply_overlay(by_market[mid], overlay, "EDDN live")

        # Always add current-system live markets, because their 0 LY distance is known.
        for row in self._current_system_live_rows(system_name, commodity_key):
            mid = row.get("market_id")
            if mid in by_market:
                self._apply_overlay(by_market[mid], row, "EDDN live")
            else:
                by_market[mid] = row

        # Your own Market.json is the highest-priority value for a station you
        # personally just opened.
        if local_market and local_market.get("commodity_key") == commodity_key:
            same_origin = str(local_market.get("system") or "").casefold() == str(system_name).casefold()
            mid = local_market.get("market_id")
            if same_origin:
                if mid in by_market:
                    row = by_market[mid]
                else:
                    row = {
                        "market_id": mid,
                        "system": local_market.get("system") or system_name,
                        "station": local_market.get("station") or "?",
                        "station_type": "",
                        "pad": "?",
                        "arrival_ls": None,
                        "distance_ly": 0.0,
                    }
                    by_market[mid] = row

                for key in (
                    "system", "station", "buy_price", "sell_price", "stock", "demand",
                    "stock_bracket", "demand_bracket", "updated_at"
                ):
                    if key in local_market:
                        row[key] = local_market[key]
                row["source"] = "Market.json (you)"

        rows = list(by_market.values()) + no_market
        qualified = [
            r for r in rows
            if self._qualify(r, mode, min_volume, max_distance, max_days)
        ]

        def distance_key(r):
            return r.get("distance_ly") if r.get("distance_ly") is not None else 10**9

        def age_key(r):
            return r.get("age_seconds") if r.get("age_seconds") is not None else 10**12

        if mode == "BUY":
            qualified.sort(key=lambda r: (r["price"], distance_key(r), age_key(r)))
        else:
            qualified.sort(key=lambda r: (-r["price"], distance_key(r), age_key(r)))

        if remote_available and self.last_provider_errors:
            self.last_note = f"Galaxy-wide baseline: {self.last_provider} after provider fallback."
        elif remote_available:
            self.last_note = f"Galaxy-wide baseline: {self.last_provider}."

        return qualified[:250]



class BridgeHistoryReader:
    """Read the compact EDDiscovery-derived commander archive without mutating it.

    The importer owns writes. This reader opens a fresh SQLite read-only connection
    when the DB/location changes or the short cache expires, so an external importer
    can safely update the archive while the Bridge is running.
    """

    TABLES = (
        "system_visits", "station_visits", "trades", "combat_events",
        "exploration_scans", "exploration_systems", "exploration_sales",
        "ships", "ship_events", "engineering_events", "material_events",
        "mission_events", "progression_events", "credit_snapshots",
        "statistics_snapshots",
    )

    def __init__(self, path):
        self.path = Path(path)
        self.last_error = ""
        self._cache_key = None
        self._cache_time = 0.0
        self._cache = None

    def _connect(self):
        uri = self.path.resolve().as_uri() + "?mode=ro"
        con = sqlite3.connect(uri, uri=True, timeout=1.5)
        con.row_factory = sqlite3.Row
        con.execute("PRAGMA query_only=ON")
        con.execute("PRAGMA busy_timeout=1500")
        return con

    @staticmethod
    def _row_dict(row):
        return dict(row) if row is not None else None

    @staticmethod
    def _scalar(con, sql, params=(), default=0):
        try:
            row = con.execute(sql, params).fetchone()
            if row is None:
                return default
            value = row[0]
            return default if value is None else value
        except sqlite3.Error:
            return default

    def snapshot(self, system=None, station=None, limit=15, force=False):
        system = str(system or "").strip()
        station = str(station or "").strip()
        limit = max(1, min(25, int(limit or 15)))
        now = time.monotonic()

        if not self.path.exists():
            snap = {
                "available": False,
                "path": str(self.path),
                "error": "Compact history database not found. Run the EDDiscovery Compact Importer.",
                "counts": {}, "current_system": None, "current_station": None,
                "trade_summary": {}, "latest_credit": None, "latest_statistics": None,
                "recent_trades": [], "ships": [], "last_import_time": None,
                "db_size_bytes": 0,
            }
            self._cache = snap
            self._cache_key = None
            return snap

        try:
            st = self.path.stat()
            key = (st.st_mtime_ns, st.st_size, system.casefold(), station.casefold(), limit)
        except OSError as exc:
            return {"available": False, "path": str(self.path), "error": str(exc), "counts": {}}

        if (not force and self._cache is not None and self._cache_key == key
                and (now - self._cache_time) < 5.0):
            return self._cache

        try:
            con = self._connect()
            try:
                names = {
                    r[0] for r in con.execute(
                        "SELECT name FROM sqlite_master WHERE type='table'"
                    )
                }
                missing = [name for name in self.TABLES if name not in names]
                if missing:
                    raise sqlite3.DatabaseError(
                        "History schema is incomplete; missing: " + ", ".join(missing)
                    )

                counts = {
                    name: int(self._scalar(con, f"SELECT COUNT(*) FROM {name}", default=0) or 0)
                    for name in self.TABLES
                }

                state = None
                if "import_state" in names:
                    state = con.execute(
                        "SELECT last_event_id,last_event_time,last_import_at,importer_version "
                        "FROM import_state ORDER BY last_import_at DESC LIMIT 1"
                    ).fetchone()

                sysrow = None
                if system and system != "-":
                    sysrow = con.execute(
                        "SELECT system_name,system_address,first_visit,last_visit,visit_count,"
                        "last_security,last_allegiance,last_government,last_economy,last_population,last_controlling_power "
                        "FROM system_visits WHERE lower(system_name)=lower(?) "
                        "ORDER BY last_visit DESC LIMIT 1",
                        (system,),
                    ).fetchone()

                stationrow = None
                if station and station != "-":
                    if system and system != "-":
                        stationrow = con.execute(
                            "SELECT station_name,system_name,market_id,station_type,first_visit,last_visit,visit_count "
                            "FROM station_visits WHERE lower(station_name)=lower(?) AND lower(system_name)=lower(?) "
                            "ORDER BY last_visit DESC LIMIT 1",
                            (station, system),
                        ).fetchone()
                    if stationrow is None:
                        stationrow = con.execute(
                            "SELECT station_name,system_name,market_id,station_type,first_visit,last_visit,visit_count "
                            "FROM station_visits WHERE lower(station_name)=lower(?) "
                            "ORDER BY last_visit DESC LIMIT 1",
                            (station,),
                        ).fetchone()

                trade = con.execute(
                    """
                    SELECT
                      COUNT(*) AS rows,
                      SUM(CASE WHEN action='BUY' THEN 1 ELSE 0 END) AS buys,
                      SUM(CASE WHEN action='SELL' THEN 1 ELSE 0 END) AS sells,
                      SUM(CASE WHEN action='BUY' THEN COALESCE(quantity,0) ELSE 0 END) AS bought_tons,
                      SUM(CASE WHEN action='SELL' THEN COALESCE(quantity,0) ELSE 0 END) AS sold_tons,
                      SUM(CASE WHEN action='BUY' THEN COALESCE(total_value,0) ELSE 0 END) AS spent,
                      SUM(CASE WHEN action='SELL' THEN COALESCE(total_value,0) ELSE 0 END) AS sales,
                      SUM(CASE WHEN action='SELL' AND avg_price_paid IS NOT NULL
                               THEN (COALESCE(unit_price,0)-avg_price_paid)*COALESCE(quantity,0)
                               ELSE 0 END) AS known_realized_profit
                    FROM trades
                    """
                ).fetchone()

                latest_credit = con.execute(
                    "SELECT event_time,credits,loan,ship_id,ship_type FROM credit_snapshots "
                    "ORDER BY event_time DESC, source_event_id DESC LIMIT 1"
                ).fetchone()
                latest_stats = con.execute(
                    "SELECT * FROM statistics_snapshots "
                    "ORDER BY event_time DESC, source_event_id DESC LIMIT 1"
                ).fetchone()

                recent = [dict(r) for r in con.execute(
                    "SELECT event_time,action,commodity,quantity,unit_price,total_value,avg_price_paid,"
                    "system_name,station_name FROM trades ORDER BY event_time DESC, source_event_id DESC LIMIT ?",
                    (limit,),
                )]
                ships = [dict(r) for r in con.execute(
                    "SELECT ship_id,ship_type,ship_name,ship_ident,first_seen,last_seen,latest_cargo_capacity,"
                    "latest_max_jump_range,last_action FROM ships ORDER BY last_seen DESC LIMIT 15"
                )]

                snap = {
                    "available": True,
                    "path": str(self.path),
                    "db_size_bytes": int(st.st_size),
                    "db_modified": datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds"),
                    "counts": counts,
                    "current_system": self._row_dict(sysrow),
                    "current_station": self._row_dict(stationrow),
                    "trade_summary": self._row_dict(trade) or {},
                    "latest_credit": self._row_dict(latest_credit),
                    "latest_statistics": self._row_dict(latest_stats),
                    "recent_trades": recent,
                    "ships": ships,
                    "last_import_event_id": state[0] if state else None,
                    "last_import_time": state[1] if state else None,
                    "last_import_run": state[2] if state else None,
                    "importer_version": state[3] if state else None,
                    "error": "",
                    "source_note": "EDDiscovery compact archive; historical context only. Live Frontier files remain authoritative.",
                }
            finally:
                con.close()

            self.last_error = ""
            self._cache_key = key
            self._cache_time = now
            self._cache = snap
            return snap
        except Exception as exc:
            self.last_error = str(exc)
            snap = {
                "available": False,
                "path": str(self.path),
                "db_size_bytes": int(st.st_size),
                "error": str(exc),
                "counts": {}, "current_system": None, "current_station": None,
                "trade_summary": {}, "latest_credit": None, "latest_statistics": None,
                "recent_trades": [], "ships": [], "last_import_time": None,
            }
            self._cache = snap
            self._cache_key = key
            self._cache_time = now
            return snap


class INTRARESClient:
    """Small no-dependency client for INTRA's documented bounty-hunting API."""

    def __init__(self, endpoint=INTRA_RES_API):
        self.endpoint = endpoint

    @staticmethod
    def _body_name(system, raw):
        text = str(raw or "").strip()
        if not text:
            return "-"
        if text.startswith("+"):
            suffix = text[1:].strip()
            return f"{system} {suffix}".strip()
        return text

    @classmethod
    def normalize_row(cls, arena, kind):
        kind_key = "haz" if str(kind).casefold().startswith("haz") else "hi"
        label = "Hazardous" if kind_key == "haz" else "High"
        status = arena.get(kind_key) if isinstance(arena, dict) else None
        if not isinstance(status, dict):
            return None
        reported = int(status.get("r", 0) or 0)
        try:
            confirmed = int(status.get("c", -1))
        except Exception:
            confirmed = -1
        try:
            res_ls = float(status.get("d", -1) or -1)
        except Exception:
            res_ls = -1.0
        body = cls._body_name(arena.get("name", "-"), status.get("b"))
        estimated = False
        if res_ls < 0 or body == "-":
            try:
                ring_ls = float(arena.get("ring_d", -1) or -1)
            except Exception:
                ring_ls = -1.0
            ring_body = cls._body_name(arena.get("name", "-"), arena.get("ring_b"))
            if reported and ring_ls >= 0:
                res_ls = ring_ls
                body = ring_body
                estimated = True
        # The API filter requires the requested RES to be present. Still reject
        # a row explicitly confirmed absent as a defensive sanity check.
        if confirmed == 0:
            return None
        if confirmed == 1:
            confidence = "CONFIRMED"
        elif reported:
            confidence = "REPORTED"
        else:
            confidence = "UNKNOWN"
        if estimated:
            confidence += " / RING EST."
        try:
            ly = float(arena.get("ref_d", -1))
        except Exception:
            ly = -1.0
        return {
            "type": label,
            "system": str(arena.get("name") or "-"),
            "distance_ly": ly,
            "body": body,
            "res_ls": res_ls,
            "confidence": confidence,
            "power": str(arena.get("pow") or "-"),
            "visits": int(arena.get("visit", 0) or 0),
        }

    def _post_kind(self, coords, radius_ly, max_ls, kind, timeout=8):
        x, y, z = (float(coords[0]), float(coords[1]), float(coords[2]))
        key = "haz" if str(kind).casefold().startswith("haz") else "hi"
        payload = {
            "ver": 1,
            "lim": 50,
            "ref": {"x": x, "y": y, "z": z, "max": float(radius_ly)},
            "arena": {"dist": {key: float(max_ls)}},
        }
        req = urllib.request.Request(
            self.endpoint,
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Content-Type": "application/json",
                "Accept": "application/json",
                "User-Agent": f"EliteAIBridge/{APP_VERSION.split()[0]}",
            },
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = json.loads(resp.read().decode("utf-8", errors="replace"))
        if not isinstance(raw, dict) or int(raw.get("ok", 0) or 0) != 1:
            raise RuntimeError(str((raw or {}).get("msg") or "INTRA returned an unsuccessful response"))
        out = []
        for row in raw.get("body") or []:
            arena = row.get("arena") if isinstance(row, dict) else None
            if not isinstance(arena, dict):
                continue
            normalized = self.normalize_row(arena, kind)
            if normalized:
                out.append(normalized)
        return out

    def search(self, coords, radius_ly=50.0, max_ls=10000.0, include_high=True, include_haz=True):
        results = []
        errors = []
        for kind, enabled in (("High", include_high), ("Hazardous", include_haz)):
            if not enabled:
                continue
            try:
                results.extend(self._post_kind(coords, radius_ly, max_ls, kind))
            except Exception as exc:
                errors.append(f"{kind}: {exc}")
        if not results and errors:
            raise RuntimeError(" | ".join(errors))
        results.sort(key=lambda r: (
            r.get("distance_ly", 1e9) if r.get("distance_ly", -1) >= 0 else 1e9,
            0 if r.get("type") == "High" else 1,
            r.get("system", ""),
        ))
        return results, errors




class BridgeApp(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title(f"{APP_NAME} {APP_VERSION}")
        self.geometry("1360x860")
        self.minsize(1120, 720)

        self.state_data = EliteState()
        self.advisor = DryRunAdvisor()
        self.current_journal = None
        self.journal_pos = 0
        # v0.12.65 live-output gate. Journal history is always useful for rebuilding
        # state, but startup/replayed rows must never speak, play SFX, call AI, or
        # drive cockpit automation. Only genuinely fresh rows may cause side effects.
        self.live_side_effect_cutoff_utc = datetime.now(timezone.utc)
        self.historical_side_effect_rows_suppressed = 0
        self.last_status_mtime = None
        self.last_market_mtime = None
        self.last_cargo_mtime = None
        self.last_navroute_mtime = None
        self.last_modulesinfo_mtime = None
        self.market_filter = tk.StringVar(value="")
        self.vars = {}

        # v0.12.23 compact commander-history reader. The importer owns writes;
        # the Bridge only reads this archive. Missing history never blocks live use.
        self.history_reader = BridgeHistoryReader(HISTORY_DB_FILE)
        self.history_snapshot = {}

        # v0.10 market layer: live EDDN cache + EDData galaxy-wide search.
        self.eddn_cache = EDDNMarketCache(EDDN_CACHE_FILE)
        self.eddn_listener = EDDNListener(self.eddn_cache)
        self.eddata_client = EDDataMarketClient(
            EDDATA_BASE, source_label="EDData"
        )
        self.ardent_client = EDDataMarketClient(
            ARDENT_BASE, source_label="Ardent"
        )
        self.market_search_engine = MarketSearchEngine(
            [self.ardent_client, self.eddata_client], self.eddn_cache
        )
        # Dedicated engine so a long-loop BUY+SELL pair search does not trample
        # the status fields of the normal Market Search or the AI market tool.
        self.loop_search_engine = MarketSearchEngine(
            [self.ardent_client, self.eddata_client], self.eddn_cache
        )
        # Route Health gets its own search-engine state so background checks do
        # not overwrite Market Search / long-loop provider diagnostics.
        self.route_health_engine = MarketSearchEngine(
            [self.ardent_client, self.eddata_client], self.eddn_cache
        )
        self.market_search_results = []
        self.market_search_result_map = {}
        self.market_search_busy = False
        self.market_last_query = None
        self.market_last_error = ""
        self.market_last_search_time = None
        self.market_search_system_var = tk.StringVar(value="")
        self.market_search_follow_current_var = tk.BooleanVar(value=True)
        self.market_search_commodity_var = tk.StringVar(value="Silver")
        self.market_search_mode_var = tk.StringVar(value="BUY")
        self.market_search_volume_var = tk.StringVar(value="1152")
        self.market_search_distance_var = tk.StringVar(value="100")
        self.market_search_age_var = tk.StringVar(value="7")
        self.market_search_exclude_carriers_var = tk.BooleanVar(value=True)
        self.market_search_ship_compatible_var = tk.BooleanVar(value=True)
        self.market_pick_rows = {}
        self.market_best_var = tk.StringVar(value="Best practical: -")
        self.market_cheapest_var = tk.StringVar(value="Cheapest / best price: -")
        self.market_closest_var = tk.StringVar(value="Closest good option: -")

        # v0.12 Trade Loop Autopilot.
        # Configuration persists, but the loop deliberately starts DISABLED
        # after each bridge launch so stale settings cannot unexpectedly route.
        self.trade_loop_enabled_var = tk.BooleanVar(value=False)
        self.trade_loop_auto_route_var = tk.BooleanVar(value=True)
        # v0.12.24 is deliberately opt-in. It can persist once the commander
        # explicitly enables it, but new installs/default configs remain OFF.
        self.trade_loop_auto_fsd_prep_var = tk.BooleanVar(value=False)
        self.trade_loop_commodity_var = tk.StringVar(value="Silver")
        self.trade_loop_cargo_var = tk.StringVar(value="1152")
