        self.station_safety_reset_pending = False
        self.station_safety_reset_verify_due = 0.0
        self.station_safety_reset_failed = False

        # v0.12.47 opt-in smart combat helpers. These never fire weapons. Auto
        # Power Plant reuses the proven Target Power Plant state machine. Auto
        # Chaff uses journal UnderAttack evidence plus encounter duration and a
        # profile-specific cooldown. Manual utility use remains invisible to the
        # journal, so displayed chaff remaining is explicitly an estimate.
        self.auto_powerplant_var = tk.BooleanVar(value=False)
        self.auto_powerplant_status = "OFF • enable to auto-select Power Plant on fully scanned WANTED heavy targets."
        self.auto_powerplant_last_signature = None
