    def _retro_init_fonts(self):
        specs = {
            "title": ("Segoe UI Semibold", 20, "bold"),
            "nav": ("Consolas", 10, "bold"),
            "section": ("Consolas", 10, "bold"),
            "hero": ("Consolas", 15, "bold"),
            "identity": ("Consolas", 10, "bold"),
            "body": ("Consolas", 9, "normal"),
            "body_bold": ("Consolas", 9, "bold"),
            "small": ("Consolas", 8, "normal"),
            "small_bold": ("Consolas", 8, "bold"),
            "micro": ("Consolas", 7, "normal"),
            "micro_bold": ("Consolas", 7, "bold"),
            "destination": ("Consolas", 14, "bold"),
            "button": ("Consolas", 9, "bold"),
        }
        self.retro_font_specs = specs
        self.retro_fonts = {}
        for key, (family, size, weight) in specs.items():
            self.retro_fonts[key] = tkfont.Font(self, family=family, size=size, weight=weight)
        self.retro_ui_scale = 1.0
        self.retro_resize_after = None

    def _retro_font(self, key):
        return self.retro_fonts.get(key, self.retro_fonts.get("body"))

    def _retro_enable_dark_titlebar(self):
        """Ask Windows 10/11 for a dark native title bar; harmless elsewhere."""
        if os.name != "nt":
            return
        try:
            self.update_idletasks()
            hwnd = int(self.winfo_id())
            value = ctypes.c_int(1)
            dwm = ctypes.windll.dwmapi
            for attr in (20, 19):
                try:
                    if dwm.DwmSetWindowAttribute(hwnd, attr, ctypes.byref(value), ctypes.sizeof(value)) == 0:
                        break
                except Exception:
                    continue
        except Exception:
            pass

    def _retro_on_resize(self, event):
        if event.widget is not self:
            return
        try:
            if self.retro_resize_after:
                self.after_cancel(self.retro_resize_after)
        except Exception:
            pass
        self.retro_resize_after = self.after(90, self._retro_apply_scale)

    def _retro_apply_scale(self):
        """Scale the finished shell/Live typography with the actual window size."""
        try:
            w = max(1, int(self.winfo_width()))
            h = max(1, int(self.winfo_height()))
            # 1360x860 is the design reference. Scaling is intentionally bounded so
            # ultrawide monitors do not turn the UI into a kiosk.
            scale = min(w / 1360.0, h / 860.0)
            scale = max(0.90, min(1.55, scale))
            if abs(scale - float(getattr(self, "retro_ui_scale", 1.0))) < 0.035:
                return
            self.retro_ui_scale = scale
            for key, (family, base, weight) in self.retro_font_specs.items():
                self.retro_fonts[key].configure(size=max(7, int(round(base * scale))))
            for holder, accent, btn in getattr(self, "retro_nav_buttons", {}).values():
                btn.configure(pady=max(7, int(round(9 * scale))), padx=max(10, int(round(12 * scale))))
            self._draw_live_ship_placeholder()
        except Exception:
            pass

    def _retro_button(self, parent, text, command, *, compact=False, danger=False, accent=False):
        """Return a physical-looking industrial switch assembly with a status lamp."""
        C = self.retro_palette
        if danger:
            lamp, face_bg, face_fg, active = C["red"], "#3a211e", "#ffd0c9", "#603129"
        elif accent:
            lamp, face_bg, face_fg, active = C["amber2"], "#3d3119", "#ffe0a0", "#5c4721"
        else:
            lamp, face_bg, face_fg, active = C["green2"], C["panel3"], C["text"], "#2d3d31"
        bezel = tk.Frame(parent, bg=C["metal_hi"], bd=0, highlightthickness=1, highlightbackground=C["metal_lo"])
        inner = tk.Frame(bezel, bg=C["metal_lo"])
        inner.pack(fill="both", expand=True, padx=2, pady=2)
        lamp_canvas = tk.Canvas(inner, width=12 if compact else 15, height=22 if compact else 31,
                                bg=C["metal_lo"], bd=0, highlightthickness=0)
        lamp_canvas.pack(side="left", fill="y", padx=(4,3), pady=3)
        cy = 11 if compact else 15
        r = 3 if compact else 4
        lamp_canvas.create_oval(6-r, cy-r, 6+r, cy+r, fill=lamp, outline="#d7d0aa", width=1)
        btn = tk.Button(inner, text=text, command=command, bg=face_bg, fg=face_fg,
                        activebackground=active, activeforeground=C["amber2"],
                        relief="raised", bd=3, overrelief="raised",
                        highlightthickness=1, highlightbackground=C["edge_dim"],
                        font=self._retro_font("small_bold" if compact else "button"),
                        padx=7 if compact else 11, pady=3 if compact else 6, cursor="hand2")
        btn.pack(side="left", fill="both", expand=True, padx=(0,3), pady=3)
        # Small stamped fastener to the right keeps the control from reading as a flat web button.
        fast = tk.Label(inner, text="•", bg=C["metal_lo"], fg=C["metal_hi"], font=self._retro_font("body_bold"))
        fast.pack(side="right", padx=(1,3))
        return bezel

    def _display_work_area(self):
        """Return the usable desktop rectangle as x, y, width, height."""
        if os.name == "nt":
            try:
                rect = ctypes.wintypes.RECT()
                SPI_GETWORKAREA = 0x0030
                ok = ctypes.windll.user32.SystemParametersInfoW(
                    SPI_GETWORKAREA, 0, ctypes.byref(rect), 0
                )
                if ok:
                    return rect.left, rect.top, max(1, rect.right - rect.left), max(1, rect.bottom - rect.top)
            except Exception:
                pass
        return 0, 0, max(1, self.winfo_screenwidth()), max(1, self.winfo_screenheight())

    def _capture_windowed_geometry(self):
        try:
            if self._display_mode_active == "WINDOWED" and self.state() == "normal":
                g = str(self.geometry() or "").strip()
                if re.match(r"^\d+x\d+(?:[+-]\d+){0,2}$", g):
                    self.windowed_geometry = g
        except Exception:
            pass

    def _apply_display_mode(self, save=False):
        mode = str(self.display_mode_var.get() or "WINDOWED").upper()
        if mode not in ("WINDOWED", "BORDERLESS", "FULLSCREEN"):
            mode = "WINDOWED"
            self.display_mode_var.set(mode)

        previous = getattr(self, "_display_mode_active", "WINDOWED")
        if previous == "WINDOWED" and mode != "WINDOWED":
            self._capture_windowed_geometry()

        try:
            self.attributes("-fullscreen", False)
        except Exception:
            pass
        try:
            self.overrideredirect(False)
        except Exception:
            pass
        try:
            self.state("normal")
        except Exception:
            pass
        self.update_idletasks()

        if mode == "WINDOWED":
            try:
                self.geometry(self.windowed_geometry or "1360x860")
            except Exception:
                self.geometry("1360x860")
        elif mode == "BORDERLESS":
            x, y, w, h = self._display_work_area()
            try:
                self.overrideredirect(True)
                self.geometry(f"{w}x{h}+{x}+{y}")
            except Exception:
                pass
        else:  # FULLSCREEN
            try:
                self.attributes("-fullscreen", True)
            except Exception:
                x, y, w, h = self._display_work_area()
                self.overrideredirect(True)
                self.geometry(f"{w}x{h}+{x}+{y}")

        self._display_mode_active = mode
        if hasattr(self, "display_mode_status_var"):
            labels = {
                "WINDOWED": "Windowed • resizable OS window",
                "BORDERLESS": "Borderless • fills usable desktop area",
                "FULLSCREEN": "Fullscreen • fills the entire display",
            }
            self.display_mode_status_var.set(labels.get(mode, mode))
        if save:
            self._save_automation_config()
        try:
            self.after(100, self._retro_apply_scale)
        except Exception:
            pass

    def _display_mode_changed(self, _event=None):
        self._apply_display_mode(save=True)

    def _reset_windowed_geometry(self):
        self.windowed_geometry = "1360x860"
        self.display_mode_var.set("WINDOWED")
        self._apply_display_mode(save=True)

    def _toggle_fullscreen_hotkey(self, _event=None):
        current = str(self.display_mode_var.get() or "WINDOWED").upper()
        self.display_mode_var.set("WINDOWED" if current == "FULLSCREEN" else "FULLSCREEN")
        self._apply_display_mode(save=True)
        return "break"

    def _retro_select_section(self, key, tab=None):
        modules = self.retro_sections.get(key)
        if not modules:
            return
        target = tab or self.retro_last_tab.get(key) or modules[0][1]
        self.retro_active_section = key
        self.retro_last_tab[key] = target
        try:
            self.main_notebook.select(target)
        except Exception:
            return
        self._retro_render_subnav(key, target)
        self._retro_update_nav_selected()

    def _retro_select_tab(self, key, tab):
        self._retro_select_section(key, tab)

    def _retro_render_subnav(self, key, selected):
        C = self.retro_palette
        self.retro_module_label.configure(text=f"MODULE // {key}")
        for child in self.retro_subnav_frame.winfo_children():
            child.destroy()
        modules = self.retro_sections.get(key, [])
        if len(modules) <= 1:
            tk.Label(self.retro_subnav_frame, text=(modules[0][0] if modules else ""),
                     bg=C["panel2"], fg=C["dim"], font=self._retro_font("micro_bold"),
                     padx=8).pack(side="right")
            return
        for label, tab in modules:
            active = str(tab) == str(selected)
            b = tk.Button(self.retro_subnav_frame, text=label,
                          command=lambda k=key, t=tab: self._retro_select_tab(k, t),
                          bg="#5a4319" if active else C["panel3"],
                          fg=C["amber2"] if active else C["text"],
                          activebackground="#73561f" if active else "#29392d",
                          activeforeground=C["amber2"], relief="sunken" if active else "raised",
                          bd=2, highlightthickness=0, font=self._retro_font("small_bold"),
                          padx=8, pady=3, cursor="hand2")
            b.pack(side="left", padx=2)

    def _retro_update_nav_selected(self):
        C = self.retro_palette
        active = getattr(self, "retro_active_section", "LIVE")
        for key, (holder, accent, btn) in self.retro_nav_buttons.items():
            selected = key == active
            accent.configure(bg=C["amber"] if selected else C["edge_dim"])
            holder.configure(bg=C["amber"] if selected else C["edge_dim"])
            btn.configure(bg="#3a3018" if selected else C["panel2"],
                          fg=C["amber2"] if selected else C["text"],
                          relief="sunken" if selected else "raised")

    def _retro_sync_from_notebook(self, event=None):
        try:
            selected = self.main_notebook.nametowidget(self.main_notebook.select())
        except Exception:
            return
        for key, modules in self.retro_sections.items():
            for _label, tab in modules:
                if str(tab) == str(selected):
                    self.retro_active_section = key
                    self.retro_last_tab[key] = tab
                    self._retro_render_subnav(key, tab)
                    self._retro_update_nav_selected()
                    return

