    def _setup_elite_binding_rows(self):
        """Return setup-facing Elite keyboard binding health without editing .binds."""
        if not getattr(self.bindings, "path", None):
            try:
                self.bindings.load()
            except Exception:
                pass
        required = [
            ("Galaxy Map", "GalaxyMapOpen"),
            ("System Map", "SystemMapOpen"),
            ("UI Focus", "UIFocus"),
            ("Interface Up", "UI_Up"),
            ("Interface Down", "UI_Down"),
            ("Interface Left", "UI_Left"),
            ("Interface Right", "UI_Right"),
            ("Interface Select", "UI_Select"),
            ("Interface Back", "UI_Back"),
            ("External / Left Panel", "FocusLeftPanel"),
            ("Boost", "UseBoostJuice"),
            ("Throttle 100%", "SetSpeed100"),
            ("Throttle 0%", "SetSpeedZero"),
            ("Landing Gear", "LandingGearToggle"),
        ]
        if bool(self.dynamic_pips_var.get()):
            required.extend([
                ("Reset Power Distribution", "ResetPowerDistribution"),
                ("Increase SYS Power", "IncreaseSystemsPower"),
                ("Increase ENG Power", "IncreaseEnginesPower"),
                ("Increase WEP Power", "IncreaseWeaponsPower"),
            ])
        rows = []
        missing = []
        for label, action in required:
            binding = self.bindings.keyboard_binding(action)
            display = self.bindings.binding_display(action) if binding else "UNBOUND"
            ok = bool(binding)
            rows.append((label, "READY" if ok else "MISSING", display))
            if not ok:
                missing.append(label)

        combined = self.bindings.keyboard_binding("HyperSuperCombination")
        hyper = self.bindings.keyboard_binding("Hyperspace")
        supercruise = self.bindings.keyboard_binding("Supercruise")
        jump_ok = bool(combined or hyper)
        sc_ok = bool(combined or supercruise)
        jump_detail = self.bindings.binding_display("HyperSuperCombination") if combined else self.bindings.binding_display("Hyperspace")
        sc_detail = self.bindings.binding_display("HyperSuperCombination") if combined else self.bindings.binding_display("Supercruise")
        rows.append(("Hyperspace / Combined FSD", "READY" if jump_ok else "MISSING", jump_detail if jump_ok else "UNBOUND"))
        rows.append(("Supercruise / Combined FSD", "READY" if sc_ok else "MISSING", sc_detail if sc_ok else "UNBOUND"))
        if not jump_ok:
            missing.append("Hyperspace or Combined FSD")
        if not sc_ok:
            missing.append("Supercruise or Combined FSD")
        return rows, missing

    def _setup_preflight_rows(self):
        ptt = self.controller_bindings.get("push_to_talk")
        ptt_ok = isinstance(ptt, dict)
        ptt_detail = (
            f"{ptt.get('device_name')} • {BridgeControllerManager.binding_label(ptt)}"
            if ptt_ok else "Map one HOTAS/controller button. Keyboard fallback remains Ctrl+Alt+Shift+V."
        )
        elite_rows, elite_missing = self._setup_elite_binding_rows()
        hotkey_count = len(getattr(self.bridge_hotkeys, "registered", set()) or set())
        hotkey_ok = hotkey_count == len(BRIDGE_HOTKEY_SPECS)
        api_ok = bool(os.environ.get("OPENAI_API_KEY"))
        audio_ok = bool(SOUNDDEVICE_AVAILABLE)
        rows = [
            ("Push-to-Talk", ("READY" if ptt_ok else "MISSING") if api_ok else "OFF", ptt_detail if api_ok else "Copilot not configured"),
            ("Elite keyboard controls", "READY" if not elite_missing else "NEEDS ATTENTION", f"{len(elite_rows)-len(elite_missing)}/{len(elite_rows)} required controls ready" + ((" • Missing: " + ", ".join(elite_missing[:5]) + ("…" if len(elite_missing) > 5 else "")) if elite_missing else "")),
            ("Microphone system", ("READY" if audio_ok else "MISSING") if api_ok else "OFF", str(self.voice_input_device_var.get() or "System Default") if api_ok and audio_ok else ("Copilot not configured" if not api_ok else f"sounddevice unavailable: {SOUNDDEVICE_IMPORT_ERROR}")),
            ("Audio output", "READY" if audio_ok else "MISSING", str(self.audio_output_device_var.get() or "System Default") if audio_ok else "Audio device layer unavailable"),
            ("AI Copilot", "READY" if api_ok else "OFF", "API key detected" if api_ok else "Core mode"),
            ("Bridge global hotkeys", "READY" if hotkey_ok else "NEEDS ATTENTION", f"{hotkey_count}/{len(BRIDGE_HOTKEY_SPECS)} registered"),
            ("HOTAS / controllers", "INFO", self.controller_manager.connected_summary()),
            ("Elite telemetry", "READY" if self.state_data.journal_connected and self.state_data.status_connected else "WAITING", f"Journal {'OK' if self.state_data.journal_connected else 'waiting'} • Status {'OK' if self.state_data.status_connected else 'waiting'}"),
        ]
        required_ready = (not elite_missing) and hotkey_ok and ((ptt_ok and audio_ok) if api_ok else True)
        return rows, elite_rows, required_ready

    def _build_setup_tab(self):
        header = ttk.LabelFrame(self.setup_tab, text="First-Run Setup / Preflight", padding=12)
        header.pack(fill="x", pady=(0, 10))
        self.setup_overall_var = tk.StringVar(value="CHECKING...")
        self.setup_summary_var = tk.StringVar(value="Bridge is checking required controls and audio/AI readiness.")
        tk.Label(header, textvariable=self.setup_overall_var, font=("Segoe UI", 18, "bold"), anchor="w").pack(fill="x")
        ttk.Label(header, textvariable=self.setup_summary_var, wraplength=1080, justify="left").pack(fill="x", pady=(3, 8))
        buttons = ttk.Frame(header)
        buttons.pack(fill="x")
        ttk.Button(buttons, text="MAP REQUIRED PTT / COMMANDS", command=self._open_controller_bindings).pack(side="left")
        ttk.Button(buttons, text="RESCAN ELITE BINDINGS", command=self._setup_rescan).pack(side="left", padx=(8,0))
        ttk.Button(buttons, text="RESCAN AUDIO", command=self._refresh_audio_devices).pack(side="left", padx=(8,0))
        ttk.Button(buttons, text="TEST MIC", command=self._test_microphone_level).pack(side="left", padx=(8,0))
        ttk.Button(buttons, text="TEST AI HEARING", command=self._test_ai_hearing).pack(side="left", padx=(8,0))
        ttk.Button(buttons, text="TEST VOICE OUTPUT", command=self._voice_test).pack(side="left", padx=(8,0))

        health = ttk.LabelFrame(self.setup_tab, text="Required Setup Health", padding=8)
        health.pack(fill="both", expand=False, pady=(0, 10))
        cols = ("Check", "Status", "Detail")
        self.setup_health_tree = ttk.Treeview(health, columns=cols, show="headings", height=8)
        self.setup_health_tree.heading("Check", text="Check")
        self.setup_health_tree.heading("Status", text="Status")
        self.setup_health_tree.heading("Detail", text="Detail")
        self.setup_health_tree.column("Check", width=220, anchor="w")
        self.setup_health_tree.column("Status", width=130, anchor="w")
        self.setup_health_tree.column("Detail", width=760, anchor="w")
        self.setup_health_tree.tag_configure("bad", foreground="#c62828")
        self.setup_health_tree.tag_configure("wait", foreground="#8a6d1d")
        self.setup_health_tree.pack(fill="x", expand=True)

        binds = ttk.LabelFrame(self.setup_tab, text="Elite Keyboard Binding Check", padding=8)
        binds.pack(fill="both", expand=True)
        self.setup_bindings_var = tk.StringVar(value="Bridge scans the active Elite preset and reports missing keyboard bindings. It does not edit Elite's .binds file.")
        ttk.Label(binds, textvariable=self.setup_bindings_var, wraplength=1080, justify="left").pack(anchor="w", pady=(0,6))
        bcols = ("Control", "Status", "Keyboard Binding")
        self.setup_bindings_tree = ttk.Treeview(binds, columns=bcols, show="headings", height=10)
        for c, width in (("Control", 300), ("Status", 130), ("Keyboard Binding", 550)):
            self.setup_bindings_tree.heading(c, text=c)
            self.setup_bindings_tree.column(c, width=width, anchor="w")
        self.setup_bindings_tree.tag_configure("missing", foreground="#c62828")
        scroll = ttk.Scrollbar(binds, orient="vertical", command=self.setup_bindings_tree.yview)
        self.setup_bindings_tree.configure(yscrollcommand=scroll.set)
        self.setup_bindings_tree.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")

    def _setup_rescan(self):
        try:
            self.bindings.load()
        except Exception:
            pass
        self._refresh_setup_preflight(force=True)
        self.refresh_preferences_widgets()

    def _open_setup_preflight(self):
        try:
            self._close_startup_overview()
            if hasattr(self, "main_notebook") and hasattr(self, "setup_tab"):
                self._retro_select_section("SETUP", self.setup_tab)
                self.lift()
                self.focus_force()
        except Exception:
            pass
        self._refresh_setup_preflight(force=True)

    def _refresh_setup_preflight(self, force=False):
        if not hasattr(self, "setup_health_tree"):
            return
        now = time.monotonic()
        if not force and now - float(getattr(self, "setup_last_refresh_mono", 0.0) or 0.0) < 1.5:
            return
        self.setup_last_refresh_mono = now
        rows, elite_rows, ready = self._setup_preflight_rows()
        tree = self.setup_health_tree
        for iid in tree.get_children(""):
            tree.delete(iid)
        for idx, (name, status, detail) in enumerate(rows):
            tag = "bad" if status in ("MISSING", "NEEDS ATTENTION") else ("wait" if status == "WAITING" else "")
            tree.insert("", "end", iid=f"health-{idx}", values=(name, status, detail), tags=((tag,) if tag else ()))
        btree = self.setup_bindings_tree
        for iid in btree.get_children(""):
            btree.delete(iid)
        for idx, (label, status, display) in enumerate(elite_rows):
            btree.insert("", "end", iid=f"bind-{idx}", values=(label, status, display), tags=(("missing",) if status == "MISSING" else ()))
        self.setup_overall_var.set("READY" if ready else "SETUP NEEDS ATTENTION")
        if ready:
            self.setup_summary_var.set("Required PTT, Elite keyboard controls, microphone/audio support, AI key and Bridge hotkeys are ready. Telemetry may remain WAITING until Elite is running.")
        else:
            self.setup_summary_var.set("Fix the red required items before treating this install as fully configured. Bridge will report problems; it will not rewrite Elite's .binds file for you.")
        self.setup_bindings_var.set(f"Active preset: {getattr(self.bindings, 'preset', '-') or '-'} • Source: {getattr(self.bindings, 'path', '-') or '-'}")

    def _make_tree(self, parent, columns, widths):
        tree = ttk.Treeview(parent, columns=columns, show="headings")
        for c in columns:
            tree.heading(c, text=c)
            tree.column(c, width=widths.get(c, 120), anchor="w")
        tree.pack(fill="both", expand=True)
        return tree



    def _hero_work_area(self):
        """Return usable desktop size in Tk logical pixels when possible."""
        try:
            if os.name == "nt":
                class RECT(ctypes.Structure):
                    _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                                ("right", ctypes.c_long), ("bottom", ctypes.c_long)]
                rect = RECT()
                if ctypes.windll.user32.SystemParametersInfoW(48, 0, ctypes.byref(rect), 0):
                    w = max(1, int(rect.right - rect.left)); h = max(1, int(rect.bottom - rect.top))
                    # Tk may report DPI-scaled logical pixels. Prefer Tk's dimensions
                    # if Windows returns a radically different coordinate space.
                    tw, th = int(self.winfo_screenwidth()), int(self.winfo_screenheight())
                    if 0.65 <= (w / max(1, tw)) <= 1.55 and 0.65 <= (h / max(1, th)) <= 1.55:
                        return w, h
        except Exception:
            pass
        return int(self.winfo_screenwidth()), int(self.winfo_screenheight())

    def _hero_choose_layout(self, work_w, work_h, chrome_free=False):
        presets = [
            (1366, 768, "hero_console_shell_1366.png"),
            (1600, 900, "hero_console_shell.png"),
            (1920, 1080, "hero_console_shell_1920.png"),
            (2560, 1440, "hero_console_shell_2560.png"),
            (3840, 2160, "hero_console_shell_3840.png"),
            (5120, 2880, "hero_console_shell_5120.png"),
        ]
        requested = str(self.hero_layout_var.get() or "AUTO").upper()
        if requested != "AUTO":
            for w, h, fn in presets:
                if requested == f"{w}X{h}":
                    return requested, w, h, fn
        # Leave a little room for normal Windows chrome. On high-DPI displays
        # Tk's reported work area is already in logical pixels, which is exactly
        # what we want for choosing a readable preset.
        fit_w = max(1, int(work_w) - (0 if chrome_free else 12))
        fit_h = max(1, int(work_h) - (0 if chrome_free else 42))
        chosen = presets[0]
        for row in presets:
            if row[0] <= fit_w and row[1] <= fit_h:
                chosen = row
        w, h, fn = chosen
        return f"{w}X{h}", w, h, fn

    def _open_hero_console(self):
        """Open the fixed-layout cinematic Live console without replacing the normal GUI."""
        try:
            if getattr(self, "hero_window", None) and self.hero_window.winfo_exists():
                self.hero_window.lift()
                self.hero_window.focus_force()
                return
        except Exception:
            self.hero_window = None

        hero_display_mode = str(self.display_mode_var.get() or "WINDOWED").upper()
        raw_sw, raw_sh = int(self.winfo_screenwidth()), int(self.winfo_screenheight())
        if hero_display_mode in ("BORDERLESS", "FULLSCREEN"):
            sw, sh = raw_sw, raw_sh
        else:
            sw, sh = self._hero_work_area()
        preset, ww, wh, asset_name = self._hero_choose_layout(sw, sh, chrome_free=hero_display_mode in ("BORDERLESS", "FULLSCREEN"))
        asset = Path(__file__).resolve().parent / "Assets" / asset_name
        if not asset.exists():
            messagebox.showerror("Hero Console", f"Missing Hero Console shell:\n{asset}")
            return

        win = tk.Toplevel(self)
        self.hero_window = win
        win.title(f"Elite AI Bridge {APP_VERSION.split()[0]} - Hero Console")
        win.configure(bg="#050705")
        win.resizable(False, False)
        if hero_display_mode == "BORDERLESS":
            try: win.overrideredirect(True)
            except Exception: pass
        elif hero_display_mode == "FULLSCREEN":
            try: win.attributes("-fullscreen", True)
            except Exception: pass
        x = max(0, (sw - ww) // 2)
        y = max(0, (sh - wh) // 2)
        win.geometry(f"{ww}x{wh}+{x}+{y}")
        try:
            win.attributes("-topmost", False)
        except Exception:
            pass
        canvas = tk.Canvas(win, width=ww, height=wh, bg="#050705", bd=0, highlightthickness=0)
        canvas.pack(fill="both", expand=False)
        self.hero_canvas = canvas
        self.hero_w, self.hero_h = ww, wh
        self.hero_sx, self.hero_sy = ww / 1600.0, wh / 900.0
        try:
            self.hero_bg_image = tk.PhotoImage(file=str(asset))
            canvas.create_image(0, 0, image=self.hero_bg_image, anchor="nw", tags=("bg",))
        except Exception as exc:
            win.destroy()
            self.hero_window = None
            messagebox.showerror("Hero Console", f"Could not load Hero Console shell:\n{exc}")
            return

        self.hero_items = {}
        self.hero_text_limits = {}
        self.hero_click_regions = []
        self.hero_hover_name = None
        self.hero_anim_phase = 0.0
        self._hero_build_dynamic_items()
        canvas.bind("<Button-1>", self._hero_canvas_click)
        canvas.bind("<Motion>", self._hero_canvas_motion)
        win.bind("<Escape>", lambda _e: self._close_hero_console())
        win.protocol("WM_DELETE_WINDOW", self._close_hero_console)
        self._hero_refresh()
        if bool(self.hero_animation_var.get()):
            self._hero_animation_tick()
        try:
            self.withdraw()
        except Exception:
            pass

    def _close_hero_console(self):
        try:
            if getattr(self, "hero_after_id", None):
                self.after_cancel(self.hero_after_id)
        except Exception:
            pass
        self.hero_after_id = None
        try:
            if getattr(self, "hero_anim_after_id", None):
                self.after_cancel(self.hero_anim_after_id)
        except Exception:
            pass
        self.hero_anim_after_id = None
        try:
            if getattr(self, "hero_window", None) and self.hero_window.winfo_exists():
                self.hero_window.destroy()
        except Exception:
            pass
        self.hero_window = None
        try:
            self.deiconify()
            self.lift()
            self.focus_force()
        except Exception:
            pass

    def _hero_xy(self, x, y):
        return int(round(x * self.hero_sx)), int(round(y * self.hero_sy))

    def _hero_font(self, base=14, bold=False):
        size = max(8, int(round(base * min(self.hero_sx, self.hero_sy))))
        return ("Consolas", size, "bold" if bold else "normal")

    def _hero_text(self, key, x, y, text="", *, fill="#d4d0bb", size=14, bold=False, anchor="nw", max_width=None):
        xx, yy = self._hero_xy(x, y)
        item = self.hero_canvas.create_text(xx, yy, text=text, fill=fill,
                                            font=self._hero_font(size, bold), anchor=anchor,
                                            tags=("dynamic", key))
        self.hero_items[key] = item
        if max_width is not None:
            self.hero_text_limits[key] = max(8, int(round(float(max_width) * self.hero_sx)))
        return item

    def _hero_fit_text(self, key, text):
        limit = (getattr(self, "hero_text_limits", {}) or {}).get(key)
        if not limit:
            return str(text)
        item = self.hero_items.get(key)
        try:
            font_spec = self.hero_canvas.itemcget(item, "font")
            font = tkfont.Font(font=font_spec)
        except Exception:
            return str(text)
        def one(line):
            line = str(line)
            if font.measure(line) <= limit:
                return line
            ell = "…"
            lo, hi = 0, len(line)
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if font.measure(line[:mid] + ell) <= limit:
                    lo = mid
                else:
                    hi = mid - 1
            return line[:lo].rstrip() + ell
        return "\n".join(one(line) for line in str(text).splitlines())

    def _hero_set(self, key, text, fill=None):
        item = self.hero_items.get(key)
        if not item:
            return
        kw = {"text": self._hero_fit_text(key, text)}
        if fill is not None:
            kw["fill"] = fill
        try:
            self.hero_canvas.itemconfigure(item, **kw)
        except Exception:
            pass

    def _hero_add_click(self, box, action, name=""):
        self.hero_click_regions.append((tuple(box), action, name))

