    def _hero_go_section(self, name):
        if name == "LIVE":
            return
        self._close_hero_console()
        try:
            self._retro_select_section(name)
        except Exception:
            pass

    def _hero_canvas_motion(self, event):
        x = event.x / max(0.001, self.hero_sx)
        y = event.y / max(0.001, self.hero_sy)
        hit_row = None
        for row in getattr(self, "hero_click_regions", []):
            (x1,y1,x2,y2), _a, name = row
            if x1 <= x <= x2 and y1 <= y <= y2:
                hit_row = row; break
        try:
            self.hero_canvas.configure(cursor="hand2" if hit_row else "")
            name = hit_row[2] if hit_row else None
            if name != getattr(self, "hero_hover_name", None):
                self.hero_hover_name = name
                self.hero_canvas.delete("hero_hover")
                if hit_row:
                    (x1,y1,x2,y2), _a, _n = hit_row
                    xx1,yy1=self._hero_xy(x1,y1); xx2,yy2=self._hero_xy(x2,y2)
                    self.hero_canvas.create_rectangle(xx1+1,yy1+1,xx2-1,yy2-1,outline="#caa85a",
                        width=max(1,int(round(1.5*min(self.hero_sx,self.hero_sy)))),tags=("hero_hover",))
        except Exception:
            pass

    def _hero_animation_tick(self):
        try:
            if not getattr(self, "hero_window", None) or not self.hero_window.winfo_exists():
                return
            if not bool(self.hero_animation_var.get()):
                return
            self.hero_anim_phase = (float(getattr(self, "hero_anim_phase", 0.0)) + 0.018) % 1.0
            c = self.hero_canvas
            c.delete("hero_anim")
            # Quiet diagnostic sweep through the ship instrument bay.
            x = 582 + 340 * self.hero_anim_phase
            xx, y1 = self._hero_xy(x, 326); _, y2 = self._hero_xy(x, 580)
            c.create_line(xx, y1, xx, y2, fill="#173c25", width=max(1,int(self.hero_sx)), tags=("hero_anim",))
            # Active LIVE lamp breathes gently instead of blinking.
            import math as _math
            glow = 0.5 + 0.5 * _math.sin(self.hero_anim_phase * _math.pi * 2.0)
            col = "#54f48a" if glow > 0.45 else "#2b8c52"
            x1,y1=self._hero_xy(48,184); x2,y2=self._hero_xy(55,215)
            c.create_rectangle(x1,y1,x2,y2,fill=col,outline="",tags=("hero_anim",))
            self.hero_anim_after_id = self.after(80, self._hero_animation_tick)
        except Exception:
            self.hero_anim_after_id = None

    def _hero_canvas_click(self, event):
        x = event.x / max(0.001, self.hero_sx)
        y = event.y / max(0.001, self.hero_sy)
        for (x1,y1,x2,y2), action, _name in list(getattr(self, "hero_click_regions", [])):
            if x1 <= x <= x2 and y1 <= y <= y2:
                try:
                    xx1,yy1=self._hero_xy(x1,y1); xx2,yy2=self._hero_xy(x2,y2)
                    flash=self.hero_canvas.create_rectangle(xx1+2,yy1+2,xx2-2,yy2-2,outline="#efc56b",width=max(1,int(2*self.hero_sx)),tags=("hero_press",))
                    self.hero_canvas.after(140, lambda i=flash: self.hero_canvas.delete(i))
                except Exception:
                    pass
                try:
                    action()
                except Exception as exc:
                    try:
                        messagebox.showerror("Hero Console", str(exc), parent=self.hero_window)
                    except Exception:
                        pass
                return

    def _pretty_ship_name(self, raw):
        raw = str(raw or "").strip()
        if not raw:
            return "-"
        key = raw.lower().replace(" ", "").replace("_", "").replace("-", "")
        aliases = {
            "mandalay": "Mandalay",
            "panthermkii": "Panther Clipper Mk II",
            "cobramkv": "Cobra Mk V",
            "pythonmkii": "Python Mk II",
            "type8": "Type-8 Transporter",
            "type8transporter": "Type-8 Transporter",
            "type9": "Type-9 Heavy",
            "type9heavy": "Type-9 Heavy",
            "type10": "Type-10 Defender",
            "type10defender": "Type-10 Defender",
            "federalcorvette": "Federal Corvette",
            "federalgunship": "Federal Gunship",
            "federalassaultship": "Federal Assault Ship",
            "federaldropship": "Federal Dropship",
            "imperialcutter": "Imperial Cutter",
            "imperialclipper": "Imperial Clipper",
            "imperialcourier": "Imperial Courier",
            "kraitmkii": "Krait Mk II",
            "kraitmap2": "Krait Mk II",
            "kraitphantom": "Krait Phantom",
        }
        if key in aliases:
            return aliases[key]
        return raw.replace("_", " ").replace("-", " ").title()

    def _hero_draw_ship(self):
        c = getattr(self, "hero_canvas", None)
        if not c:
            return
        try:
            c.delete("hero_ship")
            s = self.state_data
            ship_type = str(getattr(s, "ship", "") or "").lower()
            sx, sy = self.hero_sx, self.hero_sy
            cx, cy = self._hero_xy(751, 431)
            line = "#57f08b"
            inner = "#2b8551"
            guide = "#18492b"

            rx, ry = 137*sx, 108*sy
            c.create_oval(cx-rx, cy-ry, cx+rx, cy+ry, outline=guide, width=max(1,int(sx)), tags=("hero_ship",))
            c.create_line(cx-rx-10*sx, cy, cx+rx+10*sx, cy, fill=guide, width=1, tags=("hero_ship",))
            c.create_line(cx, cy-ry-8*sy, cx, cy+ry+8*sy, fill=guide, width=1, tags=("hero_ship",))

            if "mandalay" in ship_type:
                # Dedicated Mandalay top-view schematic.
                outline = [(0,-1.00),(-.08,-.72),(-.17,-.54),(-.36,-.39),(-.60,-.21),(-.92,-.02),
                           (-.54,.15),(-.34,.29),(-.25,.51),(-.12,.86),(0,.63),(.12,.86),(.25,.51),
                           (.34,.29),(.54,.15),(.92,-.02),(.60,-.21),(.36,-.39),(.17,-.54),(.08,-.72)]
                wx, hy = 142*sx, 111*sy
                pts=[]
                for nx,ny in outline:
                    pts.extend((cx+nx*wx, cy+ny*hy))
                c.create_polygon(*pts, outline=line, fill="", width=max(1,int(2.0*sx)), tags=("hero_ship",))
                c.create_line(cx,cy-hy*.97,cx,cy+hy*.62,fill=line,width=max(1,int(1.4*sx)),tags=("hero_ship",))
                canopy=[(-.10,-.66),(0,-.82),(.10,-.66),(.08,-.48),(0,-.39),(-.08,-.48),(-.10,-.66)]
                cp=[]
                for nx,ny in canopy:
                    cp.extend((cx+nx*wx,cy+ny*hy))
                c.create_line(*cp,fill=inner,width=max(1,int(1.2*sx)),tags=("hero_ship",))
                for side in (-1,1):
                    X=lambda q: cx+side*q*wx
                    Y=lambda q: cy+q*hy
                    c.create_line(X(.09),Y(-.55),X(.58),Y(-.19),X(.88),Y(-.02),fill=inner,width=max(1,int(1.2*sx)),tags=("hero_ship",))
                    c.create_line(X(.12),Y(-.34),X(.49),Y(.02),X(.39),Y(.24),fill=inner,width=max(1,int(1.2*sx)),tags=("hero_ship",))
                    c.create_rectangle(X(.76)-18*sx,Y(-.12),X(.76)+18*sx,Y(.11),outline=inner,width=max(1,int(sx)),tags=("hero_ship",))
                    c.create_line(X(.19),Y(.25),X(.31),Y(.52),X(.14),Y(.80),fill=inner,width=max(1,int(1.2*sx)),tags=("hero_ship",))
                    c.create_line(X(.14),Y(-.48),X(.22),Y(.16),X(.11),Y(.52),fill=guide,width=1,tags=("hero_ship",))
                for yy,ww in [(-.38,.23),(-.16,.36),(.07,.40),(.30,.30),(.50,.20)]:
                    c.create_line(cx-ww*wx,cy+yy*hy,cx+ww*wx,cy+yy*hy,fill=inner,width=1,tags=("hero_ship",))
                c.create_oval(cx-16*sx,cy-5*sy,cx+16*sx,cy+27*sy,outline=inner,width=1,tags=("hero_ship",))
            else:
                size=min(122*sx,112*sy)
                pts=[(cx,cy-size*.95),(cx-size*.18,cy-size*.46),(cx-size*.70,cy-size*.02),
                     (cx-size*.88,cy+size*.14),(cx-size*.30,cy+size*.36),(cx-size*.18,cy+size*.78),
                     (cx,cy+size*.58),(cx+size*.18,cy+size*.78),(cx+size*.30,cy+size*.36),
                     (cx+size*.88,cy+size*.14),(cx+size*.70,cy-size*.02),(cx+size*.18,cy-size*.46)]
                flat=[v for p in pts for v in p]
                c.create_polygon(*flat,outline=line,fill="",width=max(1,int(2*sx)),tags=("hero_ship",))
                c.create_line(cx,cy-size*.95,cx,cy+size*.58,fill=inner,width=1,tags=("hero_ship",))
        except Exception:
            pass

    def _hero_recent_event_lines(self):
        lines=[]
        try:
            hist=list(getattr(self,"recent_event_history",[]) or [])[-8:]
            for row in reversed(hist):
                txt=str(row).replace("\n"," ")
                if len(txt)>48: txt=txt[:47]+"…"
                lines.append(txt)
        except Exception:
            pass
        if not lines:
            try:
                for row in list(getattr(self,"pilot_notifications",[]) or [])[-6:][::-1]:
                    txt=str(row).replace("\n"," ")
                    lines.append(txt[:48])
            except Exception:
                pass
        return lines[:8]

    def _hero_refresh(self):
        try:
            if not getattr(self,"hero_window",None) or not self.hero_window.winfo_exists():
                return
        except Exception:
            return
        C={"green":"#79e59b","amber":"#efc56b","red":"#e05a4d","dim":"#879087","text":"#d4d0bb"}
        s=self.state_data
        self._hero_set("commander",str(getattr(s,"commander","-") or "-"))
        ship_name=str(getattr(s,"ship_name","") or "")
        ship_type=str(getattr(s,"ship","-") or "-")
        self._hero_set("ship", self._pretty_ship_name(ship_name if ship_name else ship_type))
        self._hero_set("system",str(getattr(s,"system","-") or "-"))
        station=str(getattr(s,"station","-") or "-")
        self._hero_set("station",station if station!="-" else "IN FLIGHT")
        if s.flag("Docked"): game="DOCKED"
        elif s.flag("Supercruise"): game="SUPERCRUISE"
        elif s.flag("FSD Charging"): game="FSD CHARGING"
        else: game="NORMAL FLIGHT"
        self._hero_set("game_state",game)
        self._hero_set("utc",datetime.now(timezone.utc).strftime("%H:%M:%S UTC"))

        hull=getattr(s,"hull_health",None)
        self._hero_set("hull","UNKNOWN" if hull is None else f"{float(hull)*100:.0f}%", C["red"] if hull is not None and hull<.35 else C["green"])
        self._hero_set("shields","UP" if s.flag("Shields Up") else "DOWN",C["green"] if s.flag("Shields Up") else C["red"])
        st=s.status or {}
        fuel=st.get("Fuel")
        if isinstance(fuel,dict) and fuel.get("FuelMain") is not None:
            fmain=float(fuel.get("FuelMain") or 0.0); cap=float(getattr(s,"fuel_capacity_main",0.0) or 0.0)
            ftxt=f"{fmain:.1f} t"+(f"  {fmain/cap*100:.0f}%" if cap>0 else "")
        else: ftxt="-"
        self._hero_set("fuel",ftxt,C["red"] if s.flag("Low Fuel") else C["green"])
        try: ptxt=self.vars.get("pips").get()
        except Exception: ptxt="-"
        self._hero_set("pips",ptxt)
        cargo=int(getattr(s,"cargo_count",0) or 0); cap=getattr(s,"cargo_capacity",None)
        self._hero_set("cargo",f"{cargo:,} / {int(cap):,} t" if cap is not None else f"{cargo:,} t")
        try: fsdtxt=self.vars.get("fsd").get()
        except Exception: fsdtxt="-"
        self._hero_set("fsd",fsdtxt,C["amber"] if s.flag("FSD Mass Locked") or s.flag("FSD Cooldown") else C["green"])
        self._hero_set("gear","DOWN" if s.flag("Landing Gear") else "UP",C["amber"] if s.flag("Landing Gear") and not s.flag("Docked") else C["green"])
        self._hero_set("hardpoints","DEPLOYED" if s.flag("Hardpoints") else "RETRACTED",C["amber"] if s.flag("Hardpoints") else C["green"])

        if getattr(self,"egress_phase","IDLE")!="IDLE": bstate="EMERGENCY EGRESS"; bmsg=str(getattr(self,"egress_status","Emergency sequence active.")); bcol=C["red"]
        elif getattr(self,"native_command_busy",False): bstate=str(getattr(self,"native_command_name","COMMAND RUNNING") or "COMMAND RUNNING").upper(); bmsg=str(getattr(self,"native_command_status","Bridge owns cockpit controls.")); bcol=C["amber"]
        elif getattr(self,"station_automation_busy",False): bstate="SHIP SERVICES"; bmsg=str(getattr(self,"station_automation_status","Station maintenance running.")); bcol=C["amber"]
        elif getattr(self,"voice_input_recording",False): bstate="LISTENING"; bmsg="PTT active. Listening for your command."; bcol=C["green"]
        elif getattr(self,"copilot_busy",False): bstate="AI THINKING"; bmsg="Luna is processing your request."; bcol=C["amber"]
        elif str(getattr(self.voice_engine,"status","")).startswith("SPEAKING"): bstate="AI SPEAKING"; bmsg=str(self.voice_engine.status); bcol=C["amber"]
        else: bstate="IDLE"; bmsg="Ready for your command, Commander."; bcol=C["green"]
        self._hero_set("bridge_state",bstate,bcol); self._hero_set("bridge_msg",bmsg,bcol)
        self._hero_set("ship_schematic_name",f"FRAME // {self._pretty_ship_name(ship_type).upper()}")
        self._hero_draw_ship()

        def sind(key,value,level="ok"):
            col=C["green"] if level=="ok" else (C["amber"] if level in ("warn","info") else C["red"])
            self._hero_set("syslamp_"+key,"●",col); self._hero_set("sys_"+key,value,col)
        sind("telemetry","ONLINE" if s.journal_connected and s.status_connected else "CHECK","ok" if s.journal_connected and s.status_connected else "bad")
        ai_key=bool(os.environ.get("OPENAI_API_KEY")); sind("ai","THINKING" if self.copilot_busy else ("READY" if ai_key else "NO KEY"),"warn" if self.copilot_busy else ("ok" if ai_key else "bad"))
        ptt=self.controller_bindings.get("push_to_talk"); sind("voice","READY" if isinstance(ptt,dict) else "MAP PTT","ok" if isinstance(ptt,dict) else "bad")
        sind("audio","READY" if SOUNDDEVICE_AVAILABLE else "CHECK","ok" if SOUNDDEVICE_AVAILABLE else "warn")
        ctrl=bool(getattr(self,"controller_manager",None) and self.controller_manager.devices_snapshot()); sind("controllers","DETECTED" if ctrl else "CHECK","ok" if ctrl else "warn")
        try: _,missing=self._setup_elite_binding_rows()
        except Exception: missing=["unknown"]
        sind("bindings","OK" if not missing else f"{len(missing)} MISSING","ok" if not missing else "bad")
        sind("pips_ind","ACTIVE" if bool(self.dynamic_pips_var.get()) else "OFF","ok" if bool(self.dynamic_pips_var.get()) else "info")
        services=any((bool(self.auto_refuel_var.get()),bool(self.auto_repair_var.get()),bool(self.auto_rearm_var.get()))); sind("services","READY" if services else "OFF","ok" if services else "info")
        arules=sum(1 for v in (getattr(self,"ai_session_rules",{}) or {}).values() if v); sind("rules",f"{arules} ACTIVE" if arules else "NONE","ok" if arules else "info")
        self._hero_set("nominal","ALL SYSTEMS NOMINAL" if not missing else "ATTENTION REQUIRED",C["green"] if not missing else C["red"])

        evlines=self._hero_recent_event_lines(); self._hero_set("events","\n".join(evlines) if evlines else "No recent events")
        alerts=[]
        if s.flag("Being Interdicted"): alerts.append("INTERDICTION IN PROGRESS")
        if time.time()-float(getattr(s,"last_under_attack",0.0) or 0.0)<15: alerts.append("RECENT HOSTILE FIRE")
        if s.flag("Overheating"): alerts.append("SHIP OVERHEATING")
        if s.flag("Low Fuel"): alerts.append("LOW FUEL")
        self._hero_set("alerts","\n".join(alerts) if alerts else "●  No active alerts", C["red"] if alerts else C["green"])

        dest=str(getattr(s,"nav_route_destination","-") or "-"); target=str(getattr(s,"nav_target_system","-") or "-")
        if dest not in ("","-"): self._hero_set("destination",dest); self._hero_set("destination_detail",f"FSD target: {target if target not in ('','-') else dest}  //  route armed")
        elif target not in ("","-"): self._hero_set("destination",target); self._hero_set("destination_detail","FSD target selected // no full route")
        else: self._hero_set("destination","NO ROUTE"); self._hero_set("destination_detail","No navigation route is currently plotted.")
        self._hero_set("voice","PTT: LISTENING" if getattr(self,"voice_input_recording",False) else ("PTT: READY" if isinstance(ptt,dict) else "PTT: NOT MAPPED"), C["green"] if isinstance(ptt,dict) else C["red"])
        self._hero_set("ai","LUNA: THINKING" if self.copilot_busy else ("LUNA: READY" if ai_key else "LUNA: API KEY MISSING"), C["amber"] if self.copilot_busy else (C["green"] if ai_key else C["red"]))
        est=(self.ai_input_tokens/1_000_000*AI_INPUT_PER_MILLION+self.ai_output_tokens/1_000_000*AI_OUTPUT_PER_MILLION); tt=int(self.ai_input_tokens or 0)+int(self.ai_output_tokens or 0)
        self._hero_set("cost",f"Requests  {self.ai_calls}\nTokens    {tt:,}\nCost      ~${est:.4f}")
        last=str(getattr(self,"ai_spoken","") or "").strip()
        if last in ("","-","NONE","None"): last=str(getattr(self.voice_engine,"last_text","") or "").strip()
        self._hero_set("last_ai",last if last not in ("","-") else "Standing by, Commander.")
        self.hero_after_id=self.after(250,self._hero_refresh)

    def _build_live_tab(self):
        """Build the responsive retro command-deck Live dashboard."""
        C = self.retro_palette
        self.live_palette = C
        F = self.retro_fonts

        fields = [
            "ship","system","station","body","target","shields","danger",
            "threat_evidence","under_attack","overheat","hardpoints","nightvision",
            "gear","lights","supercruise","lowfuel","fsd","firegroup","pips",
            "fuel","legal","cargo_live","last_event",
        ]
        for key in fields:
            if key not in self.vars:
                self.vars[key] = tk.StringVar(value="-")

        self.decision_var = tk.StringVar(value="OBSERVE")
        self.reason_var = tk.StringVar(value="Waiting for live state.")
        self.trade_summary_var = tk.StringVar(value="Waiting for trade activity.")
        self.latest_pp_var = tk.StringVar(value="No commodity sale tracked yet.")
        self.ai_live_var = tk.StringVar(value="AI has not analyzed the current state yet.")

        self.live_commander_var = tk.StringVar(value="-")
        self.live_ship_identity_var = tk.StringVar(value="-")
        self.live_system_var = tk.StringVar(value="-")
        self.live_station_var = tk.StringVar(value="-")
        self.live_game_state_var = tk.StringVar(value="INITIALIZING")
        self.live_bridge_state_var = tk.StringVar(value="INITIALIZING")
        self.live_bridge_message_var = tk.StringVar(value="Bridge systems initializing.")
        self.live_hull_var = tk.StringVar(value="-")
        self.live_shield_var = tk.StringVar(value="-")
        self.live_fuel_var = tk.StringVar(value="-")
        self.live_pips_var = tk.StringVar(value="-")
        self.live_cargo_var = tk.StringVar(value="-")
        self.live_fsd_var = tk.StringVar(value="-")
        self.live_gear_var = tk.StringVar(value="-")
        self.live_hardpoints_var = tk.StringVar(value="-")
        self.live_destination_var = tk.StringVar(value="NO ROUTE")
        self.live_destination_detail_var = tk.StringVar(value="No navigation route is currently plotted.")
        self.live_voice_var = tk.StringVar(value="PTT initializing")
        self.live_ai_var = tk.StringVar(value="Luna initializing")
        self.live_ai_cost_var = tk.StringVar(value="0 calls  •  0 tokens  •  est. $0.0000")
        self.live_alert_var = tk.StringVar(value="No active alerts")
        self.live_last_ai_var = tk.StringVar(value="Standing by, Commander.")

        root = tk.Frame(self.live_tab, bg=C["bg"], bd=0, highlightthickness=0)
        root.pack(fill="both", expand=True)
        root.grid_columnconfigure(0, weight=1)
        root.grid_rowconfigure(1, weight=1)

        def panel(parent, title, row, col, *, rowspan=1, columnspan=1, sticky="nsew", padx=4, pady=4):
            # Two-layer edge creates a physical inset bezel rather than a flat card.
            shadow = tk.Frame(parent, bg="#020403", bd=0)
            shadow.grid(row=row, column=col, rowspan=rowspan, columnspan=columnspan,
                        sticky=sticky, padx=(padx+2, max(0,padx-1)), pady=(pady+2, max(0,pady-1)))
            outer = tk.Frame(parent, bg=C["edge2"], bd=0)
            outer.grid(row=row, column=col, rowspan=rowspan, columnspan=columnspan,
                       sticky=sticky, padx=padx, pady=pady)
            outer.grid_columnconfigure(0, weight=1)
            outer.grid_rowconfigure(1, weight=1)
            head = tk.Frame(outer, bg=C["panel2"])
            head.grid(row=0, column=0, sticky="ew", padx=2, pady=(2,0))
            tk.Label(head, text="●", bg=C["panel2"], fg=C["metal_hi"], font=F["micro"]).pack(side="left", padx=(5,3))
            tk.Label(head, text="◆", bg=C["panel2"], fg=C["amber"], font=F["micro_bold"]).pack(side="left", padx=(1,5))
            tk.Label(head, text=title.upper(), bg=C["panel2"], fg=C["amber2"],
                     font=F["section"], anchor="w", pady=5).pack(side="left", fill="x", expand=True)
            tk.Label(head, text="●", bg=C["panel2"], fg=C["metal_hi"], font=F["micro"]).pack(side="right", padx=(3,5))
            body = tk.Frame(outer, bg=C["panel"], bd=0)
            body.grid(row=1, column=0, sticky="nsew", padx=2, pady=(0,2))
            return body

        def value_label(parent, variable, *, fg=None, font=None, anchor="w", wrap=0):
            return tk.Label(parent, textvariable=variable, bg=C["panel"], fg=fg or C["green"],
                            font=font or F["body"], anchor=anchor, justify="left", wraplength=wrap)

        def action_button(parent, text, command, *, accent=False, danger=False):
            return self._retro_button(parent, f"▸  {text}", command, accent=accent, danger=danger)

        # ----- Identity strip: the shell already owns the product title ------------
        identity = tk.Frame(root, bg=C["edge2"])
        identity.grid(row=0, column=0, sticky="ew", padx=4, pady=(2,3))
        weights = (2, 2, 2, 4, 2)
        for i, w in enumerate(weights):
            identity.grid_columnconfigure(i, weight=w)
        identity_items = [
            ("CMDR", self.live_commander_var), ("SHIP", self.live_ship_identity_var),
            ("SYSTEM", self.live_system_var), ("STATION", self.live_station_var),
            ("GAME STATE", self.live_game_state_var),
        ]
        for i, (title, var) in enumerate(identity_items):
            cell = tk.Frame(identity, bg=C["panel"], highlightthickness=1, highlightbackground=C["edge_dim"])
            cell.grid(row=0, column=i, sticky="nsew", padx=(1 if i else 2,1), pady=2)
            tk.Label(cell, text=title, bg=C["panel"], fg=C["dim"], font=F["micro_bold"], anchor="w").pack(fill="x", padx=8, pady=(4,0))
            tk.Label(cell, textvariable=var, bg=C["panel"], fg=C["text"], font=F["identity"], anchor="w").pack(fill="x", padx=8, pady=(0,5))

        # ----- Main command deck -----------------------------------------------------
        main = tk.Frame(root, bg=C["bg"])
        main.grid(row=1, column=0, sticky="nsew")
        main.grid_columnconfigure(0, weight=23, uniform="live")
        main.grid_columnconfigure(1, weight=47, uniform="live")
        main.grid_columnconfigure(2, weight=30, uniform="live")
        main.grid_rowconfigure(0, weight=1)

        ship = panel(main, "Ship Status", 0, 0)
        ship.grid_columnconfigure(1, weight=1)
        status_rows = [
            ("HULL", self.live_hull_var, "hull"), ("SHIELDS", self.live_shield_var, "shields"),
            ("FUEL", self.live_fuel_var, "fuel"), ("PIPS", self.live_pips_var, "pips"),
            ("CARGO", self.live_cargo_var, "cargo"), ("FSD", self.live_fsd_var, "fsd"),
            ("LANDING GEAR", self.live_gear_var, "gear"), ("HARDPOINTS", self.live_hardpoints_var, "hardpoints"),
        ]
        self.live_status_value_labels = {}
        for r, (name, var, key) in enumerate(status_rows):
            tk.Label(ship, text=name, bg=C["panel"], fg=C["dim"], font=F["body"], anchor="w").grid(row=r, column=0, sticky="w", padx=(12,6), pady=7)
            lab = tk.Label(ship, textvariable=var, bg=C["panel"], fg=C["green"], font=F["body_bold"], anchor="e")
            lab.grid(row=r, column=1, sticky="ew", padx=(6,12), pady=7)
            self.live_status_value_labels[key] = lab
        # Small physical divider / legend instead of the duplicate mini ship graphic.
        tk.Frame(ship, bg=C["edge_dim"], height=1).grid(row=len(status_rows), column=0, columnspan=2, sticky="ew", padx=10, pady=(6,4))
        tk.Label(ship, text="SHIP TELEMETRY // LIVE", bg=C["panel"], fg=C["dim"], font=F["micro_bold"], anchor="w").grid(row=len(status_rows)+1, column=0, columnspan=2, sticky="ew", padx=12, pady=(2,8))
        self.live_ship_mini_canvas = None

        bridge = panel(main, "Bridge Status", 0, 1)
        bridge.grid_columnconfigure(0, weight=2)
        bridge.grid_columnconfigure(1, weight=3)
        bridge.grid_rowconfigure(2, weight=1)
        self.live_bridge_state_label = tk.Label(bridge, textvariable=self.live_bridge_state_var,
                                                bg="#244c31", fg="#c7ffda",
                                                font=F["hero"], pady=7,
                                                highlightthickness=1, highlightbackground="#39784d")
        self.live_bridge_state_label.grid(row=0, column=0, columnspan=2, sticky="ew", padx=10, pady=(10,3))
        tk.Label(bridge, textvariable=self.live_bridge_message_var, bg=C["panel"], fg=C["green"],
                 font=F["body"], justify="center").grid(row=1, column=0, columnspan=2, sticky="ew", padx=12, pady=(2,5))
        self.live_ship_canvas = tk.Canvas(bridge, bg=C["black"], bd=0, highlightthickness=2,
                                          highlightbackground=C["edge_dim"], height=205)
