    def _live_set_system_indicator(self, key, text, level="ok"):
        if not hasattr(self, "live_system_labels") or key not in self.live_system_labels:
            return
        C = self.live_palette
        colors = {"ok": C["green"], "warn": C["amber"], "bad": C["red"], "info": C["dim"]}
        fg = colors.get(level, C["dim"])
        dot, label = self.live_system_labels[key]
        dot.configure(fg=fg)
        label.configure(text=text, fg=fg)

    def _draw_live_ship_placeholder(self, event=None):
        """Draw scalable green technical placeholder until per-ship art is added."""
        C = getattr(self, "live_palette", None)
        if not C:
            return
        for canvas in (getattr(self, "live_ship_canvas", None), getattr(self, "live_ship_mini_canvas", None)):
            if canvas is None:
                continue
            try:
                canvas.delete("all")
                w = max(80, int(canvas.winfo_width() or 300))
                h = max(60, int(canvas.winfo_height() or 180))
                # restrained CRT grid
                step = max(24, int(min(w, h) / 7))
                for x in range(0, w, step):
                    canvas.create_line(x, 0, x, h, fill="#12261a", width=1)
                for y in range(0, h, step):
                    canvas.create_line(0, y, w, y, fill="#12261a", width=1)
                cx, cy = w/2, h/2
                scale = min(w*0.38, h*0.42)
                # deliberately generic top-view spacecraft silhouette. Real ship art
                # will replace this by ship type later.
                pts = [
                    (cx, cy-scale),
                    (cx+scale*.18, cy-scale*.32),
                    (cx+scale*.78, cy+scale*.12),
                    (cx+scale*.40, cy+scale*.22),
                    (cx+scale*.28, cy+scale*.68),
                    (cx, cy+scale*.48),
                    (cx-scale*.28, cy+scale*.68),
                    (cx-scale*.40, cy+scale*.22),
                    (cx-scale*.78, cy+scale*.12),
                    (cx-scale*.18, cy-scale*.32),
                ]
                flat = [v for pt in pts for v in pt]
                canvas.create_polygon(*flat, outline=C["green2"], fill="", width=2)
                canvas.create_line(cx, cy-scale*.9, cx, cy+scale*.52, fill="#39744d", width=1)
                canvas.create_oval(cx-scale*.72, cy-scale*.72, cx+scale*.72, cy+scale*.72,
                                   outline="#21492f", width=1)
                ship_name = str(getattr(self.state_data, "ship", "-") or "-")
                canvas.create_text(8, h-8, text=f"FRAME // {ship_name.upper()}", anchor="sw",
                                   fill=C["green"], font=self._retro_font("micro_bold"))
                canvas.create_text(w-8, 8, text="FRAME SCHEMATIC // ASSET READY", anchor="ne",
                                   fill=C["dim"], font=self._retro_font("micro"))
            except Exception:
                pass

    def _refresh_live_dashboard(self):
        """Project central Bridge state into the styled Live dashboard."""
        if not hasattr(self, "live_bridge_state_var"):
            return
        C = self.live_palette
        s = self.state_data
        st = s.status or {}

        self.live_commander_var.set(str(s.commander or "-"))
        ship_display = str(s.ship or "-")
        if getattr(s, "ship_name", None):
            ship_display = f"{s.ship_name} // {s.ship}"
        self.live_ship_identity_var.set(ship_display)
        self.live_system_var.set(str(s.system or "-"))
        self.live_station_var.set(str(s.station or "-") if str(s.station or "-") != "-" else "IN FLIGHT")

        if s.flag("Docked"):
            game_state = "DOCKED"
        elif s.flag("Supercruise"):
            game_state = "SUPERCRUISE"
        elif s.flag("FSD Charging"):
            game_state = "FSD CHARGING"
        else:
            game_state = "NORMAL FLIGHT"
        self.live_game_state_var.set(game_state)

        # Bridge ownership/state. Priority mirrors the pilot-facing importance.
        if getattr(self, "egress_phase", "IDLE") != "IDLE":
            bstate, bmsg, level = "EMERGENCY EGRESS", str(getattr(self, "egress_status", "Emergency sequence active.")), "bad"
        elif getattr(self, "native_command_busy", False):
            bstate = str(getattr(self, "native_command_name", "COMMAND RUNNING") or "COMMAND RUNNING").upper()
            bmsg = str(getattr(self, "native_command_status", "Bridge owns cockpit controls."))
            level = "warn"
        elif getattr(self, "station_automation_busy", False):
            bstate = "SHIP SERVICES"
            bmsg = str(getattr(self, "station_automation_status", "Station maintenance running."))
            level = "warn"
        elif getattr(self, "voice_input_recording", False):
            bstate, bmsg, level = "LISTENING", "PTT active. Listening for your command.", "ok"
        elif getattr(self, "copilot_busy", False):
            bstate, bmsg, level = "AI THINKING", "Luna is processing your request.", "warn"
        elif str(getattr(self.voice_engine, "status", "")).startswith("SPEAKING"):
            bstate, bmsg, level = "AI SPEAKING", str(self.voice_engine.status), "warn"
        else:
            bstate, bmsg, level = "IDLE", "Ready for your command, Commander.", "ok"
        self.live_bridge_state_var.set(bstate)
        self.live_bridge_message_var.set(bmsg)
        banner_colors = {
            "ok": ("#244c31", "#b8ffd0"),
            "warn": ("#5a431d", "#ffe0a0"),
            "bad": ("#632c28", "#ffd0ca"),
        }
        bg, fg = banner_colors[level]
        self.live_bridge_state_label.configure(bg=bg, fg=fg)
        self.live_header_state_label.configure(
            text="SYSTEMS ONLINE" if level == "ok" else bstate,
            fg=C["green"] if level == "ok" else (C["amber"] if level == "warn" else C["red"])
        )

        # Ship status
        hull = getattr(s, "hull_health", None)
        self.live_hull_var.set("UNKNOWN" if hull is None else f"{float(hull)*100:.0f}%")
        self.live_shield_var.set("UP" if s.flag("Shields Up") else "DOWN")
        fuel = st.get("Fuel")
        if isinstance(fuel, dict) and fuel.get("FuelMain") is not None:
            fmain = float(fuel.get("FuelMain") or 0.0)
            cap = float(getattr(s, "fuel_capacity_main", 0.0) or 0.0)
            self.live_fuel_var.set(f"{fmain:.1f} t" + (f" // {fmain/cap*100:.0f}%" if cap > 0 else ""))
        else:
            self.live_fuel_var.set("-")
        self.live_pips_var.set(self.vars.get("pips", tk.StringVar(value="-")).get())
        cap = getattr(s, "cargo_capacity", None)
        cargo = int(getattr(s, "cargo_count", 0) or 0)
        self.live_cargo_var.set(f"{cargo:,} / {int(cap):,} t" if cap is not None else f"{cargo:,} t")
        self.live_fsd_var.set(self.vars.get("fsd", tk.StringVar(value="-")).get())
        self.live_gear_var.set("DOWN" if s.flag("Landing Gear") else "UP")
        self.live_hardpoints_var.set("DEPLOYED" if s.flag("Hardpoints") else "RETRACTED")

        # Color only meaningful exceptions. Green means normal/ready, not simply ON.
        self.live_status_value_labels["hull"].configure(fg=C["red"] if hull is not None and hull < .35 else (C["amber"] if hull is not None and hull < .65 else C["green"]))
        self.live_status_value_labels["shields"].configure(fg=C["green"] if s.flag("Shields Up") else C["red"])
        self.live_status_value_labels["fuel"].configure(fg=C["red"] if s.flag("Low Fuel") else C["green"])
        self.live_status_value_labels["fsd"].configure(fg=C["amber"] if s.flag("FSD Mass Locked") or s.flag("FSD Cooldown") else C["green"])
        self.live_status_value_labels["gear"].configure(fg=C["amber"] if s.flag("Landing Gear") and not s.flag("Docked") else C["green"])
        self.live_status_value_labels["hardpoints"].configure(fg=C["amber"] if s.flag("Hardpoints") else C["green"])

        # System health indicators
        self._live_set_system_indicator("telemetry", "ONLINE" if s.journal_connected and s.status_connected else "CHECK", "ok" if s.journal_connected and s.status_connected else "bad")
        ai_key = bool(os.environ.get("OPENAI_API_KEY"))
        self._live_set_system_indicator("ai", "READY" if ai_key and not self.copilot_busy else ("THINKING" if self.copilot_busy else "NO KEY"), "ok" if ai_key and not self.copilot_busy else ("warn" if self.copilot_busy else "bad"))
        ptt = self.controller_bindings.get("push_to_talk")
        self._live_set_system_indicator("voice", "READY" if isinstance(ptt, dict) else "MAP PTT", "ok" if isinstance(ptt, dict) else "bad")
        audio_ok = SOUNDDEVICE_AVAILABLE and bool(getattr(self, "audio_output_device_var", None))
        self._live_set_system_indicator("audio", "READY" if audio_ok else "CHECK", "ok" if audio_ok else "warn")
        controller_ok = bool(getattr(self, "controller_manager", None) and self.controller_manager.devices_snapshot())
        self._live_set_system_indicator("controllers", "DETECTED" if controller_ok else "CHECK", "ok" if controller_ok else "warn")
        try:
            _, missing = self._setup_elite_binding_rows()
        except Exception:
            missing = ["unknown"]
        self._live_set_system_indicator("bindings", "OK" if not missing else f"{len(missing)} MISSING", "ok" if not missing else "bad")
        self._live_set_system_indicator("pips", "ACTIVE" if bool(self.dynamic_pips_var.get()) else "OFF", "ok" if bool(self.dynamic_pips_var.get()) else "info")
        services_on = any((bool(self.auto_refuel_var.get()), bool(self.auto_repair_var.get()), bool(self.auto_rearm_var.get())))
        self._live_set_system_indicator("services", "READY" if services_on else "OFF", "ok" if services_on else "info")
        active_rules = sum(1 for v in (getattr(self, "ai_session_rules", {}) or {}).values() if v)
        self._live_set_system_indicator("rules", f"{active_rules} ACTIVE" if active_rules else "NONE", "ok" if active_rules else "info")

        # Route / voice / cost
        dest = str(getattr(s, "nav_route_destination", "-") or "-")
        target = str(getattr(s, "nav_target_system", "-") or "-")
        if dest not in ("", "-"):
            self.live_destination_var.set(dest)
            self.live_destination_detail_var.set(f"FSD target: {target if target not in ('','-') else dest}  //  route armed")
        elif target not in ("", "-"):
            self.live_destination_var.set(target)
            self.live_destination_detail_var.set("FSD target selected // no full route currently reported")
        else:
            self.live_destination_var.set("NO ROUTE")
            self.live_destination_detail_var.set("No navigation route is currently plotted.")

        self.live_voice_var.set("PTT: LISTENING" if getattr(self, "voice_input_recording", False) else ("PTT: READY" if isinstance(ptt, dict) else "PTT: NOT MAPPED"))
        self.live_ai_var.set("LUNA: THINKING" if self.copilot_busy else ("LUNA: READY" if ai_key else "LUNA: API KEY MISSING"))
        estimated = (self.ai_input_tokens / 1_000_000 * AI_INPUT_PER_MILLION + self.ai_output_tokens / 1_000_000 * AI_OUTPUT_PER_MILLION)
        total_tokens = int(self.ai_input_tokens or 0) + int(self.ai_output_tokens or 0)
        self.live_ai_cost_var.set(f"{self.ai_calls} calls  •  {total_tokens:,} tokens\nest. ${estimated:.4f} LLM usage")
        last_ai = str(getattr(self, "ai_spoken", "") or "").strip()
        if last_ai in ("", "-", "NONE", "None"):
            last_ai = str(getattr(self.voice_engine, "last_text", "") or "").strip()
        self.live_last_ai_var.set(last_ai if last_ai not in ("", "-") else "Standing by, Commander.")

        # Alerts and recent events
        alerts = []
        if s.flag("Being Interdicted"):
            alerts.append("INTERDICTION IN PROGRESS")
        if time.time() - float(getattr(s, "last_under_attack", 0.0) or 0.0) < 15:
            alerts.append("RECENT HOSTILE FIRE")
        if s.flag("Overheating"):
            alerts.append("SHIP OVERHEATING")
        if s.flag("Low Fuel"):
            alerts.append("LOW FUEL")
        if s.flag("FSD Mass Locked") and not s.flag("Docked"):
            alerts.append("FSD MASS LOCKED")
        if alerts:
            self.live_alert_var.set("\n".join(f"● {a}" for a in alerts))
            self.live_alert_label.configure(fg=C["red"] if any("FIRE" in a or "INTERDICTION" in a or "OVERHEATING" in a for a in alerts) else C["amber"])
        else:
            self.live_alert_var.set("● No active alerts")
            self.live_alert_label.configure(fg=C["green"])

        if hasattr(self, "live_event_text"):
            lines = list(getattr(s, "event_log", []) or [])[-10:]
            self.live_event_text.configure(state="normal")
            self.live_event_text.delete("1.0", "end")
            self.live_event_text.insert("end", "\n".join(lines) if lines else "No recent journal events.")
            self.live_event_text.see("end")
            self.live_event_text.configure(state="disabled")

        self._draw_live_ship_placeholder()


    def _field_grid(self,parent,fields):
        for r,(label,key) in enumerate(fields):
            ttk.Label(parent,text=label+":",width=22).grid(row=r,column=0,sticky="w",pady=3)
            v=tk.StringVar(value="-")
            self.vars[key]=v
            ttk.Label(parent,textvariable=v,width=64).grid(row=r,column=1,sticky="w",pady=3)

