    def _refresh_bridge_hotkey_status(self):
        if not hasattr(self, "bridge_hotkey_status_var"):
            return
        self.bridge_hotkey_status_var.set(self.bridge_hotkeys.status)

    def show_bridge_hotkey_map(self):
        registered = set(self.bridge_hotkeys.registered)
        lines = [
            "GLOBAL BRIDGE HOTKEYS",
            "These work while Elite has focus and can be mapped directly in Stream Deck.",
            "For safety, Bridge ignores these global shortcuts when Elite is not the foreground window.",
            "",
        ]
        for command_id, display, _vk, label in BRIDGE_HOTKEY_SPECS:
            state = "READY" if command_id in registered else "NOT REGISTERED"
            lines.append(f"{display:<22}  {label}  [{state}]")
        if self.bridge_hotkeys.failures:
            lines.extend([
                "",
                "A NOT REGISTERED shortcut is normally already reserved by Windows or another application.",
            ])
        messagebox.showinfo("Elite AI Bridge - Global Hotkeys", "\n".join(lines))

    def _dispatch_bridge_hotkey(self, command_id, source="HOTKEY"):
        actions = {
            "target_power_plant": self.start_target_power_plant,
            "target_highest_threat": self.start_target_highest_threat,
            "ensure_combat_mode": self.start_ensure_combat_mode,
            "docking_protocol": self.start_docking_protocol,
            "auto_launch": self.start_auto_launch,
            "clear_station_jump": self.start_clear_station_jump,
            "assist_wing_1": lambda: self.start_assist_wing(1),
            "assist_wing_2": lambda: self.start_assist_wing(2),
            "assist_wing_3": lambda: self.start_assist_wing(3),
            "deploy_fighter_1": lambda: self.start_deploy_fighter(1),
            "deploy_fighter_2": lambda: self.start_deploy_fighter(2),
            "recall_fighter": self.start_recall_fighter,
            "wing_nav_lock_1": lambda: self.start_wing_nav_lock(1),
            "wing_nav_lock_2": lambda: self.start_wing_nav_lock(2),
            "wing_nav_lock_3": lambda: self.start_wing_nav_lock(3),
            "emergency_egress": self.start_emergency_egress,
            "cancel_egress": self.cancel_emergency_egress,
            "push_to_talk": self._ptt_keyboard_hotkey,
        }
        action = actions.get(str(command_id))
        if not action:
            return
        label = next((row[3] for row in BRIDGE_HOTKEY_SPECS if row[0] == command_id), command_id)
        source = str(source or "HOTKEY").upper()
        if str(command_id) == "push_to_talk":
            self.bridge_hotkey_last_action = f"{datetime.now().strftime('%H:%M:%S')}  {source} {label}"
            action()
            return
        if not self.key_sender.elite_foreground():
            self.native_command_status = f"{source} {label}: ignored because Elite is not the foreground window."
            self.bridge_hotkey_last_action = f"{datetime.now().strftime('%H:%M:%S')}  IGNORED {source} {label}"
            self._native_command_log(f"{source} IGNORED {label} | Elite not foreground")
            return
        self.bridge_hotkey_last_action = f"{datetime.now().strftime('%H:%M:%S')}  {source} {label}"
        self._native_command_log(f"{source} {label}")
        action()

    def _drain_bridge_hotkeys(self):
        drained = 0
        while drained < 12:
            try:
                command_id = self.bridge_hotkey_queue.get_nowait()
            except queue.Empty:
                break
            drained += 1
            try:
                self._dispatch_bridge_hotkey(command_id)
            except Exception as exc:
                self.native_command_status = f"Hotkey {command_id}: FAILED • {exc}"
                self._native_command_log(f"FAIL HOTKEY {command_id} | {exc}")
        self._refresh_bridge_hotkey_status()

    def _bridge_hotkey_tick(self):
        try:
            self._drain_bridge_hotkeys()
        finally:
            try:
                self.after(50, self._bridge_hotkey_tick)
            except Exception:
                pass

    def _controller_action_label(self, action):
        return next((row[3] for row in BRIDGE_HOTKEY_SPECS if row[0] == action), str(action))

    def _controller_binding_conflict_action(self, binding, except_action=None):
        sig = BridgeControllerManager.control_signature(binding)
        if sig is None:
            return None
        for action, existing in self.controller_bindings.items():
            if action == except_action:
                continue
            if BridgeControllerManager.control_signature(existing) == sig:
                return action
        return None

    def _drain_controller_events(self):
        changed = False
        drained = 0
        while drained < 24:
            try:
                row = self.controller_event_queue.get_nowait()
            except queue.Empty:
                break
            drained += 1
            kind = row.get("type")
            if kind == "trigger":
                action = row.get("action")
                try:
                    self._dispatch_bridge_hotkey(action, source="HOTAS")
                except Exception as exc:
                    self.native_command_status = f"HOTAS {action}: FAILED • {exc}"
                    self._native_command_log(f"FAIL HOTAS {action} | {exc}")
            elif kind == "ptt_down":
                self._start_ptt_recording("HOTAS PTT")
            elif kind == "ptt_up":
                self._stop_ptt_recording()
            elif kind == "captured":
                action = str(row.get("action") or "")
                binding = row.get("binding") if isinstance(row.get("binding"), dict) else None
                if not action or not binding:
                    continue
                conflict = self._controller_binding_conflict_action(binding, except_action=action)
                accept = True
                if conflict:
                    accept = messagebox.askyesno(
                        "Controller Binding Conflict",
                        f"{BridgeControllerManager.binding_label(binding)} on {binding.get('device_name')} is already bound to "
                        f"{self._controller_action_label(conflict)}.\n\nMove that control to {self._controller_action_label(action)}?",
                    )
                    if accept:
                        self.controller_bindings.pop(conflict, None)
                if accept:
                    self.controller_bindings[action] = binding
                    self.controller_manager.set_bindings(self.controller_bindings)
                    self._save_controller_bindings_file()
                    if row.get("ambiguous_device"):
                        self.native_command_status = (
                            f"Controller binding saved for {self._controller_action_label(action)}, but identical connected devices are ambiguous."
                        )
                    else:
                        self.native_command_status = (
                            f"Controller bound: {self._controller_action_label(action)} = "
                            f"{binding.get('device_name')} • {BridgeControllerManager.binding_label(binding)}"
                        )
                    if action == "push_to_talk" and self.startup_splash_status_var is not None:
                        self.startup_splash_status_var.set(
                            f"PTT READY • {binding.get('device_name')} • {BridgeControllerManager.binding_label(binding)}\n"
                            "Required voice control mapped. Startup preflight can continue."
                        )
                    elite_hits = self.bindings.controller_binding_collisions(binding)
                    if elite_hits:
                        elite_text = self.bindings.controller_conflict_display(binding, limit=6)
                        self.native_command_status += f" • WARNING: Elite also uses this control for {elite_text}."
                        messagebox.showwarning(
                            "Elite Binding Conflict",
                            f"Bridge saved this binding, but Elite Dangerous also uses the same physical control for:\n\n{elite_text}\n\n"
                            "The row will stay red until the overlap is removed from either Bridge or Elite.",
                        )
                if self.controller_capture_status_var is not None:
                    self.controller_capture_status_var.set(self.native_command_status)
                changed = True
            elif kind == "devices_changed":
                changed = True
        if changed:
            self._refresh_controller_binding_dialog()
            self.refresh_preferences_widgets()

    def _bridge_controller_tick(self):
        try:
            self._drain_controller_events()
        finally:
            try:
                self.after(60, self._bridge_controller_tick)
            except Exception:
                pass

    def _open_controller_bindings(self):
        if self.controller_dialog is not None:
            try:
                if self.controller_dialog.winfo_exists():
                    self.controller_dialog.lift()
                    self.controller_dialog.focus_force()
                    self._refresh_controller_binding_dialog()
                    return
            except Exception:
                pass
        win = tk.Toplevel(self)
        self.controller_dialog = win
        win.title("Elite AI Bridge - Command Map / Controller Bindings")
        win.geometry("1360x720")
        win.minsize(1080, 560)
        win.transient(self)

        intro = ttk.LabelFrame(win, text="Direct Bridge Controls", padding=10)
        intro.pack(fill="x", padx=10, pady=(10, 8))
        ttk.Label(
            intro,
            text=(
                "Every Bridge action is listed here with its fixed Windows shortcut for Stream Deck/keyboard use and any direct HOTAS/controller binding. "
                "For HOTAS, select an action, click BIND / REBIND, then press one button or POV/hat direction. Bridge stores the SDL device GUID + product name, "
                "not Joystick 1/2 numbering. Axes are intentionally ignored. Any direct-control overlap with the active Elite .binds preset is shown in RED."
            ),
            wraplength=920,
            justify="left",
        ).pack(anchor="w")

        self.controller_capture_status_var = tk.StringVar(value=self.controller_manager.status)
        ttk.Label(intro, textvariable=self.controller_capture_status_var, font=("Segoe UI", 9, "bold"), wraplength=920).pack(anchor="w", pady=(6, 0))

        table_frame = ttk.Frame(win, padding=(10, 0, 10, 0))
        table_frame.pack(fill="both", expand=True)
        cols = ("Action", "Stream Deck / Keyboard", "Controller", "Device", "Status", "Elite Conflict")
        tree = ttk.Treeview(table_frame, columns=cols, show="headings", selectmode="browse")
        self.controller_binding_tree = tree
        widths = {
            "Action": 205, "Stream Deck / Keyboard": 220, "Controller": 145,
            "Device": 285, "Status": 125, "Elite Conflict": 300,
        }
        tree.tag_configure("elite_conflict", foreground="#d11a2a")
        for c in cols:
            tree.heading(c, text=c)
            tree.column(c, width=widths[c], anchor="w")
        scroll = ttk.Scrollbar(table_frame, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=scroll.set)
        tree.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")

        buttons = ttk.Frame(win, padding=10)
        buttons.pack(fill="x")
        ttk.Button(buttons, text="BIND / REBIND", command=self._controller_bind_selected).pack(side="left")
        ttk.Button(buttons, text="CLEAR", command=self._controller_clear_selected).pack(side="left", padx=(8, 0))
        ttk.Button(buttons, text="COPY STREAM DECK HOTKEY", command=self._controller_copy_hotkey_selected).pack(side="left", padx=(8, 0))
        ttk.Button(buttons, text="CANCEL LISTENING", command=self._controller_cancel_capture).pack(side="left", padx=(8, 0))
        ttk.Button(buttons, text="REFRESH DEVICES", command=self._controller_refresh_devices).pack(side="left", padx=(8, 0))
        ttk.Button(buttons, text="CHECK ELITE BINDINGS", command=self._controller_check_elite_bindings).pack(side="left", padx=(8, 0))
        ttk.Button(buttons, text="CLOSE", command=self._close_controller_dialog).pack(side="right")

        devices = ttk.LabelFrame(win, text="Connected Devices", padding=8)
        devices.pack(fill="x", padx=10, pady=(0, 10))
        self.controller_devices_var = tk.StringVar(value="-")
        ttk.Label(devices, textvariable=self.controller_devices_var, wraplength=920, justify="left").pack(anchor="w")

        win.protocol("WM_DELETE_WINDOW", self._close_controller_dialog)
        self._refresh_controller_binding_dialog()

    def _close_controller_dialog(self):
        self.controller_manager.cancel_capture()
        win = self.controller_dialog
        self.controller_dialog = None
        self.controller_capture_status_var = None
        self.controller_binding_tree = None
        self.controller_devices_var = None
        if win is not None:
            try:
                win.destroy()
            except Exception:
                pass

    def _selected_controller_action(self):
        tree = getattr(self, "controller_binding_tree", None)
        if tree is None:
            return None
        sel = tree.selection()
        return str(sel[0]) if sel else None

    def _controller_copy_hotkey_selected(self):
        action = self._selected_controller_action()
        if not action:
            messagebox.showinfo("Command Map", "Select a Bridge action first.")
            return
        row = next((r for r in BRIDGE_HOTKEY_SPECS if r[0] == action), None)
        if not row:
            return
        display = str(row[1])
        label = str(row[3])
        try:
            self.clipboard_clear()
            self.clipboard_append(display)
            self.update()
            if self.controller_capture_status_var is not None:
                self.controller_capture_status_var.set(f"Copied {label} Stream Deck hotkey: {display}")
        except Exception as exc:
            messagebox.showerror("Command Map", f"Could not copy the hotkey: {exc}")

    def _controller_bind_selected(self):
        action = self._selected_controller_action()
        if not action:
            messagebox.showinfo("Controller Binding", "Select a Bridge action first.")
            return
        if not self.controller_manager.begin_capture(action):
            messagebox.showerror("Controller Binding", self.controller_manager.status)
            return
        text = f"Listening for {self._controller_action_label(action)}. Press one controller button or hat direction..."
        if self.controller_capture_status_var is not None:
            self.controller_capture_status_var.set(text)

    def _controller_clear_selected(self):
        action = self._selected_controller_action()
        if not action:
            messagebox.showinfo("Controller Binding", "Select a Bridge action first.")
            return
        if action in self.controller_bindings:
            self.controller_bindings.pop(action, None)
            self.controller_manager.set_bindings(self.controller_bindings)
            self._save_controller_bindings_file()
        self._refresh_controller_binding_dialog()
        self.refresh_preferences_widgets()

    def _controller_cancel_capture(self):
        self.controller_manager.cancel_capture()
        if self.controller_capture_status_var is not None:
            self.controller_capture_status_var.set(self.controller_manager.status)

    def _controller_refresh_devices(self):
        # The listener rescans every second. This button simply pumps the UI and
        # makes the current health state immediately visible.
        self._refresh_controller_binding_dialog()
        if self.controller_capture_status_var is not None:
            self.controller_capture_status_var.set(self.controller_manager.status)

    def _controller_check_elite_bindings(self):
        ok = self.bindings.load()
        if ok:
            conflicts = 0
            for binding in self.controller_bindings.values():
                if self.bindings.controller_binding_collisions(binding):
                    conflicts += 1
            path = str(self.bindings.path or "-")
            self.bindings_watch_last_reload = datetime.now().strftime("%H:%M:%S")
            self.bindings_watch_status = f"MANUAL CONTROLLER CHECK {self.bindings.preset}"
            text = f"Elite bindings checked: {conflicts} Bridge control conflict(s) • {path}"
        else:
            text = self.bindings.error or "Elite bindings check failed."
        if self.controller_capture_status_var is not None:
            self.controller_capture_status_var.set(text)
        self._refresh_controller_binding_dialog()
        self.refresh_preferences_widgets()

    def _refresh_controller_binding_dialog(self):
        tree = getattr(self, "controller_binding_tree", None)
        if tree is not None:
            selected = tree.selection()
            for iid in tree.get_children(""):
                tree.delete(iid)
            registered = set(self.bridge_hotkeys.registered)
            for action, display, _vk, label in BRIDGE_HOTKEY_SPECS:
                binding = self.controller_bindings.get(action)
                control = BridgeControllerManager.binding_label(binding)
                device = str(binding.get("device_name") or "-") if isinstance(binding, dict) else "-"
                status = self.controller_manager.binding_status(binding) if binding else "UNBOUND"
                elite_conflict = self.bindings.controller_conflict_display(binding) if binding else ""
                hotkey_state = "READY" if action in registered else "NOT REGISTERED"
                hotkey_text = f"{display}  [{hotkey_state}]"
                tags = ()
                if elite_conflict:
                    status = "ELITE CONFLICT"
                    tags = ("elite_conflict",)
                tree.insert(
                    "", "end", iid=action,
                    values=(label, hotkey_text, control, device, status, elite_conflict or "-"),
                    tags=tags,
                )
            if selected and tree.exists(selected[0]):
                tree.selection_set(selected[0])
                tree.see(selected[0])
        if getattr(self, "controller_devices_var", None) is not None:
            rows = self.controller_manager.devices_snapshot()
            if not rows:
                text = self.controller_manager.connected_summary()
            else:
                parts = []
                for row in rows:
                    suffix = " • AMBIGUOUS IDENTICAL DEVICE" if row.get("ambiguous") else ""
                    guid = str(row.get("guid") or "")
                    guid_short = guid[:12] + "..." if len(guid) > 15 else guid
                    parts.append(
                        f"{row.get('name')} • GUID {guid_short or 'unknown'} • "
                        f"{row.get('buttons')} buttons / {row.get('hats')} hats{suffix}"
                    )
                text = "\n".join(parts)
            self.controller_devices_var.set(text)
        if self.controller_capture_status_var is not None and not self.controller_manager.capture_snapshot():
            self.controller_capture_status_var.set(self.controller_manager.status)

    def _native_command_log(self, text):
        line = f"{datetime.now().strftime('%H:%M:%S')}  {text}"
        self.native_command_history.append(line)
        self.state_data.observer_note("NATIVE_COMMAND", text)

    def _native_set_status(self, text):
        self.native_command_status = str(text)
        self._native_command_log(str(text))

    def _native_cancel_guard(self):
        if self.native_command_busy and self.native_command_cancel_event.is_set():
            raise NativeCommandCancelled(self.native_command_cancel_reason or "cancelled")

    def _wait_for(self, predicate, timeout=2.0, interval=0.05):
        deadline = time.monotonic() + max(0.0, float(timeout))
        while time.monotonic() < deadline:
            self._native_cancel_guard()
            try:
                if predicate():
                    return True
            except NativeCommandCancelled:
                raise
            except Exception:
                pass
            time.sleep(max(0.01, float(interval)))
        self._native_cancel_guard()
        try:
            return bool(predicate())
        except NativeCommandCancelled:
            raise
        except Exception:
            return False

    def _native_binding(self, action):
        binding = self.bindings.keyboard_binding(action)
        if not binding:
            raise RuntimeError(f"Missing Elite keyboard binding: {BindingsManager.DISPLAY_NAMES.get(action, action)}")
        # copy so a live bindings reload cannot mutate our in-flight snapshot
        return {"action": binding.get("action"), "slot": binding.get("slot"), "key": binding.get("key"), "modifiers": list(binding.get("modifiers") or [])}

    def _native_tap(self, binding, pause=0.10):
        self._native_cancel_guard()
        if not self.key_sender.elite_foreground():
            raise RuntimeError("Elite is not the foreground window.")
        self.key_sender.send_binding(binding)
        if pause:
            deadline = time.monotonic() + float(pause)
            while time.monotonic() < deadline:
                self._native_cancel_guard()
                time.sleep(min(0.04, max(0.0, deadline - time.monotonic())))

    def _native_begin(self, name, worker):
        if self.egress_phase != "IDLE":
            self.native_command_status = f"BUSY: Emergency Egress owns cockpit controls; {name} was not started."
            self._native_command_log(f"IGNORED {name} | Emergency Egress owns cockpit controls")
            return
        if self.station_automation_busy:
            service = self.station_automation_current_service
            detail = f" ({service})" if service not in ("", "-") else ""
            self.native_command_status = f"BUSY: station maintenance is running{detail}; {name} was not started."
            self._native_command_log(f"IGNORED {name} | station maintenance owns cockpit controls{detail}")
            return
        if self.native_command_busy:
            self.native_command_status = f"BUSY: {self.native_command_name} is already running."
            return
        # Button clicks necessarily put the Bridge in the foreground. Bring Elite
        # forward here on Tk's UI/input thread before the worker starts. Windows
        # is much more likely to honor SetForegroundWindow from the thread that
        # received the user's click than from a later background worker.
        try:
            self.key_sender.focus_elite()
        except Exception as exc:
            self.native_command_status = f"{name}: FAILED to focus Elite • {exc}"
            self._native_command_log(f"FAIL {name} | focus | {exc}")
            return
        self.native_command_busy = True
        self.native_command_name = str(name)
        self.native_command_started_mono = time.monotonic()
        self.native_command_generation += 1
        generation = self.native_command_generation
        self.native_command_cancel_event = threading.Event()
        self.native_command_cancel_reason = "-"
        self.native_command_status = f"{name}: starting..."
        self._native_command_log(f"START {name} | owner generation={generation}")

        def run():
            try:
                worker()
            except NativeCommandCancelled as exc:
                if name == "Auto Launch" and self.station_safety_pips_context == "AUTO_LAUNCH":
                    self._station_safety_pips_release("Auto Launch cancelled")
                elif name == "Docking Protocol" and self.station_safety_pips_context == "DOCKING_COMMAND":
                    self._station_safety_pips_release("Docking Protocol cancelled")
                self.native_command_status = f"{name}: CANCELLED • {exc}"
                self._native_command_log(f"CANCELLED {name} | {exc}")
            except Exception as exc:
                if name == "Auto Launch" and self.station_safety_pips_context == "AUTO_LAUNCH":
                    self._station_safety_pips_release("Auto Launch command failed")
                elif name == "Docking Protocol" and self.station_safety_pips_context == "DOCKING_COMMAND":
                    self._station_safety_pips_release("Docking Protocol command failed")
                self.native_command_status = f"{name}: FAILED • {exc}"
                self._native_command_log(f"FAIL {name} | {exc}")
            finally:
                if self.native_command_generation == generation:
                    self.native_command_busy = False
                    self.native_command_name = "-"
                    self.native_command_cancel_reason = "-"
        threading.Thread(target=run, name=f"EliteBridge-{name}", daemon=True).start()

    def cancel_current_command(self, reason="Pilot cancel"):
        reason = str(reason or "Pilot cancel")
        if self.egress_phase != "IDLE":
            self.cancel_emergency_egress()
            self._native_command_log(f"CANCEL CURRENT | Emergency Egress | {reason}")
            return True
        if self.station_automation_busy:
            self.station_automation_generation += 1
            self.station_automation_status = "CANCEL REQUESTED • station maintenance will stop at its next safe checkpoint."
            self._station_automation_log(f"Cancel requested: {reason}")
            return True
        if not self.native_command_busy:
            self.native_command_status = "No cockpit command is currently running."
            return False
        name = self.native_command_name
        self.native_command_cancel_reason = reason
        self.native_command_cancel_event.set()
        self.native_command_status = f"CANCEL REQUESTED • {name} • waiting for safe worker exit."
        self._native_command_log(f"CANCEL REQUESTED {name} | {self.native_command_cancel_reason}")
        return True

    def _native_prepare_cockpit(self, command_name):
        if not self.key_sender.elite_foreground():
            title = self.key_sender.focus_elite()
        else:
            title = self.key_sender.last_window_title or "Elite - Dangerous"
        # Let Status.json catch up after Windows focus changes.
        time.sleep(0.20)
        gui = int((self.state_data.status or {}).get("GuiFocus", 0) or 0)
        if gui != 0:
            raise RuntimeError(f"{command_name} requires normal cockpit view (GuiFocus 0); current GuiFocus={gui}.")
        return title

    def _ensure_combat_mode(self, command_name="Combat Command"):
        """Ensure Elite is in Combat HUD mode using Status.json as truth."""
        s = self.state_data
        if not s.flag("Analysis Mode"):
            return False
        toggle = self._native_binding("PlayerHUDModeToggle")
        self.native_command_status = f"{command_name}: switching ANALYSIS -> COMBAT mode..."
        self._native_tap(toggle, 0.12)
        if not self._wait_for(lambda: not s.flag("Analysis Mode"), 2.5, 0.05):
            raise RuntimeError("Combat Mode toggle was sent, but Status.json still reports Analysis Mode.")
        self._native_command_log(f"MODE {command_name} | Analysis -> Combat confirmed")
        return True

    def start_ensure_combat_mode(self):
        self._native_begin("Ensure Combat Mode", self._ensure_combat_mode_worker)

    def _ensure_combat_mode_worker(self):
        self._native_prepare_cockpit("Ensure Combat Mode")
        changed = self._ensure_combat_mode("Ensure Combat Mode")
        if changed:
            self.native_command_status = "Ensure Combat Mode: CONFIRMED • Combat HUD active."
            self._native_command_log("SUCCESS Ensure Combat Mode | switched from Analysis")
        else:
            self.native_command_status = "Ensure Combat Mode: already in Combat HUD mode."
            self._native_command_log("SUCCESS Ensure Combat Mode | already combat")

    def start_target_highest_threat(self):
        self._native_begin("Target Highest Threat", self._target_highest_threat_worker)

    def _target_highest_threat_worker(self):
        s = self.state_data
        if s.flag("Docked") or s.flag("Supercruise") or s.flag("FSD Jump"):
            raise RuntimeError("Highest Threat targeting is only attempted in normal-space flight.")
        self._native_prepare_cockpit("Target Highest Threat")
        self._ensure_combat_mode("Target Highest Threat")
        bind = self._native_binding("SelectHighestThreat")
        before_rev = int(getattr(s, "target_revision", 0) or 0)
        before_target = str(s.target)
        self._native_tap(bind, 0.10)
        self._wait_for(lambda: int(getattr(s, "target_revision", 0) or 0) > before_rev, 1.5, 0.05)
        target = str(s.target)
        if target not in ("", "-"):
            changed = "selected" if target != before_target else "current target after command"
            self.native_command_status = f"Target Highest Threat: {changed} • {target}."
            self._native_command_log(f"SUCCESS Target Highest Threat | {target}")
        else:
            self.native_command_status = "Target Highest Threat: command sent; Elite reported no ship target."
            self._native_command_log("SENT Target Highest Threat | no ShipTargeted confirmation")

    @staticmethod
    def _wing_target_action(wing_number):
        n = max(1, min(3, int(wing_number)))
        return n, f"TargetWingman{n-1}"

    def _target_wingman_for_native_command(self, wing_number, command_name):
        s = self.state_data
        if not s.flag("In Wing"):
            raise RuntimeError("Elite Status.json says you are not currently in a wing/team.")
        n, action = self._wing_target_action(wing_number)
        bind = self._native_binding(action)
        before_rev = int(getattr(s, "target_revision", 0) or 0)
        self.native_command_status = f"{command_name}: targeting Wing {n}..."
        self._native_tap(bind, 0.12)
        # ShipTargeted usually arrives quickly, but targeting a wingmate is still
        # useful even if the journal does not emit a fresh row. Give Elite a
        # deterministic settle window before the next wing command.
        changed = self._wait_for(lambda: int(getattr(s, "target_revision", 0) or 0) > before_rev, 0.9, 0.05)
        if not changed:
            time.sleep(0.22)
        target_label = str(s.target) if changed and str(s.target) not in ("", "-") else f"Wing {n}"
        return n, target_label

    def start_assist_wing(self, wing_number):
        n = max(1, min(3, int(wing_number)))
        self._native_begin(f"Assist Wing {n}", lambda: self._assist_wing_worker(n))

    def _assist_wing_worker(self, wing_number):
        s = self.state_data
        if s.flag("Docked") or s.flag("Supercruise") or s.flag("FSD Jump"):
            raise RuntimeError("Wing Assist is only attempted in normal-space flight.")
        self._native_prepare_cockpit(f"Assist Wing {wing_number}")
        self._ensure_combat_mode(f"Assist Wing {wing_number}")
        n, wing_target = self._target_wingman_for_native_command(wing_number, f"Assist Wing {wing_number}")
        select_targets_target = self._native_binding("SelectTargetsTarget")
        before_rev = int(getattr(s, "target_revision", 0) or 0)
        self.native_command_status = f"Assist Wing {n}: {wing_target} selected; targeting their target..."
        self._native_tap(select_targets_target, 0.10)
        self._wait_for(lambda: int(getattr(s, "target_revision", 0) or 0) > before_rev, 1.5, 0.05)
        final_target = str(s.target)
        if final_target not in ("", "-"):
            self.native_command_status = f"Assist Wing {n}: target-of-target selected • {final_target}."
            self._native_command_log(f"SUCCESS Assist Wing {n} | {final_target}")
        else:
            self.native_command_status = f"Assist Wing {n}: target-of-target command sent; no ShipTargeted confirmation."
            self._native_command_log(f"SENT Assist Wing {n} | no ShipTargeted confirmation")

    def start_wing_nav_lock(self, wing_number):
        n = max(1, min(3, int(wing_number)))
        self._native_begin(f"Wing Nav Lock {n}", lambda: self._wing_nav_lock_worker(n))

    def _wing_nav_lock_worker(self, wing_number):
        self._native_prepare_cockpit(f"Wing Nav Lock {wing_number}")
        n, wing_target = self._target_wingman_for_native_command(wing_number, f"Wing Nav Lock {wing_number}")
        navlock = self._native_binding("WingNavLock")
        self._native_tap(navlock, 0.10)
        # Elite exposes the input but not a reliable journal/status bit for the
        # resulting nav-lock toggle, so report exactly what we can prove.
        self.native_command_status = f"Wing Nav Lock {n}: toggle sent for {wing_target}."
        self._native_command_log(f"SENT Wing Nav Lock {n} | target={wing_target}")

    def start_deploy_fighter(self, fighter_number):
        fighter_number = 1 if int(fighter_number) == 1 else 2
        self._native_begin(f"Deploy Fighter {fighter_number}", lambda: self._deploy_fighter_worker(fighter_number))

    def _deploy_fighter_worker(self, fighter_number):
        s = self.state_data
        if s.flag("Docked") or s.flag("Supercruise") or s.flag("FSD Jump"):
            raise RuntimeError("fighter deployment is only attempted in normal-space flight.")
        binds = {a: self._native_binding(a) for a in (
            "FocusRadarPanel", "CyclePreviousPanel", "CycleNextPanel",
            "UI_Right", "UI_Select", "UI_Up", "UI_Down"
        )}
        start_launch_count = s.fighter_launch_count
        self._native_prepare_cockpit(f"Deploy Fighter {fighter_number}")
        self._ensure_combat_mode(f"Deploy Fighter {fighter_number}")
        self._native_tap(binds["FocusRadarPanel"], 0.15)
        if not self._wait_for(lambda: int((s.status or {}).get("GuiFocus", 0) or 0) == 4, 2.0):
            raise RuntimeError("Role Panel did not become active (GuiFocus 4).")
        time.sleep(0.15)
        for _ in range(3):
            self._native_tap(binds["CyclePreviousPanel"], 0.18)
        self._native_tap(binds["CycleNextPanel"], 0.28)
        self._native_tap(binds["UI_Right"], 0.10)
        if fighter_number == 2:
            self._native_tap(binds["UI_Down"], 0.10)
        self._native_tap(binds["UI_Select"], 0.45)
        reset_count = 4 if fighter_number == 1 else 3
        for _ in range(reset_count):
            self._native_tap(binds["UI_Up"], 0.18)
        self._native_tap(binds["UI_Down"], 0.16)
        self._native_tap(binds["UI_Select"], 0.70)
        self._native_tap(binds["FocusRadarPanel"], 0.10)
        launched = self._wait_for(
            lambda: s.fighter_launch_count > start_launch_count,
            6.0, 0.10
        )
        if launched:
            self.native_command_status = f"Deploy Fighter {fighter_number}: CONFIRMED by LaunchFighter journal event."
            self._native_command_log(f"SUCCESS Deploy Fighter {fighter_number} | LaunchFighter confirmed")
        else:
            self.native_command_status = f"Deploy Fighter {fighter_number}: sequence sent, but no LaunchFighter confirmation arrived."
            self._native_command_log(f"UNCONFIRMED Deploy Fighter {fighter_number} | no LaunchFighter event")

    def start_recall_fighter(self):
        self._native_begin("Recall Fighter", self._recall_fighter_worker)

    def _recall_fighter_worker(self):
        bind = self._native_binding("OrderRequestDock")
        self._native_prepare_cockpit("Recall Fighter")
        self._native_tap(bind, 0.10)
        self.native_command_status = "Recall Fighter: docking order sent. DockFighter journal event will confirm when the fighter actually docks."
        self._native_command_log(f"RECALL ORDER SENT | {self.bindings.binding_display('OrderRequestDock')}")

    def start_target_power_plant(self):
        self._native_begin("Target Power Plant", self._target_power_plant_worker)

    @staticmethod
    def _is_power_plant_name(text):
        t = str(text or "").strip().casefold()
        return t == "power plant" or "power plant" in t or "powerplant" in t

    def _target_power_plant_worker(self):
        s = self.state_data
        self._native_prepare_cockpit("Target Power Plant")
        self._ensure_combat_mode("Target Power Plant")
        if s.target in ("", "-"):
            raise RuntimeError("no ship target is currently locked.")
        initial_target = str(s.target)
        # Preserve the old VoiceAttack safety behavior: never subsystem-cycle a Clean ship.
        if str(s.target_legal or "").casefold() == "clean":
            raise RuntimeError(f"refused: {initial_target} is CLEAN.")
        if int(getattr(s, "target_scan_stage", 0) or 0) < 3:
            self.native_command_status = f"Target Power Plant: waiting for full target scan of {initial_target}..."
            # ShipTargeted progressively changes its display identity while scan
            # data arrives (e.g. ship type -> pilot / ship). Only a lost lock
            # counts as failure during this phase.
            self._wait_for(lambda: int(getattr(s, "target_scan_stage", 0) or 0) >= 3 or s.target in ("", "-"), 8.0, 0.10)
        if s.target in ("", "-"):
            raise RuntimeError("target was lost while waiting for scan completion.")
        if int(getattr(s, "target_scan_stage", 0) or 0) < 3:
            raise RuntimeError("target has not reached ShipTargeted ScanStage 3.")
        target_name = str(s.target)
        if str(s.target_legal or "").casefold() == "clean":
            raise RuntimeError(f"refused: {target_name} is CLEAN.")
        if self._is_power_plant_name(s.target_subsystem):
            self.native_command_status = f"Target Power Plant: already selected on {target_name}."
            self._native_command_log(f"SUCCESS Target Power Plant | already selected | {target_name}")
            return
        cycle = self._native_binding("CyclePreviousSubsystem")
        for attempt in range(1, 19):
            if s.target != target_name or s.target in ("", "-"):
                raise RuntimeError("target changed or was lost during subsystem search.")
            if str(s.target_legal or "").casefold() == "clean":
                raise RuntimeError("target legal state changed to CLEAN; search stopped.")
            before_rev = int(getattr(s, "target_subsystem_revision", 0) or 0)
            self.native_command_status = f"Target Power Plant: cycling subsystem {attempt}/18 on {target_name}..."
            self._native_tap(cycle, 0.05)
            # VoiceAttack's proven routine was intentionally slow. We wait for the
            # journal subsystem update first, but still allow up to ~2.8 s before
            # sending another cycle command.
            self._wait_for(lambda: int(getattr(s, "target_subsystem_revision", 0) or 0) > before_rev or s.target != target_name, 2.8, 0.08)
            if s.target != target_name:
                raise RuntimeError("target changed during subsystem search.")
            if self._is_power_plant_name(s.target_subsystem):
                self.native_command_status = f"Target Power Plant: CONFIRMED • {target_name} • {s.target_subsystem}."
                self._native_command_log(f"SUCCESS Target Power Plant | {target_name} | cycles={attempt}")
                return
        raise RuntimeError(f"Power Plant was not confirmed after 18 subsystem cycles on {target_name}.")

    def _request_docking_bindings(self):
        return {a: self._native_binding(a) for a in (
            "FocusLeftPanel", "UI_Back", "UI_Left", "UI_Right", "UI_Select", "CyclePreviousPanel"
        )}

    def _request_docking_tab_sweep(self, binds, start_revision, max_tabs=5):
        """Search the left-panel tabs using the proven VoiceAttack interaction block.

        Elite exposes GuiFocus for the left panel, but not the currently selected
        tab. Previous/next tab controls wrap, so there is no safe keyboard-only
        way to force a tab "home". Instead we reproduce the proven interaction
        block on one tab at a time and check the journal immediately after every
        Select.

        IMPORTANT: a real docking response can be DockingRequested,
        DockingGranted, DockingDenied, or DockingCancelled. In particular Elite
        may emit DockingDenied directly when the ship is too far away, without a
        preceding DockingRequested event. Any fresh docking response proves the
        Contacts/request interaction was reached, so the sweep must stop there.
        """
        s = self.state_data
        self._native_tap(binds["FocusLeftPanel"], 0.08)
        if not self._wait_for(lambda: int((s.status or {}).get("GuiFocus", 0) or 0) == 2, 1.2, 0.04):
            raise RuntimeError("External panel did not become active (GuiFocus 2).")

        self._native_command_log(f"Docking TAB SWEEP | starting from pilot's current left-panel tab | max={int(max_tabs)}")
        docking_events = {"DockingRequested", "DockingGranted", "DockingDenied", "DockingCancelled"}
        seen_revision = int(start_revision or 0)

        for attempt in range(1, int(max_tabs) + 1):
            if int((s.status or {}).get("GuiFocus", 0) or 0) != 2:
                # A previous Select may have entered a nested view. Directly
                # refocus the external panel instead of using UI Back, which can
                # close the panel and was the v0.12.58 failure mode.
                self._native_tap(binds["FocusLeftPanel"], 0.08)
                self._wait_for(lambda: int((s.status or {}).get("GuiFocus", 0) or 0) == 2, 0.6, 0.04)

            self.native_command_status = f"Request Docking: checking left-panel tab {attempt}/{int(max_tabs)}..."
            self._native_command_log(f"Docking TAB SWEEP | attempt {attempt}/{int(max_tabs)}")

            # Preserve the small VoiceAttack interaction block that has already
            # worked in-game. Verify ANY fresh docking response immediately,
            # before moving to another tab.
            before_revision = max(seen_revision, int(getattr(s, "docking_revision", 0) or 0))
            self._native_tap(binds["UI_Left"], 0.10)
            self._native_tap(binds["UI_Right"], 0.10)
            self._native_tap(binds["UI_Select"], 0.18)

            got_response = self._wait_for(
                lambda: (int(getattr(s, "docking_revision", 0) or 0) > before_revision and
                         str(getattr(s, "last_docking_event", "") or "") in docking_events),
                0.85, 0.04
            )
            if got_response:
                event = str(getattr(s, "last_docking_event", "") or "DockingRequested")
                seen_revision = int(getattr(s, "docking_revision", 0) or 0)
                self._native_command_log(f"Docking TAB SWEEP | {event} confirmed on attempt {attempt}")
                # The journal proved we reached Request Docking. Close the panel;
                # do not continue sweeping and accidentally submit more requests.
                try:
                    self._native_tap(binds["UI_Back"], 0.08)
                except Exception:
                    pass
                return event

            if attempt < int(max_tabs):
                self._native_tap(binds["CyclePreviousPanel"], 0.10)
                time.sleep(0.06)

        return None

    def _request_docking_sequence(self, binds=None):
        s = self.state_data
        binds = binds or self._request_docking_bindings()
        start_revision = int(getattr(s, "docking_revision", 0) or 0)
        start_granted = s.docking_granted_count
        start_denied = s.docking_denied_count
        start_cancelled = s.docking_cancelled_count

        # v0.12.58 tried to normalize with repeated UI Back, which could close
        # the panel. The tab sweep instead searches from the pilot's current tab.
        # v0.12.60 treats ANY fresh docking response as proof that the request
        # control was reached. This matters because an out-of-range station may
        # answer with DockingDenied directly and never emit DockingRequested.
        response = self._request_docking_tab_sweep(binds, start_revision, max_tabs=5)
        if not response:
            try:
                if int((s.status or {}).get("GuiFocus", 0) or 0) != 0:
                    self._native_tap(binds["UI_Back"], 0.06)
            except Exception:
                pass
            raise RuntimeError("no docking response after sweeping the left-panel tabs (possibly station contact unavailable or Elite UI layout changed).")

        station = s.last_docking_station
        if response == "DockingGranted":
            return "DockingGranted", station
        if response == "DockingDenied":
            return "DockingDenied", station
        if response == "DockingCancelled":
            return "DockingCancelled", station

        # DockingRequested was seen. Give Elite a short window for the normal
        # grant/deny/cancel result. If none follows, preserve REQUESTED state.
        self.native_command_status = f"Request Docking: request sent to {station}. Waiting for response..."
        if self._wait_for(
            lambda: (s.docking_granted_count > start_granted or
                     s.docking_denied_count > start_denied or
                     s.docking_cancelled_count > start_cancelled),
            6.0, 0.08
        ):
            if s.docking_granted_count > start_granted:
                return "DockingGranted", s.last_docking_station
            if s.docking_denied_count > start_denied:
                return "DockingDenied", s.last_docking_station
            return "DockingCancelled", s.last_docking_station
        return "DockingRequested", station

    def start_request_docking(self):
        self._native_begin("Request Docking", self._request_docking_worker)

    def _request_docking_worker(self):
        if self.state_data.flag("Docked"):
            raise RuntimeError("ship is already docked.")
        self._native_prepare_cockpit("Request Docking")
        result, station = self._request_docking_sequence()
        if result == "DockingGranted":
            self.native_command_status = f"Request Docking: GRANTED by {station}."
            self._native_command_log(f"SUCCESS Request Docking | granted | {station}")
        elif result in ("DockingDenied", "DockingCancelled"):
            raise RuntimeError(f"{result} by {station}.")
        else:
            self.native_command_status = f"Request Docking: REQUESTED at {station}; no grant/deny response seen yet."
            self._native_command_log(f"REQUESTED Request Docking | response pending | {station}")

    def start_docking_protocol(self):
        self._native_begin("Docking Protocol", self._docking_protocol_worker)

    def _docking_denial_is_distance(self):
        reason = str(getattr(self.state_data, "last_docking_reason", "") or "").strip().casefold()
        return any(token in reason for token in ("distance", "too far", "toofar", "approach"))

    def _docking_protocol_finish(self, result, station, zero):
        s = self.state_data
        if result == "DockingGranted":
            self._native_tap(zero, 0.08)
            self.native_command_status = f"Docking Protocol: GRANTED by {station} • throttle 0% sent."
            self._native_command_log(f"SUCCESS Docking Protocol | granted | {station} | throttle zero")
            return True
        if result == "DockingRequested":
            self._native_tap(zero, 0.08)
            self.native_command_status = f"Docking Protocol: REQUESTED at {station}; response pending • throttle 0%."
            self._native_command_log(f"REQUESTED Docking Protocol | response pending | {station} | throttle zero")
            return True
        if result == "DockingCancelled":
            self._native_tap(zero, 0.08)
            raise RuntimeError(f"DockingCancelled by {station}; throttle 0% sent.")
        if result == "DockingDenied" and not self._docking_denial_is_distance():
            self._native_tap(zero, 0.08)
            reason = str(getattr(s, "last_docking_reason", "-") or "-")
            raise RuntimeError(f"DockingDenied by {station}: {reason}; throttle 0% sent.")
        return False

    def _docking_protocol_worker(self):
        """Boost-first arrival command.

        v0.12.69 intentionally makes the physical approach happen before the UI
        work: one boost is always sent first (unless already docked), then the
        Bridge coasts briefly, zeros throttle, and requests docking. A Distance
        denial authorizes another boost/retry, up to three boosts total. Any
        non-distance denial stops immediately rather than blindly boosting.
        """
        s = self.state_data
        if s.flag("Docked"):
            raise RuntimeError("ship is already docked.")
        boost = self._native_binding("UseBoostJuice")
        zero = self._native_binding("SetSpeedZero")
        dock_binds = self._request_docking_bindings()
        self._native_prepare_cockpit("Docking Protocol")
        self._station_safety_pips_arm("DOCKING_COMMAND", "Docking Protocol command pressed")
        self._dynamic_pips_apply_now("STATION_SAFETY", "Docking Protocol command pressed")

        max_boosts = 3
        for approach in range(1, max_boosts + 1):
            self.native_command_status = f"Docking Protocol: approach boost {approach}/{max_boosts}..."
            start_zone_revision = int(getattr(s, "no_fire_zone_revision", 0) or 0)
            self._native_tap(boost, 0.08)
            self._native_command_log(
                f"Docking Protocol | BOOST {approach}/{max_boosts}"
                + (" | initial boost before first range check" if approach == 1 else " | retry after Distance denial")
            )

            # Let the boost actually carry the ship toward the station before
            # opening Contacts. A fresh No-Fire-Zone entry can shorten the wait,
            # but it is not required and stale NFZ state is never trusted.
            coast_deadline = time.monotonic() + 3.5
            while time.monotonic() < coast_deadline:
                self._native_cancel_guard()
                entered = (
                    getattr(s, "no_fire_zone_inside", None) is True and
                    int(getattr(s, "no_fire_zone_revision", 0) or 0) > start_zone_revision
                )
                if entered and (coast_deadline - time.monotonic()) > 0.45:
                    self._native_command_log(
                        f"Docking Protocol | fresh No Fire Zone ENTERED @ {getattr(s, 'no_fire_zone_last_time', '-')}"
                    )
                    break
                time.sleep(0.08)

            # Stop accelerating before the panel sequence. This also makes a
            # successful grant hand off to the docking computer predictably.
            self._native_tap(zero, 0.15)
            self.native_command_status = f"Docking Protocol: boost {approach}/{max_boosts} complete • requesting docking..."
            self._native_command_log(f"Docking Protocol | RANGE CHECK {approach}/{max_boosts} | request docking")
            result, station = self._request_docking_sequence(dock_binds)
            if self._docking_protocol_finish(result, station, zero):
                return

            if result == "DockingDenied" and self._docking_denial_is_distance():
                reason = str(getattr(s, "last_docking_reason", "Distance") or "Distance")
                self._native_command_log(
                    f"Docking Protocol | TOO FAR after boost {approach}/{max_boosts} ({reason})"
                )
                if approach < max_boosts:
                    # _request_docking_sequence closes the panel on a confirmed
                    # response; give Status.json a beat before the next boost.
                    time.sleep(0.20)
                    continue
                self._native_tap(zero, 0.08)
                raise RuntimeError(
                    f"still outside docking range after {max_boosts} boosts; throttle 0% sent."
                )

            # _docking_protocol_finish handles normal terminal responses. This
            # guard catches only an unexpected future journal state.
            raise RuntimeError(f"unexpected docking response after approach: {result}.")

    def start_auto_launch(self):
        self._native_begin("Auto Launch", self._auto_launch_worker)

    def _auto_launch_worker(self):
        """Select Elite's docked Launch / Auto Launch option and verify departure.

        There is no dedicated Elite key binding for Auto Launch. The docked main
        menu is vertical, so anchor at the top with repeated UI Up, move down to
        the Launch row, select once, and then wait for Elite's real Undocked
        telemetry. No retry is sent if the menu geometry is not what we expect.
        """
        s = self.state_data
        if not s.flag("Docked"):
            raise RuntimeError("Auto Launch requires the ship to be docked.")
        if self.station_automation_busy:
            raise RuntimeError("station maintenance is still using the station menu.")

        up = self._native_binding("UI_Up")
        down = self._native_binding("UI_Down")
        select = self._native_binding("UI_Select")
        self._native_prepare_cockpit("Auto Launch")

        start_undocked = float(getattr(s, "last_undocked_mono", 0.0) or 0.0)
        self._station_safety_pips_arm("AUTO_LAUNCH", "Auto Launch command pressed")
        self._dynamic_pips_apply_now("STATION_SAFETY", "Auto Launch command pressed")
        self.native_command_status = "Auto Launch: anchoring docked station menu..."
        # Current ship menu geometry: Starport Services / Hangar-or-Surface /
        # Launch, with optional lower items such as Disembark. Anchoring TOP then
        # moving down two rows avoids depending on whether Disembark exists.
        for _ in range(8):
            self._native_tap(up, 0.045)
        self._native_tap(down, 0.07)
        self._native_tap(down, 0.07)
        self._native_command_log("Auto Launch | station menu anchor TOP -> Down x2 -> Select")
        self._native_tap(select, 0.12)
        self.native_command_status = "Auto Launch: selection sent • waiting for Elite to confirm undock..."

        if self._wait_for(
            lambda: (not s.flag("Docked")) or float(getattr(s, "last_undocked_mono", 0.0) or 0.0) > start_undocked,
            35.0, 0.10
        ):
            self.native_command_status = "Auto Launch: CONFIRMED • ship undocked / launch sequence active."
            self._native_command_log("SUCCESS Auto Launch | Undocked telemetry confirmed")
            if bool(self.session_rules.get("clear_and_jump_after_auto_launch", False)):
                self._native_command_log("SESSION RULE | Auto Launch complete -> Clear Station + FSD queued")
                self.after(650, self._session_rule_clear_and_jump_after_launch)
            return
        self._station_safety_pips_release("Auto Launch failed: no Undocked confirmation")
        raise RuntimeError("no Undocked confirmation after Auto Launch selection; no retry was sent.")

    def _session_rule_clear_and_jump_after_launch(self, attempts=0):
        """Execute the opt-in current-session Auto Launch handoff rule."""
        if not bool(self.session_rules.get("clear_and_jump_after_auto_launch", False)):
            return
        if self.state_data.flag("Docked"):
            if attempts < 20:
                self.after(250, lambda a=attempts + 1: self._session_rule_clear_and_jump_after_launch(a))
                return
            self._native_command_log("SESSION RULE SKIP | ship remained docked; clear-and-jump handoff expired")
            return
        if self.native_command_busy:
            # A session-rule handoff may wait behind the Auto Launch worker that
            # created it, but it never stacks underneath an unrelated command.
            if self.native_command_name == "Auto Launch" and attempts < 20:
                self.after(250, lambda a=attempts + 1: self._session_rule_clear_and_jump_after_launch(a))
                return
            self._native_command_log(f"SESSION RULE SKIP | cockpit owner={self.native_command_name}")
            return
        if self.station_automation_busy or self.egress_phase != "IDLE":
            self._native_command_log("SESSION RULE SKIP | higher-priority cockpit owner active")
            return
        stamp = datetime.now().strftime("%H:%M:%S")
        self.session_rule_history.append(f"{stamp}  EXECUTE clear_and_jump_after_auto_launch")
        self._native_command_log("SESSION RULE EXECUTE | Clear Station + FSD after Auto Launch")
        self.start_clear_station_jump()

    def start_clear_station_jump(self):
        """Clear the station, then use the appropriate FSD mode.

        If a route/FSD target is available, this remains the normal clear-and-jump
        command. If no route is plotted, the same safe departure sequence is used
        but the Bridge deliberately sends Elite's dedicated Supercruise binding.
        """
        self._native_begin("Clear Station + FSD", self._clear_station_jump_worker)

    def _clear_station_jump_target(self):
        s = self.state_data
        next_target = str(getattr(s, "nav_target_system", "") or "").strip()
        route_target = str(getattr(s, "nav_route_destination", "") or "").strip()
        if next_target and next_target != "-":
            return next_target, "FSDTarget"
        if route_target and route_target != "-":
            return route_target, "NavRoute"
        return "", ""

    def _clear_station_jump_worker(self):
        """Actively clear the station, then jump or enter Supercruise.

        Route-aware behavior:
          * plotted route / FSD target -> clear mass lock, then start hyperspace/FSD
          * no plotted route           -> clear mass lock, then dedicated Supercruise

        Both paths use the same telemetry-driven landing-gear, throttle and boost
        sequence. The no-route path intentionally does not use the combined FSD
        toggle, so an empty route can never be mistaken for a hyperspace command.
        """
        s = self.state_data
        self._station_safety_force_cruise_for_bridge_departure()
        target, target_source = self._clear_station_jump_target()
        has_route = bool(target)
        departure_label = target if has_route else "SUPERCRUISE"
        departure_mode = "HYPERSPACE" if has_route else "SUPERCRUISE"

        throttle = self._native_binding("SetSpeed100")
        boost = self._native_binding("UseBoostJuice")

        if has_route:
            fsd_action = None
            fsd_binding = None
            for action in ("Hyperspace", "HyperSuperCombination"):
                candidate = self.bindings.keyboard_binding(action)
                if candidate:
                    fsd_action = action
                    fsd_binding = {
                        "action": candidate.get("action"), "slot": candidate.get("slot"),
                        "key": candidate.get("key"), "modifiers": list(candidate.get("modifiers") or [])
                    }
                    break
            if not fsd_binding:
                raise RuntimeError("missing Elite keyboard binding: Hyperspace or FSD / Hyper-Supercruise Toggle.")
        else:
            fsd_action = "Supercruise"
            candidate = self.bindings.keyboard_binding("Supercruise")
            if not candidate:
                raise RuntimeError("no route is plotted and the dedicated Elite Supercruise keyboard binding is missing.")
            fsd_binding = {
                "action": candidate.get("action"), "slot": candidate.get("slot"),
                "key": candidate.get("key"), "modifiers": list(candidate.get("modifiers") or [])
            }

        start = time.monotonic()
        timeout = 150.0
        clear_since = None
        throttle_sent = False
        gear_retract_sent = False
        gear_retract_sent_mono = 0.0
        boost_count = 0
        next_boost_mono = 0.0
        max_boosts = 8
        last_phase = None
        self._native_command_log(
            f"Clear Station + FSD | ARMED | mode={departure_mode} | target={departure_label} | "
            f"source={target_source or 'NO_ROUTE'} | boost={self.bindings.binding_display('UseBoostJuice')} | "
            f"FSD={self.bindings.binding_display(fsd_action)}"
        )

        while time.monotonic() - start < timeout:
            if s.flag("Being Interdicted"):
                raise RuntimeError("interdiction detected; departure command stopped and pilot has control.")
            if s.flag("Overheating"):
                raise RuntimeError("ship is overheating; departure command stopped before FSD start.")

            if not has_route and s.flag("Supercruise"):
                self.native_command_status = "Clear Station + FSD: Supercruise confirmed."
                self._native_command_log(
                    f"SUCCESS Clear Station + FSD | Supercruise confirmed | gear=UP | boosts={boost_count}"
                )
                return
            if has_route and s.flag("FSD Jump"):
                self.native_command_status = f"Clear Station + FSD: jump already in progress toward {target}."
                self._native_command_log(f"SUCCESS Clear Station + FSD | FSD Jump already active | {target}")
                return
            if s.flag("FSD Charging"):
                if has_route:
                    self.native_command_status = f"Clear Station + FSD: FSD is already charging toward {target}; Bridge stood down."
                    self._native_command_log(f"SUCCESS Clear Station + FSD | existing FSD charge detected | {target}")
                else:
                    self.native_command_status = "Clear Station + FSD: Supercruise FSD is already charging; Bridge stood down."
                    self._native_command_log("SUCCESS Clear Station + FSD | existing Supercruise charge detected")
                return

            status = getattr(s, "status", {}) or {}
            try:
                gui_focus = int(status.get("GuiFocus", 0) or 0)
            except Exception:
                gui_focus = -1

            if s.flag("Docked"):
                phase = "WAIT_DOCKED"
                clear_since = None
                if has_route:
                    msg = f"Clear Station + FSD: armed for {target} • waiting for launch / Undocked."
                else:
                    msg = "Clear Station + FSD: no route plotted • waiting for launch, then Supercruise."

            elif gui_focus != 0:
                phase = "WAIT_GUI"
                clear_since = None
                msg = f"Clear Station + FSD: waiting for cockpit view (GuiFocus {gui_focus})."

            elif s.flag("Landing Gear"):
                phase = "RETRACT_GEAR"
                clear_since = None
                if not gear_retract_sent:
                    gear = self._native_binding("LandingGearToggle")
                    self.native_command_status = f"Clear Station + FSD: retracting landing gear before departure boost • {departure_label}."
                    self._native_tap(gear, 0.08)
                    gear_retract_sent = True
                    gear_retract_sent_mono = time.monotonic()
                    self._native_command_log(
                        f"Clear Station + FSD | GEAR RETRACT sent via {self.bindings.binding_display('LandingGearToggle')} | mode={departure_mode} | target={departure_label}"
                    )
                if gear_retract_sent and gear_retract_sent_mono and time.monotonic() - gear_retract_sent_mono > 4.0:
                    raise RuntimeError("landing gear retract command was sent once but Status.json still reports gear DOWN; no retry sent.")
                msg = f"Clear Station + FSD: waiting for landing gear UP confirmation • {departure_label}."

            elif s.flag("FSD Mass Locked"):
                phase = "BOOST_CLEAR"
                clear_since = None

                if self.station_safety_pips_active:
                    self._station_safety_force_cruise_for_bridge_departure()

                if not throttle_sent:
                    self.native_command_status = f"Clear Station + FSD: full throttle • preparing to boost clear of station for {departure_label}."
                    self._native_tap(throttle, 0.10)
                    throttle_sent = True
                    self._native_command_log(
                        f"Clear Station + FSD | THROTTLE 100% | before mass-lock clearing boosts | mode={departure_mode} | target={departure_label}"
                    )
                    next_boost_mono = time.monotonic()

                now = time.monotonic()
                if now >= next_boost_mono:
                    if boost_count >= max_boosts:
                        raise RuntimeError(
                            f"still mass locked after {max_boosts} departure boosts; Bridge stopped rather than boost indefinitely."
                        )
                    boost_count += 1
                    self.native_command_status = (
                        f"Clear Station + FSD: mass locked • boost {boost_count}/{max_boosts} to clear station • {departure_label}."
                    )
                    self._native_tap(boost, 0.08)
                    self._native_command_log(
                        f"Clear Station + FSD | BOOST {boost_count}/{max_boosts} | mass lock still active | mode={departure_mode} | target={departure_label}"
                    )
                    next_boost_mono = time.monotonic() + 4.25

                msg = (
                    f"Clear Station + FSD: mass locked • boosting clear ({boost_count}/{max_boosts}) • {departure_label}."
                )

            else:
                if clear_since is None:
                    clear_since = time.monotonic()
                    phase = "CLEAR_HOLD"
                    msg = f"Clear Station + FSD: mass lock clear • verifying departure for {departure_label}."
                elif time.monotonic() - clear_since < 1.25:
                    phase = "CLEAR_HOLD"
                    msg = f"Clear Station + FSD: mass lock clear • holding briefly before {departure_mode.lower()}."
                else:
                    current_target, current_source = self._clear_station_jump_target()
                    if has_route:
                        if current_target and not self._same_system_name(current_target, target):
                            raise RuntimeError(
                                f"route target changed while clearing the station ({target} -> {current_target}); no FSD key sent."
                            )
                    elif current_target:
                        raise RuntimeError(
                            f"a route appeared while the no-route Supercruise departure was clearing the station ({current_target}); no FSD key sent. Run the command again."
                        )

                    if not self.key_sender.elite_foreground():
                        raise RuntimeError("Elite lost foreground after station clearance; no FSD key sent.")

                    if not throttle_sent:
                        self.native_command_status = f"Clear Station + FSD: mass lock clear • full throttle for {departure_label}."
                        self._native_tap(throttle, 0.10)
                        throttle_sent = True
                        self._native_command_log(
                            f"Clear Station + FSD | THROTTLE 100% | already clear of mass lock | mode={departure_mode} | target={departure_label}"
                        )
                        if s.flag("FSD Mass Locked"):
                            clear_since = None
                            continue

                    if s.flag("Landing Gear"):
                        gear_retract_sent = False
                        gear_retract_sent_mono = 0.0
                        clear_since = None
                        continue

                    if has_route:
                        self.native_command_status = f"Clear Station + FSD: starting FSD toward {target}."
                    else:
                        self.native_command_status = "Clear Station + FSD: no route plotted • entering Supercruise."
                    self._native_tap(fsd_binding, 0.08)
                    sent = time.monotonic()
                    self._native_command_log(
                        f"Clear Station + FSD | FSD START sent once via {self.bindings.binding_display(fsd_action)} | mode={departure_mode} | target={departure_label}"
                    )

                    if has_route:
                        confirmed = self._wait_for(
                            lambda: s.flag("FSD Charging") or s.flag("FSD Jump"), 4.5, 0.05
                        )
                        if confirmed:
                            state = "FSD Jump" if s.flag("FSD Jump") else "FSD Charging"
                            self.native_command_status = f"Clear Station + FSD: {state} confirmed • {target}."
                            self._native_command_log(
                                f"SUCCESS Clear Station + FSD | {state} confirmed after {time.monotonic()-sent:.2f}s | "
                                f"gear=UP | boosts={boost_count} | {target}"
                            )
                            return
                        raise RuntimeError("FSD start was sent once but Status.json did not confirm charging; no retry sent.")
                    else:
                        charge_confirmed = self._wait_for(
                            lambda: s.flag("FSD Charging") or s.flag("Supercruise"), 6.0, 0.05
                        )
                        if not charge_confirmed:
                            raise RuntimeError("dedicated Supercruise command was sent once but Elite did not confirm FSD charging; no retry sent.")
                        if s.flag("Supercruise"):
                            self.native_command_status = "Clear Station + FSD: Supercruise confirmed."
                            self._native_command_log(
                                f"SUCCESS Clear Station + FSD | Supercruise confirmed after {time.monotonic()-sent:.2f}s | gear=UP | boosts={boost_count}"
                            )
                            return
                        self.native_command_status = "Clear Station + FSD: Supercruise charging • waiting for entry confirmation."
                        if self._wait_for(lambda: s.flag("Supercruise"), 35.0, 0.10):
                            self.native_command_status = "Clear Station + FSD: Supercruise confirmed."
                            self._native_command_log(
                                f"SUCCESS Clear Station + FSD | Supercruise confirmed after {time.monotonic()-sent:.2f}s | gear=UP | boosts={boost_count}"
                            )
                            return
                        raise RuntimeError("Supercruise charge began but entry was not confirmed before the safety timeout; pilot take control.")

            if phase != last_phase:
                self._native_command_log(f"Clear Station + FSD | {phase} | {msg}")
                last_phase = phase
            self.native_command_status = msg
            time.sleep(0.10)

        raise RuntimeError(f"timed out waiting to clear the station for {departure_label}; no FSD retry was sent.")

    def _dynamic_pips_log(self, text):
        line = f"{datetime.now().strftime('%H:%M:%S')}  {text}"
        self.dynamic_pip_history.append(line)
        self.state_data.observer_note("DYNAMIC_PIPS", text)

    def _station_safety_pips_arm(self, context, reason):
        """Track the simple mass-lock shield-bias state for diagnostics/UI."""
        if not self.dynamic_pips_enabled:
            return False
        context = str(context or "MASS_LOCK").upper()
        changed = (not self.station_safety_pips_active) or self.station_safety_pips_context != context
        self.station_safety_pips_active = True
        self.station_safety_pips_context = context
        # Auto Launch must observe Mass Lock *after* Undocked before a clear can
        # release the hold; docked Status.json commonly reports Mass Locked=True.
        self.station_safety_pips_seen_mass_lock = (
            False if context == "AUTO_LAUNCH" else bool(self.state_data.flag("FSD Mass Locked"))
        )
        self.station_safety_pips_started_mono = time.monotonic()
        self.station_safety_reset_pending = False
        self.station_safety_reset_verify_due = 0.0
        self.station_safety_reset_failed = False
        if changed:
            self._dynamic_pips_log(f"STATION SAFETY ACTIVE {context} | {reason}")
        return True

    def _station_safety_pips_release(self, reason):
        if not self.station_safety_pips_active:
            return False
        context = self.station_safety_pips_context
        self.station_safety_pips_active = False
        self.station_safety_pips_context = "-"
        self.station_safety_pips_seen_mass_lock = False
        self.station_safety_pips_started_mono = 0.0
        self.station_safety_reset_pending = False
        self.station_safety_reset_verify_due = 0.0
        self.station_safety_reset_failed = False
        self._dynamic_pips_log(f"STATION SAFETY RELEASE {context} | {reason}")
        return True

    def _dynamic_pips_apply_now(self, mode, reason):
        """Apply one existing Dynamic PIP preset immediately, once, with no retry."""
        if not self.dynamic_pips_enabled or not self.dynamic_pips_var.get():
            self._dynamic_pips_log(f"{mode} IMMEDIATE SKIP | Dynamic PIPs disabled | {reason}")
            return False
        if not self.key_sender.elite_foreground():
            self._dynamic_pips_log(f"{mode} IMMEDIATE SKIP | Elite not foreground | {reason}")
            return False
        status = getattr(self.state_data, "status", {}) or {}
        try:
            gui_focus = int(status.get("GuiFocus", 0) or 0)
        except Exception:
            gui_focus = -1
        if gui_focus != 0:
            self._dynamic_pips_log(f"{mode} IMMEDIATE SKIP | GuiFocus={gui_focus} | {reason}")
            return False
        reset, sequence, missing = self._dynamic_pips_bindings(mode)
        if missing:
            self.dynamic_pip_status = "Dynamic PIPs unavailable: missing keyboard binding(s): " + ", ".join(missing)
            self._dynamic_pips_log(f"{mode} IMMEDIATE SKIP | missing " + ", ".join(missing))
            return False
        preset = DYNAMIC_PIP_PRESETS[mode]
        try:
            self.key_sender.send_binding(reset)
            time.sleep(0.06)
            sent_steps = []
            for action_name, action, count in sequence:
                for _ in range(count):
                    self.key_sender.send_binding(action)
                    time.sleep(0.04)
                sent_steps.append(f"{self.bindings.binding_display(action_name)} x{count}")
            self.dynamic_pip_last_command_mono = time.monotonic()
            self.dynamic_pip_last_applied = mode
            self.dynamic_pip_pending_verify = (
                mode, time.monotonic() + DYNAMIC_PIP_VERIFY_DELAY_SECONDS, list(preset["expected"])
            )
            self.dynamic_pip_mode = mode.replace("_", " ")
            self.dynamic_pip_status = f"{mode}: sent {preset['display']}; awaiting Status.json verification."
            self._dynamic_pips_log(
                f"APPLY {mode} IMMEDIATE | {reason} | {preset['display']} | "
                + " -> ".join(sent_steps)
            )
            return True
        except Exception as exc:
            self.dynamic_pip_status = f"Dynamic PIP command failed: {exc}. No retry sent."
            self.dynamic_pip_last_command_mono = time.monotonic()
            self._dynamic_pips_log(f"FAILED {mode} IMMEDIATE | {reason} | {exc}")
            return False

    def _station_safety_force_cruise_for_bridge_departure(self):
        """Clear Station + FSD explicitly overrides mass-lock shield bias with CRUISE."""
        if not self.dynamic_pips_enabled or not self.dynamic_pips_var.get():
            self._station_safety_pips_release("Clear Station + FSD takeover; Dynamic PIPs disabled")
            return True
        applied = self._dynamic_pips_apply_now("CRUISE", "Clear Station + FSD takeover")
        self._station_safety_pips_release("Clear Station + FSD took cockpit control")
        return applied

    def consider_station_safety_event(self, e):
        # v0.12.80: DockingGranted no longer drives PIPs. Mass Lock does.
        if str(e.get("event") or "") == "Docked":
            self._station_safety_pips_release("Docked telemetry confirmed")

    def _maybe_station_safety_pips(self):
        """Maintain a simple station-safety hold without fighting normal Dynamic PIPs.

        Docking Protocol holds 4/2/0 until Docked. Auto Launch holds 4/2/0
        until post-launch mass lock has been seen and then clears. Generic
        undocked Mass Lock also selects 4/2/0. Clear Station + FSD is the
        explicit exception and owns its 2/4/0 departure profile.
        """
        if not self.dynamic_pips_enabled or not self.dynamic_pips_var.get():
            self._station_safety_pips_release("Dynamic PIPs disabled by pilot")
            return
        s = self.state_data
        command = self.native_command_name if self.native_command_busy else "-"

        if command == "Clear Station + FSD":
            self._station_safety_pips_release("Clear Station + FSD owns departure")
            return

        context = str(self.station_safety_pips_context or "-").upper()

        if self.station_safety_pips_active and context == "DOCKING_COMMAND":
            if s.flag("Docked"):
                self._station_safety_pips_release("Docked telemetry confirmed")
            return

        if self.station_safety_pips_active and context == "AUTO_LAUNCH":
            if s.flag("Docked"):
                return
            if s.flag("FSD Mass Locked"):
                self.station_safety_pips_seen_mass_lock = True
                return
            if self.station_safety_pips_seen_mass_lock:
                self._station_safety_pips_release("post-launch FSD Mass Lock cleared")
            return

        if s.flag("Docked") or not s.flag("In Main Ship"):
            self._station_safety_pips_release("outside undocked main-ship mass-lock flight")
            return

        if s.flag("FSD Mass Locked"):
            self._station_safety_pips_arm("MASS_LOCK", "FSD Mass Locked; favor shields")
        else:
            self._station_safety_pips_release("FSD Mass Lock cleared; return to normal Dynamic PIPs")

    def _dynamic_pips_toggle_changed(self):
        self.dynamic_pips_enabled = bool(self.dynamic_pips_var.get())
        self.dynamic_pip_candidate = None
        self.dynamic_pip_candidate_since = 0.0
        self.dynamic_pip_last_applied = "-"
        self.dynamic_pip_pending_verify = None
        if self.dynamic_pips_var.get():
            self.dynamic_pip_status = "Dynamic PIPs enabled; waiting for a stable flight state."
            self._dynamic_pips_log("ENABLED by pilot")
        else:
            self._station_safety_pips_release("Dynamic PIPs disabled by pilot")
            self.dynamic_pip_status = "Dynamic PIPs OFF. Pilot has full manual distributor control."
            self._dynamic_pips_log("DISABLED by pilot; no reset command sent")
        self._save_automation_config()
        self.refresh_combat_widgets()

    def _dynamic_pips_current(self):
        pips = (getattr(self.state_data, "status", {}) or {}).get("Pips")
        if isinstance(pips, list) and len(pips) >= 3:
            try:
                return [int(round(float(x))) for x in pips[:3]]
            except Exception:
                return None
        return None

    @staticmethod
    def _dynamic_pips_display(values):
        if not isinstance(values, (list, tuple)) or len(values) < 3:
            return "-"
        try:
            return " / ".join(f"{float(x)/2:g}" for x in values[:3]) + "  SYS / ENG / WEP"
        except Exception:
            return "-"

    def _dynamic_pips_desired_mode(self):
        s = self.state_data
        if self.egress_phase != "IDLE":
            return None
        if s.flag("Docked") or s.flag("Supercruise") or s.flag("FSD Jump"):
            return None
        # Ship-only behavior. Do not let today's ship assumptions leak into future
        # fighter/SRV/Rhino/Nomad ground-vehicle logic.
        if not s.flag("In Main Ship"):
            return None

        # Station-safety holds must outrank normal CRUISE/COMBAT selection.
        # This prevents a not-yet-mass-locked docking approach from briefly
        # flipping back to engines before Mass Lock arrives.
        if self.station_safety_pips_active or s.flag("FSD Mass Locked"):
            return "STATION_SAFETY"

        # Priority after explicit Egress / station proximity: real combat next.
        # A fully scanned WANTED target still pre-arms the proven combat profile.
        if s.combat_active or s.wanted_target_prearmed():
            return "COMBAT"

        # After a fight goes quiet, favor SYS even if the pilot intentionally leaves
        # hardpoints deployed while sitting still to rebuild weakened shields. Elite
        # only exposes own-ship shields as UP/DOWN here, not a trustworthy percentage,
        # so the quiet recovery window is deliberately time-based. If shields are
        # actually DOWN, recovery persists beyond the timer until Elite reports UP.
        now = time.monotonic()
        recovery_age = now - float(getattr(s, "combat_last_end_mono", 0.0) or 0.0)
        if (not s.flag("Shields Up")) or (
            getattr(s, "combat_last_end_mono", 0.0)
            and recovery_age < DYNAMIC_PIP_POST_COMBAT_RECOVERY_SECONDS
        ):
            return "RECOVERY"

        # Deploying hardpoints from an otherwise quiet state is enough to prepare
        # the weapon capacitor, but it does NOT mark combat active or trigger any
        # other combat automation. Post-combat RECOVERY above intentionally wins.
        if s.flag("Hardpoints"):
            return "WEAPONS"

        return "CRUISE"

    def _dynamic_pips_bindings(self, mode):
        preset = DYNAMIC_PIP_PRESETS.get(mode) or {}
        reset = self.bindings.keyboard_binding("ResetPowerDistribution")
        sequence = []
        missing = []
        for action_name, count in preset.get("sequence", ()):
            binding = self.bindings.keyboard_binding(action_name)
            sequence.append((action_name, binding, int(count)))
            if not binding:
                missing.append(BindingsManager.DISPLAY_NAMES.get(action_name, action_name))
        if not reset:
            missing.insert(0, "Reset Power Distribution")
        return reset, sequence, missing

    def _maybe_dynamic_pips(self):
        if getattr(self, "native_command_busy", False):
            return
        # Verify a previous command once, but never spam retries. A manual pilot
        # change after the command is respected until the next mode transition.
        if self.dynamic_pip_pending_verify is not None:
            mode, due, expected = self.dynamic_pip_pending_verify
            if time.monotonic() >= due:
                current = self._dynamic_pips_current()
                if current == expected:
                    self.dynamic_pip_status = f"{mode} verified: {DYNAMIC_PIP_PRESETS[mode]['display']}."
                    self._dynamic_pips_log(f"VERIFIED {mode} | {self._dynamic_pips_display(current)}")
                else:
                    self.dynamic_pip_status = (
                        f"{mode} command sent, but Status.json shows {self._dynamic_pips_display(current)}; "
                        "no automatic retry will fight the pilot."
                    )
                    self._dynamic_pips_log(
                        f"VERIFY MISMATCH {mode} | expected {expected} | observed {current}"
                    )
                self.dynamic_pip_pending_verify = None

        if not self.dynamic_pips_var.get():
            self.dynamic_pip_mode = "OFF"
            return

        desired = self._dynamic_pips_desired_mode()
        if desired is None:
            self.dynamic_pip_mode = "INACTIVE"
            self.dynamic_pip_candidate = None
            self.dynamic_pip_candidate_since = 0.0
            self.dynamic_pip_status = "Dynamic PIPs standing by (outside normal main-ship flight)."
            return
        self.dynamic_pip_mode = desired.replace("_", " ")
        now = time.monotonic()
        if desired != self.dynamic_pip_candidate:
            self.dynamic_pip_candidate = desired
            self.dynamic_pip_candidate_since = now
            self.dynamic_pip_status = f"{desired} detected; confirming state before changing PIPs."
            return
        if (now - self.dynamic_pip_candidate_since) < DYNAMIC_PIP_DEBOUNCE_SECONDS:
            return

        # Station Safety is sticky while an Auto Launch/Docking hold is active,
        # or while ordinary Mass Lock is present. Clear Station + FSD bypasses
        # this loop and applies CRUISE directly while it owns the cockpit.
        if desired == self.dynamic_pip_last_applied:
            return
        if (now - self.dynamic_pip_last_command_mono) < DYNAMIC_PIP_MIN_COMMAND_GAP_SECONDS:
            self.dynamic_pip_status = f"{desired} queued behind PIP command cooldown."
            return

        status = getattr(self.state_data, "status", {}) or {}
        try:
            gui_focus = int(status.get("GuiFocus", 0) or 0)
        except Exception:
            gui_focus = -1
        if gui_focus != 0:
            self.dynamic_pip_status = f"{desired} ready; waiting for Elite cockpit focus (GuiFocus={gui_focus})."
            return
        if not self.key_sender.elite_foreground():
            self.dynamic_pip_status = f"{desired} ready; Elite is not foreground, so no PIP keys were sent."
            return

        reset, sequence, missing = self._dynamic_pips_bindings(desired)
        if missing:
            self.dynamic_pip_status = "Dynamic PIPs unavailable: missing keyboard binding(s): " + ", ".join(missing)
            return

        preset = DYNAMIC_PIP_PRESETS[desired]
        try:
            # Proven normal-flight behavior remains unchanged.
            self.key_sender.send_binding(reset)
            time.sleep(0.06)
            sent_steps = []
            for action_name, action, count in sequence:
                for _ in range(count):
                    self.key_sender.send_binding(action)
                    time.sleep(0.04)
                sent_steps.append(f"{self.bindings.binding_display(action_name)} x{count}")
            self.dynamic_pip_last_command_mono = time.monotonic()
            self.dynamic_pip_last_applied = desired
            self.dynamic_pip_pending_verify = (
                desired, time.monotonic() + DYNAMIC_PIP_VERIFY_DELAY_SECONDS, list(preset["expected"])
            )
            self.dynamic_pip_status = f"{desired}: sent {preset['display']}; awaiting Status.json verification."
            self._dynamic_pips_log(
                f"APPLY {desired} | {preset['display']} | reset={self.bindings.binding_display('ResetPowerDistribution')} | "
                + " -> ".join(sent_steps)
            )
        except Exception as exc:
            self.dynamic_pip_status = f"Dynamic PIP command failed: {exc}. No retry sent."
            self.dynamic_pip_last_applied = desired
            self.dynamic_pip_last_command_mono = time.monotonic()
            self._dynamic_pips_log(f"FAILED {desired} | {exc}")

    @staticmethod
    def _ship_key(text):
        return re.sub(r"[^a-z0-9]+", "", str(text or "").casefold())

    def _auto_powerplant_toggle_changed(self):
        if self.auto_powerplant_var.get():
            self.auto_powerplant_status = "ARMED • waiting for a fully scanned WANTED heavy target."
            self.auto_powerplant_history.append(f"{datetime.now().strftime('%H:%M:%S')}  ENABLED")
        else:
            self.auto_powerplant_status = "OFF"
            self.auto_powerplant_history.append(f"{datetime.now().strftime('%H:%M:%S')}  DISABLED")

    def _auto_powerplant_target_signature(self):
        s = self.state_data
        if not s.wanted_target_prearmed():
            return None
        ship_key = self._ship_key(s.target_ship)
        if ship_key not in AUTO_POWERPLANT_HEAVY_SHIP_KEYS:
            return None
        return (
            str(s.target_pilot or "-").casefold(),
            ship_key,
            str(s.target_faction or "-").casefold(),
        )

    def _maybe_auto_heavy_power_plant(self):
        if not self.auto_powerplant_var.get():
            self.auto_powerplant_status = "OFF"
            return
        s = self.state_data
        signature = self._auto_powerplant_target_signature()
        if signature is None:
            self.auto_powerplant_status = "ARMED • waiting for a fully scanned WANTED configured combat target."
            return
        target_name = str(s.target)
        if self._is_power_plant_name(s.target_subsystem):
            self.auto_powerplant_last_signature = signature
            self.auto_powerplant_status = f"READY • Power Plant already selected on {target_name}."
            return
        if signature == self.auto_powerplant_last_signature:
            self.auto_powerplant_status = f"DONE • already attempted this target: {target_name}."
            return
        if self.native_command_busy:
            self.auto_powerplant_status = f"QUEUED • {target_name} qualifies; waiting for {self.native_command_name}."
            return
        if self.egress_phase != "IDLE":
            self.auto_powerplant_status = "BLOCKED • Emergency Egress is active."
            return
        if s.flag("Docked") or s.flag("Supercruise") or s.flag("FSD Jump"):
            self.auto_powerplant_status = "ARMED • waiting for normal-space flight."
            return
        try:
            gui_focus = int((s.status or {}).get("GuiFocus", 0) or 0)
        except Exception:
            gui_focus = -1
        if gui_focus != 0:
            self.auto_powerplant_status = f"READY • heavy WANTED target found; waiting for cockpit view (GuiFocus={gui_focus})."
            return
        if not self.key_sender.elite_foreground():
            self.auto_powerplant_status = "READY • heavy WANTED target found; waiting for Elite foreground."
            return
        self.auto_powerplant_last_signature = signature
        self.auto_powerplant_last_action = f"{datetime.now().strftime('%H:%M:%S')}  {target_name}"
        self.auto_powerplant_status = f"ACTING • selecting Power Plant on {target_name}."
        self.auto_powerplant_history.append(f"{datetime.now().strftime('%H:%M:%S')}  TRIGGER | {target_name}")
        self.state_data.observer_note("AUTO_POWER_PLANT", f"TRIGGER | {target_name}")
        self.start_target_power_plant()

    def _auto_chaff_toggle_changed(self):
        self.auto_chaff_status = "ARMED • monitoring sustained combat pressure." if self.auto_chaff_var.get() else "OFF"
        state = "ENABLED" if self.auto_chaff_var.get() else "DISABLED"
        self.auto_chaff_history.append(f"{datetime.now().strftime('%H:%M:%S')}  {state} | profile={self.auto_chaff_profile_var.get()}")

    def _auto_chaff_profile_changed(self, *_args):
        profile = str(self.auto_chaff_profile_var.get() or "MED").upper()
        if profile not in AUTO_CHAFF_PROFILES:
            profile = "MED"
            self.auto_chaff_profile_var.set(profile)
        if self.auto_chaff_var.get():
            self.auto_chaff_status = f"ARMED • {profile} profile • monitoring sustained combat pressure."

    def _sync_auto_chaff_ammo_epoch(self):
        ts = str(self.state_data.utility_ammo_timestamp or "-")
        if ts != self.auto_chaff_ammo_source_timestamp:
            self.auto_chaff_ammo_source_timestamp = ts
            self.bridge_chaff_fires_since_loadout = 0

    def _auto_chaff_known_remaining(self):
        self._sync_auto_chaff_ammo_epoch()
        return max(0, self._utility_total("chaff") - int(self.bridge_chaff_fires_since_loadout or 0))

    def _auto_chaff_log(self, text):
        line = f"{datetime.now().strftime('%H:%M:%S')}  {text}"
        self.auto_chaff_history.append(line)
        self.state_data.observer_note("AUTO_CHAFF", text)

    def _maybe_auto_chaff(self):
        if not self.auto_chaff_var.get():
            self.auto_chaff_status = "OFF"
            return
        s = self.state_data
        profile_name = str(self.auto_chaff_profile_var.get() or "MED").upper()
        profile = AUTO_CHAFF_PROFILES.get(profile_name, AUTO_CHAFF_PROFILES["MED"])
        if self.native_command_busy:
            self.auto_chaff_status = f"{profile_name} • holding while {self.native_command_name} is running."
            return
        if self.egress_phase != "IDLE":
            self.auto_chaff_status = f"{profile_name} • blocked during Emergency Egress."
            return
        if not s.combat_active or s.combat_encounter_start_mono is None:
            self.auto_chaff_status = f"ARMED • {profile_name} • waiting for sustained combat."
            return
        if s.flag("Docked") or s.flag("Supercruise") or s.flag("FSD Jump"):
            self.auto_chaff_status = f"ARMED • {profile_name} • normal-space combat required."
            return

        now_mono = time.monotonic()
        now_wall = time.time()
        encounter_seconds = max(0.0, now_mono - float(s.combat_encounter_start_mono))
        attack_window = float(profile["attack_window_seconds"])
        recent_attacks = sum(1 for t in s.under_attack_times if now_wall - float(t) <= attack_window)
        if encounter_seconds < float(profile["min_combat_seconds"]):
            self.auto_chaff_status = (
                f"ARMED • {profile_name} • combat {encounter_seconds:.0f}s / {profile['min_combat_seconds']:.0f}s before pressure response."
            )
            return
        if recent_attacks < int(profile["min_attacks"]):
            self.auto_chaff_status = (
                f"ARMED • {profile_name} • need {profile['min_attacks']} UnderAttack event(s) in {attack_window:.0f}s; have {recent_attacks}."
            )
            return
        cooldown = float(profile["cooldown_seconds"])
        since_fire = now_mono - float(self.auto_chaff_last_fire_mono or 0.0)
        if self.auto_chaff_last_fire_mono and since_fire < cooldown:
            self.auto_chaff_status = f"COOLDOWN • {profile_name} • {max(0.0, cooldown - since_fire):.0f}s remaining."
            return
        try:
            gui_focus = int((s.status or {}).get("GuiFocus", 0) or 0)
        except Exception:
            gui_focus = -1
        if gui_focus != 0:
            self.auto_chaff_status = f"READY • {profile_name} pressure met; waiting for cockpit view (GuiFocus={gui_focus})."
            return
        if not self.key_sender.elite_foreground():
            self.auto_chaff_status = f"READY • {profile_name} pressure met; waiting for Elite foreground."
            return
        binding = self.bindings.keyboard_binding("FireChaffLauncher")
        if not binding:
            self.auto_chaff_status = "UNAVAILABLE • Fire Chaff Launcher has no keyboard binding."
            return
        remaining = self._auto_chaff_known_remaining()
        if remaining <= 0:
            self.auto_chaff_status = "BLOCKED • no estimated chaff charges remain from the last Loadout snapshot."
            return
        try:
            self.key_sender.send_binding(binding)
            self.auto_chaff_last_fire_mono = time.monotonic()
            self.auto_chaff_last_fire_wall = datetime.now().strftime("%H:%M:%S")
            self.bridge_chaff_fires_since_loadout += 1
            left = max(0, remaining - 1)
            self.auto_chaff_status = (
                f"CHAFF FIRED • {profile_name} • combat {encounter_seconds:.0f}s • {recent_attacks} recent UnderAttack event(s) • est {left} left."
            )
            self._auto_chaff_log(
                f"FIRED | profile={profile_name} | combat={encounter_seconds:.0f}s | attacks={recent_attacks}/{attack_window:.0f}s | est left={left}"
            )
        except Exception as exc:
            self.auto_chaff_last_fire_mono = time.monotonic()
            self.auto_chaff_status = f"FAILED • {exc}"
            self._auto_chaff_log(f"FAILED | {exc}")

    def _egress_log(self, text):
        line = f"{datetime.now().strftime('%H:%M:%S')}  {text}"
        self.egress_history.append(line)
        self.state_data.observer_note("EMERGENCY_EGRESS", text)

    def _utility_total(self, key):
        rec = (self.state_data.utility_ammo or {}).get(key) or {}
        try:
            return int(rec.get("total", 0) or 0)
        except Exception:
            return 0

    def start_emergency_egress(self):
        s = self.state_data
        if self.egress_phase != "IDLE":
            self.egress_status = f"Emergency Egress already active ({self.egress_phase})."
            return
        # Emergency Egress has priority over ordinary cockpit automation, but it
        # does not overlap it. First request cancellation and wait briefly for
        # the current worker to relinquish ownership.
        if self.native_command_busy:
            prior = self.native_command_name
            self.cancel_current_command("Emergency Egress requested")
            deadline = time.monotonic() + 2.5
            while self.native_command_busy and time.monotonic() < deadline:
                time.sleep(0.05)
            if self.native_command_busy:
                self.egress_status = f"Emergency Egress blocked: {prior} has not released cockpit controls yet."
                self._egress_log(f"REFUSED | command owner still active: {prior}")
                return
        if self.station_automation_busy:
            self.station_automation_generation += 1
            self.egress_status = "Emergency Egress: cancelling station maintenance before taking cockpit controls."
            if not self.station_automation_worker_done.wait(timeout=2.5):
                self.egress_status = "Emergency Egress blocked: station maintenance has not released cockpit controls yet."
                self._egress_log("REFUSED | station automation still active")
                return
            # The worker is physically finished; the normal result-drain will
            # still consume its status row later, but it no longer owns controls.
            self.station_automation_busy = False
            self.station_automation_current_service = "-"
        if s.flag("Docked") or s.flag("Supercruise") or s.flag("FSD Jump"):
            self.egress_status = "Emergency Egress requires normal-space flight; no keys sent."
            self._egress_log("REFUSED | not in normal-space flight")
            return
        try:
            gui_focus = int((s.status or {}).get("GuiFocus", 0) or 0)
        except Exception:
            gui_focus = -1
        if gui_focus != 0 or not self.key_sender.elite_foreground():
            self.egress_status = "Bring Elite to the foreground with no panel open, then press Emergency Egress again."
            self._egress_log(f"REFUSED | foreground={self.key_sender.elite_foreground()} GuiFocus={gui_focus}")
            return

        required = {
            "ResetPowerDistribution": self.bindings.keyboard_binding("ResetPowerDistribution"),
            "IncreaseEnginesPower": self.bindings.keyboard_binding("IncreaseEnginesPower"),
            "SetSpeed100": self.bindings.keyboard_binding("SetSpeed100"),
            "UseBoostJuice": self.bindings.keyboard_binding("UseBoostJuice"),
            "Supercruise": self.bindings.keyboard_binding("Supercruise"),
        }
        hardpoints_deployed = s.flag("Hardpoints")
        retract_binding = self.bindings.keyboard_binding("DeployHardpointToggle") if hardpoints_deployed else None
        missing = [BindingsManager.DISPLAY_NAMES.get(k, k) for k, v in required.items() if not v]
        if hardpoints_deployed and not retract_binding:
            missing.append(BindingsManager.DISPLAY_NAMES.get("DeployHardpointToggle", "Deploy / Retract Hardpoints"))
        if missing:
            self.egress_status = "Emergency Egress unavailable: missing keyboard binding(s): " + ", ".join(missing)
            self._egress_log("REFUSED | missing bindings: " + ", ".join(missing))
            return

        try:
            if hardpoints_deployed:
                self.key_sender.send_binding(retract_binding)
                self._egress_log("HARDPOINTS | retract toggle sent before escape")
                time.sleep(0.12)

            self.key_sender.send_binding(required["ResetPowerDistribution"])
            time.sleep(0.06)
            for _ in range(4):
                self.key_sender.send_binding(required["IncreaseEnginesPower"])
                time.sleep(0.04)
            self.dynamic_pip_last_applied = "EGRESS"
            self.dynamic_pip_pending_verify = (
                "EGRESS", time.monotonic() + DYNAMIC_PIP_VERIFY_DELAY_SECONDS,
                list(DYNAMIC_PIP_PRESETS["EGRESS"]["expected"])
            )

            chaff = self.bindings.keyboard_binding("FireChaffLauncher")
            if chaff and self._auto_chaff_known_remaining() > 0:
                self.key_sender.send_binding(chaff)
                self.bridge_chaff_fires_since_loadout += 1
                self.egress_chaff_sent = True
            else:
                self.egress_chaff_sent = False

            self.key_sender.send_binding(required["SetSpeed100"])
            time.sleep(0.12)
            self.key_sender.send_binding(required["UseBoostJuice"])
            self.egress_boost_sent = True

            self.egress_phase = "CLEAR_MASS_LOCK"
            self.egress_started_mono = time.monotonic()
            self.egress_phase_mono = self.egress_started_mono
            self.egress_supercruise_sent = False
            self.egress_recovery_station = None
            self.egress_status = (
                "EGRESS ACTIVE: hardpoints retract if needed, ENG priority, full throttle, one boost" +
                (", chaff fired" if self.egress_chaff_sent else "") +
                ". PILOT: pull clear of the ring; waiting for MassLocked to clear."
            )
            self._egress_log(
                "START | hardpoints " + ("retract sent | " if hardpoints_deployed else "already retracted | ") +
                "1 SYS / 4 ENG / 1 WEP | full throttle | one boost | " +
                ("chaff sent" if self.egress_chaff_sent else "chaff not sent")
            )
        except Exception as exc:
            self.egress_phase = "IDLE"
            self.egress_status = f"Emergency Egress start failed: {exc}"
            self._egress_log(f"FAILED START | {exc}")

    def cancel_emergency_egress(self):
        if self.egress_phase == "IDLE":
            self.egress_status = "Emergency Egress is not active."
            return
        phase = self.egress_phase
        self.egress_phase = "IDLE"
        self.egress_status = "Emergency Egress cancelled. Pilot has full control."
        self._egress_log(f"CANCELLED by pilot from {phase}; no FSD toggle sent")
        self.dynamic_pip_candidate = None
        self.dynamic_pip_last_applied = "-"

    def _start_egress_recovery_lookup(self):
        if self.egress_recovery_busy or not self.state_data.system or self.state_data.system == "-":
            return
        self.egress_recovery_busy = True
        system = self.state_data.system
        def worker():
            try:
                rows = self.eddata_client._get_json(
                    f"/system/name/{urllib.parse.quote(system, safe='')}/nearest/repair",
                    params={"minLandingPadSize": 3}, timeouts=(6, 12)
                )
                candidates = rows if isinstance(rows, list) else self.eddata_client._records(rows)
                best = None
                for raw in candidates:
                    if not isinstance(raw, dict):
                        continue
                    if str(raw.get("maxLandingPadSize") or "").upper() != "L":
                        continue
                    score = sum(1 for k in ("repair", "refuel", "restock") if int(raw.get(k, 0) or 0))
                    candidate = {
                        "system": str(raw.get("systemName") or "-"),
                        "station": str(raw.get("stationName") or "-"),
                        "station_type": str(raw.get("stationType") or "-"),
                        "arrival_ls": _market_float(raw.get("distanceToArrival")),
                        "support_score": score,
                    }
                    if best is None or (score, -(candidate["arrival_ls"] or 1e12)) > (best["support_score"], -(best["arrival_ls"] or 1e12)):
                        best = candidate
                self.egress_recovery_queue.put(("ok", best, None))
            except Exception as exc:
                self.egress_recovery_queue.put(("error", None, str(exc)))
        threading.Thread(target=worker, daemon=True, name="EgressRecovery").start()

    def _drain_egress_recovery(self):
        try:
            while True:
                kind, station, err = self.egress_recovery_queue.get_nowait()
                self.egress_recovery_busy = False
                if kind == "ok" and station:
                    self.egress_recovery_station = station
                    ls = station.get("arrival_ls")
                    ls_text = "? LS" if ls is None else f"{ls:,.0f} LS"
                    self.egress_status = (
                        f"SAFE IN SUPERCRUISE. Recovery option: {station['station']} / {station['system']} "
                        f"({station['station_type']}, {ls_text})."
                    )
                    self._egress_log(f"RECOVERY | {station['station']} / {station['system']} | {ls_text}")
                elif kind == "ok":
                    self.egress_status = "Safe in supercruise. No large-pad repair station was returned."
                else:
                    self.egress_status = f"Safe in supercruise. Recovery-station lookup unavailable: {err}"
        except queue.Empty:
            pass

    def _maybe_emergency_egress(self):
        if self.egress_phase == "IDLE":
            return
        s = self.state_data
        now = time.monotonic()
        if not self.key_sender.elite_foreground():
            self.egress_status = "Emergency Egress paused: Elite is not foreground. Pilot has control."
            return
        if s.flag("Supercruise"):
            self.egress_phase = "IDLE"
            self.egress_status = "Emergency Egress complete: supercruise confirmed. Looking for recovery support..."
            self._egress_log("COMPLETE | Supercruise confirmed")
            self._start_egress_recovery_lookup()
            self.dynamic_pip_candidate = None
            self.dynamic_pip_last_applied = "-"
            return
        if self.egress_phase == "CLEAR_MASS_LOCK":
            if not s.flag("FSD Mass Locked"):
                binding = self.bindings.keyboard_binding("Supercruise")
                try:
                    self.key_sender.send_binding(binding)
                    self.egress_supercruise_sent = True
                    self.egress_phase = "WAIT_FSD"
                    self.egress_phase_mono = now
                    self.egress_status = "Mass lock clear. Dedicated Supercruise command sent once; waiting for FSD charge."
                    self._egress_log("MASS LOCK CLEAR | Supercruise command sent once")
                except Exception as exc:
                    self.egress_phase = "IDLE"
                    self.egress_status = f"Mass lock cleared, but Supercruise command failed: {exc}"
                    self._egress_log(f"FAILED SUPERCRUISE COMMAND | {exc}")
                return
            if now - self.egress_started_mono > EGRESS_MASSLOCK_TIMEOUT_SECONDS:
                self.egress_status = "Still mass locked. Keep flying clear; Bridge will continue watching. No extra boost is sent automatically."
            return
        if self.egress_phase == "WAIT_FSD":
            if s.flag("FSD Charging") or s.flag("FSD Jump"):
                self.egress_phase = "WAIT_SUPERCRUISE"
                self.egress_phase_mono = now
                self.egress_status = "Supercruise FSD charge confirmed. Keep the escape vector clear."
                self._egress_log("FSD CHARGING confirmed")
                return
            if now - self.egress_phase_mono > EGRESS_FSD_CONFIRM_SECONDS:
                self.egress_phase = "IDLE"
                self.egress_status = "Supercruise command was not confirmed. No blind retry was sent; pilot take control."
                self._egress_log("STOPPED | Supercruise charge not confirmed; no retry")
                return
        if self.egress_phase == "WAIT_SUPERCRUISE" and now - self.egress_phase_mono > EGRESS_SUPERCRUISE_TIMEOUT_SECONDS:
            self.egress_phase = "IDLE"
            self.egress_status = "FSD charge did not reach supercruise before the safety timeout. Pilot take control."
            self._egress_log("STOPPED | supercruise entry timeout")

    def reset_combat_session(self):
        self.state_data.reset_combat_session()
        self.res_search_status = "Combat session counters reset. RES finder results preserved."
        self.refresh_combat_widgets()

    @staticmethod
    def _combat_format_duration(seconds):
        total = max(0, int(seconds or 0))
        h, rem = divmod(total, 3600)
        m, sec = divmod(rem, 60)
        return f"{h:d}:{m:02d}:{sec:02d}"

    def refresh_combat_widgets(self):
        if not hasattr(self, "combat_ship_vars"):
            return
        s = self.state_data
        elapsed = s.combat_elapsed_seconds()
        combat_cr = int(s.combat_bounty_cr or 0) + int(s.combat_bond_cr or 0)
        cr_hr = int(combat_cr * 3600.0 / elapsed) if elapsed >= 30 else 0
        ship_display = s.ship if not s.ship_name else f"{s.ship} ({s.ship_name})"
        cv = self.combat_ship_vars
        cv["state"].set("ACTIVE" if s.combat_active else "IDLE")
        cv["ship"].set(ship_display)
        cv["shields"].set("UP" if s.flag("Shields Up") else "DOWN")
        cv["hull"].set(pct(s.hull_health))
        cv["heat"].set("OVERHEATING" if s.flag("Overheating") else "NORMAL")
        cv["hardpoints"].set("DEPLOYED" if s.flag("Hardpoints") else "RETRACTED")
        cv["hud_mode"].set("ANALYSIS" if s.flag("Analysis Mode") else "COMBAT")
        cv["session"].set(f"{self._combat_format_duration(elapsed)} | encounters {s.combat_encounters}")
        cv["kills"].set(f"{s.combat_bounty_kills:,}")
        cv["bounty_cr"].set(f"{s.combat_bounty_cr:,} CR")
        cv["bonds"].set(f"{s.combat_bond_kills:,} kills | {s.combat_bond_cr:,} CR")
        cv["pvp"].set(f"{s.combat_pvp_kills:,}")
        cv["shield_drops"].set(f"{s.combat_shield_drops:,}")
        cv["hull_events"].set(f"{s.combat_hull_events:,}")
        cv["heat_events"].set(f"{s.combat_heat_events:,}")
        cv["cr_hr"].set("-" if elapsed < 30 else f"{cr_hr:,} CR/hr")

        tv = self.combat_target_vars
        tv["target"].set(s.target)
        tv["pilot"].set(s.target_pilot)
        tv["ship"].set(s.target_ship)
        tv["legal"].set(s.target_legal)
        tv["faction"].set(s.target_faction)
        tv["rank"].set(s.target_rank)
        tv["hull"].set(pct(s.target_hull))
        tv["shield"].set(pct(s.target_shield))
        tv["bounty"].set("-" if s.target_bounty is None else f"{int(s.target_bounty):,} CR" if isinstance(s.target_bounty, (int, float)) else str(s.target_bounty))
        tv["subsystem"].set(s.target_subsystem)
        tv["subsystem_health"].set(pct(s.target_subsystem_health))
        live_res = sorted({row.get("type", "RES") for row in s.combat_res_signals.values()})
        tv["res_signals"].set(", ".join(live_res) if live_res else "none observed in current journal")

        if hasattr(self, "combat_target_intel_var"):
            current_intel = s.current_target_intel()
            if current_intel:
                self.combat_target_intel_var.set(f"TARGET INTEL • {current_intel}")
                wanted = str(s.target_legal or "").strip().casefold() == "wanted"
                self.combat_target_intel_label.configure(bg="#8b1e1e" if wanted else "#355c45", fg="white")
            elif s.target_intel_last != "-":
                self.combat_target_intel_var.set(
                    f"LAST FULL SCAN • {s.target_intel_last} • {s.target_intel_last_time}"
                )
                self.combat_target_intel_label.configure(bg="#444444", fg="white")
            else:
                self.combat_target_intel_var.set("TARGET INTEL • waiting for a completed ship scan")
                self.combat_target_intel_label.configure(bg="#444444", fg="white")

        if hasattr(self, "combat_material_intel_var"):
            if s.material_last_pickup != "-":
                if s.material_last_pickup_total is None:
                    observed = int(s.material_last_pickup_session_observed or 0)
                    total_text = f"{observed:,}+ observed this session"
                else:
                    total_text = f"{int(s.material_last_pickup_total):,} held"
                self.combat_material_intel_var.set(
                    f"MATERIAL INTEL • {s.material_last_pickup} • +pickup • {s.material_last_pickup_category} • "
                    f"{total_text} • {s.material_last_pickup_time}"
                )
                self.combat_material_intel_label.configure(bg="#355c45", fg="white")
            else:
                seed_text = "inventory snapshot loaded" if s.material_inventory_seeded else "waiting for Materials snapshot"
                self.combat_material_intel_var.set(f"MATERIAL INTEL • waiting for a material pickup • {seed_text}")
                self.combat_material_intel_label.configure(bg="#444444", fg="white")

        if hasattr(self, "combat_assist_vars"):
            av = self.combat_assist_vars
            av["mode"].set(self.dynamic_pip_mode + (" • ON" if self.dynamic_pips_var.get() else " • OFF"))
            av["pips"].set(self._dynamic_pips_display(self._dynamic_pips_current()))
            av["status"].set(self.dynamic_pip_status)
            av["bindings"].set(
                f"SYS {self.bindings.binding_display('IncreaseSystemsPower')} | "
                f"ENG {self.bindings.binding_display('IncreaseEnginesPower')} | "
                f"WEP {self.bindings.binding_display('IncreaseWeaponsPower')} | "
                f"RESET {self.bindings.binding_display('ResetPowerDistribution')}"
            )
            av["hostile_chat"].set(self._combat_hostile_chat_active() or "-")
            av["auto_powerplant"].set(self.auto_powerplant_status)
            av["auto_chaff"].set(
                f"{self.auto_chaff_status} | est charges {self._auto_chaff_known_remaining()} | binding {self.bindings.binding_display('FireChaffLauncher')}"
            )
            av["egress"].set(f"{self.egress_phase} • {self.egress_status}")

        if hasattr(self, "native_command_status_var"):
            busy = f"BUSY • {self.native_command_name} • " if self.native_command_busy else ""
            self.native_command_status_var.set(busy + self.native_command_status)
            self.native_command_bindings_var.set(
                f"Threat {self.bindings.binding_display('SelectHighestThreat')} • "
                f"Wing target {self.bindings.binding_display('TargetWingman0')} • "
                f"Target's target {self.bindings.binding_display('SelectTargetsTarget')} • "
                f"Nav lock {self.bindings.binding_display('WingNavLock')} • "
                f"Mode {self.bindings.binding_display('PlayerHUDModeToggle')} • "
                f"Dock {self.bindings.binding_display('FocusLeftPanel')} • "
                f"Jump {self.bindings.binding_display('Hyperspace') if self.bindings.keyboard_binding('Hyperspace') else self.bindings.binding_display('HyperSuperCombination')}"
            )

        stolen_aboard = s.stolen_cargo_count()
        collector_count = max(0, int(s.collector_launches_upper_bound or 0))
        reserve = s.limpet_reserve_count()
        pickup_count = max(0, int(s.collector_pickups_since_reset or 0))
        if stolen_aboard:
            strip_text = (
                f"STOLEN CARGO WARNING • {stolen_aboard} stolen unit(s) aboard • "
                f"collectors possibly deployed: {collector_count} • limpets remaining: {reserve} • "
                f"collector-context pickups: {pickup_count}"
            )
            strip_bg = "#8b1e1e"
        elif collector_count:
            strip_text = (
                f"COLLECTOR WATCH • up to {collector_count} may still be deployed • "
                f"limpets remaining: {reserve} • collector-context pickups: {pickup_count} • "
                f"last pickup: {s.collector_last_pickup}"
            )
            strip_bg = "#6b5a1f"
        else:
            strip_text = (
                f"COLLECTOR WATCH • none observed in current context • limpets remaining: {reserve} • "
                f"session salvage: {s.salvage_collected} cargo / {s.salvage_material_units} material unit(s)"
            )
            strip_bg = "#355c45"
        if hasattr(self, "combat_salvage_strip_var"):
            self.combat_salvage_strip_var.set(strip_text)
        if hasattr(self, "combat_salvage_strip_label"):
            self.combat_salvage_strip_label.configure(bg=strip_bg, fg="white")

        sv = self.combat_support_vars
        sv["collectors"].set(s.collector_deployment_text())
        sv["limpet_reserve"].set(f"{s.limpet_reserve_count():,}")
        sv["collector_pickups"].set(
            f"{s.collector_pickups_since_reset:,} total • "
            f"{s.collector_cargo_pickups_since_reset:,} cargo • "
            f"{s.collector_material_units_since_reset:,} material unit(s)"
        )
        sv["collector_last_pickup"].set(
            f"{s.collector_last_pickup} @ {s.collector_last_pickup_time}"
            if s.collector_last_pickup != "-" else "none observed since reset"
        )
        sv["salvage_total"].set(
            f"{s.salvage_collected:,} cargo pickup(s) • {s.salvage_material_units:,} material unit(s) • "
            f"{s.salvage_stolen_collected:,} stolen cargo pickup(s)"
        )
        sv["stolen_aboard"].set(f"{stolen_aboard:,}" + ("  WARNING" if stolen_aboard else ""))
        sv["salvage_notice"].set(s.salvage_last_notice)
        sv["crew_total"].set(f"{s.crew_wages_total:,} CR across {s.crew_wage_events} wage event(s)")
        sv["crew_last"].set(s.crew_last_wage)
        for key in ("chaff", "heat_sink"):
            rec = (s.utility_ammo or {}).get(key) or {}
            total = int(rec.get("total", 0) or 0)
            modules = int(rec.get("modules", 0) or 0)
            if key == "chaff" and modules:
                sv[key].set(
                    f"~{self._auto_chaff_known_remaining()} estimated remaining across {modules} module(s) "
                    f"({self.bridge_chaff_fires_since_loadout} Bridge-fired since Loadout; manual use not observable)"
                )
            else:
                sv[key].set(f"{total} charge(s) across {modules} module(s)" if modules else "not observed in last Loadout")
        if stolen_aboard:
            self.combat_support_alert_var.set(
                f"SALVAGE WARNING • {stolen_aboard} stolen cargo unit(s) currently aboard. "
                "Warning only; no selective cargo ejection is exposed."
            )
        elif (
            s.crew_pay_alert_text not in ("", "-")
            and time.monotonic() <= float(s.crew_pay_alert_expires_mono or 0.0)
        ):
            self.combat_support_alert_var.set(s.crew_pay_alert_text)
        else:
            self.combat_support_alert_var.set(
                "Salvage / crew watch ready. Crew pay alerts require an explicit positive NpcCrewPaidWage journal event."
            )

        self.combat_event_text.configure(state="normal")
        self.combat_event_text.delete("1.0", "end")
        for line in list(s.combat_event_history)[-100:]:
            self.combat_event_text.insert("end", line + "\n")
        self.combat_event_text.see("end")
        self.combat_event_text.configure(state="disabled")
        self.res_search_status_var.set(self.res_search_status)
        rows = []
        for r in self.res_search_results:
            ly = r.get("distance_ly", -1)
            ls = r.get("res_ls", -1)
            support_ls = r.get("support_station_ls")
            rows.append((
                r.get("type", "-"), r.get("system", "-"),
                "-" if ly is None or ly < 0 else f"{ly:.1f}",
                r.get("body", "-"),
                "-" if ls is None or ls < 0 else f"{ls:,.0f}",
                r.get("support_quality", "-"),
                r.get("support_station", "-"),
                "-" if support_ls is None or support_ls < 0 else f"{support_ls:,.0f}",
                r.get("confidence", "-"), r.get("power", "-"),
            ))
        rows_key = tuple(tuple(row) for row in rows)
        if rows_key != self._res_tree_rows_cache:
            self.update_tree(self.res_tree, rows)
            self._res_tree_rows_cache = rows_key
            # Restore the stored selection after a result-table rebuild. The
            # selected result itself is authoritative; Treeview focus is visual.
            if self.res_selected_signature:
                for idx, item_id in enumerate(self.res_tree.get_children()):
                    if idx >= len(self.res_search_results):
                        break
                    row = self.res_search_results[idx]
                    sig = (str(row.get("type", "")), str(row.get("system", "")), str(row.get("body", "")))
                    if sig == self.res_selected_signature:
                        self.res_tree.selection_set(item_id)
                        self.res_tree.focus(item_id)
                        self.res_tree.see(item_id)
                        break

    def _on_res_tree_select(self, _event=None):
        if not hasattr(self, "res_tree"):
            return
        selected = self.res_tree.selection()
        if not selected:
            return
        children = list(self.res_tree.get_children())
        try:
            idx = children.index(selected[0])
        except ValueError:
            return
        if not (0 <= idx < len(self.res_search_results)):
            return
        row = dict(self.res_search_results[idx])
        self.res_selected_result = row
        self.res_selected_signature = (str(row.get("type", "")), str(row.get("system", "")), str(row.get("body", "")))
        system = row.get("system") or "-"
        body = row.get("body") or "-"
        kind = row.get("type") or "RES"
        self.res_search_status = f"Selected {kind}: {system} / {body}. Ready to plot selected system."
        if hasattr(self, "res_search_status_var"):
            self.res_search_status_var.set(self.res_search_status)

    def find_nearby_res(self):
        if self.res_search_busy:
            self.res_search_status = "RES search already running..."
            self.refresh_combat_widgets()
            return
        coords = self.state_data.system_pos
        if not coords or len(coords) < 3:
            self.res_search_status = "Cannot search yet: current system coordinates are not available from the Elite journal."
            self.refresh_combat_widgets()
            return
        if not self.res_search_high_var.get() and not self.res_search_haz_var.get():
            self.res_search_status = "Select High RES, Haz RES, or both."
            self.refresh_combat_widgets()
            return
        try:
            radius = float(self.res_search_radius_var.get().strip())
            max_ls = float(self.res_search_max_ls_var.get().strip())
        except Exception:
            self.res_search_status = "Radius and max RES distance must be numbers."
            self.refresh_combat_widgets()
            return
        # Hard input bounds keep accidental typos from creating absurd searches.
        radius = min(250.0, max(1.0, radius))
        max_ls = min(500000.0, max(100.0, max_ls))
        self.res_search_radius_var.set(f"{radius:g}")
        self.res_search_max_ls_var.set(f"{max_ls:g}")
        self.res_search_busy = True
        self.res_search_results = []
        self.res_search_last_errors = []
        self.res_selected_result = None
        self.res_selected_signature = None
        self._res_tree_rows_cache = None
        include_high = bool(self.res_search_high_var.get())
        include_haz = bool(self.res_search_haz_var.get())
        self.res_search_last_query = {
            "system": self.state_data.system, "coords": tuple(coords),
            "radius_ly": radius, "max_ls": max_ls,
            "high": include_high, "haz": include_haz,
        }
        self.res_search_status = f"Searching INTRA around {self.state_data.system} within {radius:g} LY..."
        self.refresh_combat_widgets()

        def worker():
            try:
                results, warnings = self.intra_res_client.search(
                    coords, radius, max_ls,
                    include_high=include_high,
                    include_haz=include_haz,
                )
                results = self._enrich_res_support(results)
                self.res_search_queue.put(("ok", results, warnings))
            except Exception as exc:
                self.res_search_queue.put(("error", str(exc), []))
        threading.Thread(target=worker, daemon=True, name="RESFinder").start()

    def _best_combat_support_station(self, system_name):
        candidates=[]

        def as_bool(v):
            if isinstance(v,bool): return v
            if isinstance(v,(int,float)): return bool(v)
            return str(v or "").strip().casefold() in ("1","true","yes","y","on")

        def consider(raw, source="EDData"):
            if not isinstance(raw,dict): return
            pad=str(raw.get("maxLandingPadSize") or raw.get("pad") or "").upper()
            station_type=str(raw.get("stationType") or raw.get("station_type") or "")
            # Journal fallback may not explicitly store pad size. Full orbital
            # starports are large-pad capable; outposts are not.
            if not pad and station_type.casefold() in ("coriolis","orbis","ocellus","asteroid base","asteroidbase"):
                pad="L"
            if pad != "L": return
            if "carrier" in station_type.casefold(): return
            repair=as_bool(raw.get("repair"))
            refuel=as_bool(raw.get("refuel"))
            restock=as_bool(raw.get("restock")) or as_bool(raw.get("rearm"))
            score=int(repair)+int(refuel)+int(restock)
            if score==3: quality="FULL"
            elif repair and restock: quality="GOOD"
            elif repair: quality="REPAIR"
            else: quality="LIMITED"
            arrival=_market_float(raw.get("distanceToArrival",raw.get("arrival_ls")))
            candidates.append({
                "station":str(raw.get("stationName") or raw.get("station") or "-"),
                "station_type":station_type or "-",
                "arrival_ls":arrival if arrival is not None else -1.0,
                "score":score,"quality":quality,"source":source,
            })

        # First use station truth learned directly from this commander's journal.
        # This guarantees places like Metz Enterprise remain usable support data
        # even if a community API is temporarily sparse.
        for meta in getattr(self.state_data,"station_metadata",{}).values():
            if str(meta.get("system") or "").casefold()!=str(system_name).casefold():
                continue
            local=dict(meta)
            services={str(x).casefold() for x in (local.get("services") or [])}
            if services:
                local["repair"]="repair" in services
                local["refuel"]="refuel" in services
                local["restock"]=("rearm" in services or "restock" in services)
            consider(local,"Journal")

        remote=[]
        try:
            remote=self.eddata_client.stations_in_system(system_name,timeout=6)
        except Exception:
            remote=[]
        # Some EDData deployments have returned the station collection through
        # /markets more reliably than /stations, so use it as a harmless backup.
        if not remote:
            try:
                system=urllib.parse.quote(str(system_name),safe="")
                data=self.eddata_client._get_json(f"/system/name/{system}/markets",timeouts=(6,))
                remote=self.eddata_client._records(data)
            except Exception:
                remote=[]
        for raw in remote:
            consider(raw,"EDData")

        if not candidates:
            return None
        def key(c):
            arrival=c["arrival_ls"] if c["arrival_ls"] is not None and c["arrival_ls"]>=0 else 1e12
            # Full service first, then shortest supercruise arrival distance;
            # Journal and EDData are both treated as evidence, not ranking bias.
            return (c["score"],-arrival)
        return max(candidates,key=key)

    def _enrich_res_support(self, results):
        # Network enrichment is best-effort and never blocks use of RES results.
        systems = []
        for row in results:
            name = str(row.get("system") or "-")
            if name != "-" and name not in systems:
                systems.append(name)
            if len(systems) >= 12:
                break
        support = {}
        threads = []
        outq = queue.Queue()
        def lookup(name):
            outq.put((name, self._best_combat_support_station(name)))
        for name in systems:
            t = threading.Thread(target=lookup, args=(name,), daemon=True)
            t.start(); threads.append(t)
        deadline = time.monotonic() + 8.0
        remaining = set(systems)
        while remaining and time.monotonic() < deadline:
            try:
                name, value = outq.get(timeout=0.25)
                support[name] = value
                remaining.discard(name)
            except queue.Empty:
                pass
        enriched = []
        for row in results:
            r = dict(row)
            info = support.get(str(r.get("system") or "-"))
            if info:
                r["support_quality"] = info["quality"]
                r["support_station"] = info["station"]
                r["support_station_type"] = info["station_type"]
                r["support_station_ls"] = info["arrival_ls"]
            elif str(r.get("system") or "-") in systems:
                r["support_quality"] = "NONE"
                r["support_station"] = "-"
                r["support_station_ls"] = -1.0
            else:
                r["support_quality"] = "NOT CHECKED"
                r["support_station"] = "-"
                r["support_station_ls"] = -1.0
            enriched.append(r)
        return enriched

    def _drain_res_search_results(self):
        try:
            while True:
                kind, payload, warnings = self.res_search_queue.get_nowait()
                self.res_search_busy = False
                if kind == "ok":
                    self.res_search_results = list(payload or [])
                    self.res_search_last_errors = list(warnings or [])
                    self.res_selected_result = None
                    self.res_selected_signature = None
                    self._res_tree_rows_cache = None
                    if self.res_search_results:
                        suffix = f" | warnings: {' | '.join(warnings)}" if warnings else ""
                        full = sum(1 for r in self.res_search_results if r.get("support_quality") == "FULL")
                        self.res_search_status = f"Found {len(self.res_search_results)} nearby RES result(s), nearest first; {full} with FULL large-pad repair/refuel/restock support.{suffix}"
                    else:
                        self.res_search_status = "No matching RES sites found in that search window. Try a larger LY/LS range."
                else:
                    self.res_search_results = []
                    self.res_search_last_errors = [str(payload)]
                    self.res_search_status = f"RES search failed: {payload}"
        except queue.Empty:
            pass

    def plot_selected_res_system(self):
        if not hasattr(self, "res_tree"):
            return

        row = self.res_selected_result
        if row is None:
            # Fallback for a click that has not yet delivered the Tk selection
            # callback. Store by result index, not by transient display text.
            selected = self.res_tree.selection()
            if selected:
                children = list(self.res_tree.get_children())
                try:
                    idx = children.index(selected[0])
                except ValueError:
                    idx = -1
                if 0 <= idx < len(self.res_search_results):
                    row = dict(self.res_search_results[idx])
                    self.res_selected_result = row
                    self.res_selected_signature = (
                        str(row.get("type", "")), str(row.get("system", "")), str(row.get("body", ""))
                    )

        if not row:
            self.res_search_status = "Select a RES row first."
            self.refresh_combat_widgets()
            return
        system = str(row.get("system") or "").strip()
        if not system:
            self.res_search_status = "Selected RES result does not contain a system name."
            self.refresh_combat_widgets()
            return
        kind = row.get("type") or "RES"
        body = row.get("body") or "-"
        self.res_search_status = f"Plotting {kind} destination {system} / {body} with the proven Navigation Lab route engine..."
        self.refresh_combat_widgets()
        # Deliberately call the unchanged proven navigation method. RES Finder
        # does not contain its own Galaxy Map choreography.
        self.nav_quick_route(system)

