    def _automation_toggle_changed(self):
        self._save_automation_config()
        enabled = []
        if self.auto_refuel_var.get():
            enabled.append("Refuel")
        if self.auto_repair_var.get():
            enabled.append("Repair")
        if self.auto_rearm_var.get():
            enabled.append("Rearm")
        if not enabled:
            self.station_automation_pending = False
            self.station_automation_status = "Automatic station maintenance is OFF."
            self._station_automation_log("Automation toggles OFF.")
        else:
            self.station_automation_status = "Enabled: " + ", ".join(enabled) + "."
            self._station_automation_log("Automation enabled: " + ", ".join(enabled) + ".")
            # If the commander enables a service while already docked, allow a
            # cautious one-time run after a short hold instead of requiring undock/redock.
            if self.state_data.flag("Docked"):
                self.station_automation_completed_token = "-"
                self.station_automation_pending = True
                self.station_automation_pending_started = time.monotonic()
                self.station_automation_pending_due = time.monotonic() + 1.5
                self.station_automation_dock_token = (
                    f"{self.state_data.station}|toggle|{time.time():.3f}"
                )
        self.refresh_preferences_widgets()

    def _station_automation_log(self, text):
        line = f"{datetime.now().strftime('%H:%M:%S')}  {text}"
        self.station_automation_history.append(line)

    def _current_main_fuel(self):
        fuel = (getattr(self.state_data, "status", {}) or {}).get("Fuel")
        if isinstance(fuel, dict):
            try:
                value = fuel.get("FuelMain")
                if value is not None:
                    return float(value)
            except Exception:
                pass
        try:
            if self.state_data.last_fuel_level is not None:
                return float(self.state_data.last_fuel_level)
        except Exception:
            pass
        return None

    def _station_service_plan(self):
        """Return only enabled, available and currently-needed maintenance actions."""
        s = self.state_data
        available = set(getattr(s, "station_services", set()) or set())
        plan = []
        skipped = []

        if self.auto_refuel_var.get():
            if "refuel" not in available:
                skipped.append("Refuel unavailable at this station")
            else:
                # Dock-time refuel is intentionally unconditional. Status/Fuel can
                # briefly lag immediately after docking and has previously reported
                # a full tank even when Elite still accepted a small RefuelAll.
                # The pilot's rule is simpler and safer: if the station offers fuel
                # and Auto Refuel is enabled, press Refuel exactly once for this dock.
                # Selecting Refuel at a genuinely full tank is harmless; no retry is
                # ever sent, and the dock token prevents repeated automatic passes.
                plan.append({"service": "refuel", "label": "Refuel", "index": 0})

        if self.auto_repair_var.get():
            if "repair" not in available:
                skipped.append("Repair unavailable at this station")
            else:
                # Hull=100% does not prove modules / wear need no repair. The
                # pilot explicitly enabled Auto Repair, so ask Elite to Repair All.
                plan.append({"service": "repair", "label": "Repair", "index": 1})

        if self.auto_rearm_var.get():
            if "rearm" not in available:
                skipped.append("Rearm unavailable at this station")
            else:
                # Elite does not provide a simple all-weapons ammo deficit value
                # comparable to FuelMain. Rearm is therefore an explicit opt-in
                # attempt and still requires a BuyAmmo journal confirmation.
                plan.append({"service": "rearm", "label": "Rearm", "index": 2})

        return plan, skipped

    def _station_required_bindings(self):
        # v0.12.22 mirrors the proven VoiceAttack station-maintenance choreography:
        # Up x3, hold Left ~1.05 s to anchor at the left edge, Right xN, Select.
        # UIFocus is intentionally not used.
        actions = ("UI_Up", "UI_Left", "UI_Right", "UI_Select")
        missing = [a for a in actions if not self.bindings.keyboard_binding(a)]
        mode = self.bindings.ui_focus_mode()
        return actions, missing, mode

    def _station_focus_conflicts(self):
        """Return dangerous hold-key collisions for the Station Services macro.

        UIFocus is held while a directional key is pressed to acquire a cockpit
        panel. If any key held by UIFocus is also the *main* key for Up/Left/Right/
        Select, Elite can interpret the focus chord as a different panel command.
        That is exactly what happened with the old Ctrl+Ctrl+K binding: K was also
        UI Left, so the macro opened the left panel.
        """
        focus = self.bindings.keyboard_binding("UIFocus")
        if not focus:
            return []
        held_tokens = set(focus.get("modifiers", [])) | {focus.get("key")}
        conflicts = []
        for action in ("UI_Up", "UI_Left", "UI_Right", "UI_Select"):
            binding = self.bindings.keyboard_binding(action)
            if binding and binding.get("key") in held_tokens:
                conflicts.append(
                    f"UI Focus holds {self.bindings.key_display(binding.get('key'))}, "
                    f"which is the main key for {BindingsManager.DISPLAY_NAMES.get(action, action)}"
                )
        return conflicts

    def _station_binding_sendability_error(self):
        for action in ("UI_Up", "UI_Left", "UI_Right", "UI_Select"):
            binding = self.bindings.keyboard_binding(action)
            if not binding:
                continue
            for token in list(binding.get("modifiers", [])) + [binding.get("key")]:
                try:
                    self.key_sender.vk_for(token)
                except Exception as exc:
                    return (
                        f"{BindingsManager.DISPLAY_NAMES.get(action, action)} uses unsupported "
                        f"keyboard token {token}: {exc}"
                    )
        return ""

    def _station_gui_focus(self):
        try:
            return int((self.state_data.status or {}).get("GuiFocus", -1))
        except Exception:
            return -1

    def _station_preflight(self):
        if os.name != "nt":
            return False, "Station automation is Windows-only."
        if not self._automation_enabled():
            return False, "No station automation toggles are enabled."
        if not self.state_data.flag("Docked"):
            return False, "Not docked."
        if not getattr(self.state_data, "station_services_explicit", False):
            return False, "Docked event did not provide a StationServices capability list."
        gui_focus = self._station_gui_focus()
        # VoiceAttack capture proved successful station quick-service input while
        # Status.json remained GuiFocus=0 throughout. GuiFocus therefore cannot
        # confirm this menu. We still fail closed if Elite reports a *different*
        # focused cockpit/map panel, because steering that panel would be unsafe.
        if gui_focus not in (0, 5):
            return False, (
                f"Station maintenance blocked by GuiFocus={gui_focus} "
                f"({GUI_FOCUS_NAMES.get(gui_focus, 'Unknown')}). Return to the normal post-dock station menu."
            )
        _actions, missing, _mode = self._station_required_bindings()
        if missing:
            names = ", ".join(BindingsManager.DISPLAY_NAMES.get(x, x) for x in missing)
            return False, f"Missing keyboard binding(s): {names}."
        send_error = self._station_binding_sendability_error()
        if send_error:
            return False, send_error
        return True, (
            "Ready: docked station menu state is safe for the VoiceAttack-style "
            "Up x3 / Left-hold anchoring sequence."
        )

    def consider_station_automation_event(self, e):
        event = str(e.get("event") or "")
        if event == "Docked":
            self.station_automation_generation += 1
            self.station_automation_dock_token = (
                f"{e.get('timestamp') or time.time()}|{e.get('StationName') or self.state_data.station}"
            )
            self.station_automation_completed_token = "-"
            self.station_automation_expected_service = "-"
            self.station_automation_expected_event = "-"
            self.station_automation_confirmation_deadline = 0.0
            if self._automation_enabled():
                self.station_automation_pending = True
                self.station_automation_pending_started = time.monotonic()
                self.station_automation_pending_due = time.monotonic() + 1.5
                self.station_automation_status = (
                    "Docked. Waiting 1.5 seconds, then attempting VoiceAttack-style station-menu anchoring."
                )
                self._station_automation_log(
                    f"Docked at {self.state_data.station}; automatic maintenance queued."
                )
            else:
                self.station_automation_pending = False
        elif event == "Undocked":
            self.station_automation_generation += 1
            self.station_automation_pending = False
            self.station_automation_status = "Undocked. Station maintenance idle."
            self.station_automation_current_service = "-"
            self.station_automation_expected_service = "-"
            self.station_automation_expected_event = "-"
            self.station_automation_confirmation_deadline = 0.0
        elif event in ("RefuelAll", "RepairAll", "BuyAmmo", "Resupply"):
            service = {
                "RefuelAll": "refuel",
                "RepairAll": "repair",
                "BuyAmmo": "rearm",
                "Resupply": "rearm",
            }[event]
            detail = ", ".join(
                f"{k}={v}" for k, v in e.items() if k not in ("timestamp", "event")
            ) or "confirmed"
            now = time.monotonic()
            matched = bool(
                self.station_automation_busy
                and self.station_automation_expected_service == service
                and self.station_automation_expected_event in (event, "BuyAmmo" if event == "Resupply" else event)
                and now <= float(self.station_automation_confirmation_deadline or 0.0)
            )
            if matched:
                payload = dict(e)
                self.station_service_confirmation_payload[service] = payload
                self.station_service_confirmations[service].set()
                self.station_automation_last_confirmation = f"{event}: {detail}"
                self._sfx_play("automation_confirm", cooldown=0.35)
            else:
                note = (
                    f"Observed {event} outside the active automation confirmation window; "
                    f"treated as manual/external ({detail})."
                )
                self.station_automation_unmatched_confirmations.append(
                    f"{datetime.now().strftime('%H:%M:%S')}  {note}"
                )
                self._station_automation_log(note)

    def _maybe_run_station_automation(self):
        if self.station_automation_busy or not self.station_automation_pending:
            return
        # Do not let station-service UI automation start underneath another
        # Bridge command such as docking, fighter control, or departure/jump.
        # The pending maintenance run remains queued and will start after the
        # active native command releases cockpit ownership.
        if self.egress_phase != "IDLE":
            self.station_automation_status = "Queued behind Emergency Egress."
            return
        if self.native_command_busy:
            self.station_automation_status = (
                f"Queued behind Bridge command: {self.native_command_name}."
            )
            return
        if not self._automation_enabled():
            self.station_automation_pending = False
            return
        if time.monotonic() < float(self.station_automation_pending_due or 0.0):
            return
        if self.station_automation_completed_token == self.station_automation_dock_token:
            self.station_automation_pending = False
            return

        ok, reason = self._station_preflight()
        if not ok:
            self.station_automation_pending = False
            self.station_automation_status = "Blocked: " + reason
            self._station_automation_log("Blocked: " + reason)
            self.station_automation_notice = "AUTOMATION SETUP: " + reason
            self.station_automation_notice_expires = time.monotonic() + 20.0
            return

        plan, skipped = self._station_service_plan()
        for item in skipped:
            self._station_automation_log(item + ".")
        if not plan:
            self.station_automation_pending = False
            self.station_automation_completed_token = self.station_automation_dock_token
            self.station_automation_status = "Docked. No enabled station maintenance is currently needed."
            return

        snapshot = {
            "token": self.station_automation_dock_token,
            "generation": self.station_automation_generation,
            "station": self.state_data.station,
            "plan": plan,
            "focus_mode": self.bindings.ui_focus_mode(),
            "bindings": {
                action: self.bindings.keyboard_binding(action)
                for action in ("UI_Up", "UI_Left", "UI_Right", "UI_Select")
            },
        }
        self.station_automation_pending = False
        self.station_automation_busy = True
        self.station_automation_active_generation = self.station_automation_generation
        self.station_automation_worker_done.clear()
        self.station_automation_started_mono = time.monotonic()
        self.station_automation_status = "Starting station maintenance..."
        self._station_automation_log(
            "Starting: " + ", ".join(x["label"] for x in plan) + "."
        )
        # Docked speech already announces that services are starting. The actual
        # worker start uses the existing confirmation SFX only, so a second TTS
        # sentence cannot arrive after the service sequence is nearly finished.
        self._sfx_play("automation_confirm", cooldown=0.0)
        threading.Thread(
            target=self._run_station_automation_worker,
            args=(snapshot,),
            daemon=True,
            name="EliteAIStationServices",
        ).start()

    def run_enabled_station_services_now(self):
        if self.station_automation_busy:
            self.station_automation_status = "Station maintenance is already running."
            self.refresh_preferences_widgets()
            return
        if not self._automation_enabled():
            self.station_automation_status = "Enable at least one station service first."
            self.refresh_preferences_widgets()
            return
        if not self.state_data.flag("Docked"):
            self.station_automation_status = "Manual run blocked: you are not docked."
            self.refresh_preferences_widgets()
            return
        self.station_automation_completed_token = "-"
        self.station_automation_dock_token = (
            f"{self.state_data.station}|manual|{time.time():.3f}"
        )
        self.station_automation_pending = True
        self.station_automation_pending_started = time.monotonic()
        self.station_automation_pending_due = time.monotonic()
        self.station_automation_status = "Manual station-maintenance preflight queued."
        self._station_automation_log("Manual RUN ENABLED SERVICES NOW requested.")
        self.refresh_preferences_widgets()

    def _station_worker_put(self, kind, **payload):
        row = {"kind": kind}
        row.update(payload)
        self.station_automation_results.put(row)

    def _station_wait_for_gui_focus(self, target, timeout=3.0):
        deadline = time.monotonic() + max(0.1, float(timeout))
        observed = []
        last = object()
        while time.monotonic() < deadline:
            value = self._station_gui_focus()
            if value != last:
                observed.append(value)
                last = value
            if value == target:
                return True, observed
            if not self.state_data.flag("Docked"):
                return False, observed
            time.sleep(0.05)
        return self._station_gui_focus() == target, observed

    def _station_acquire_services_panel(self, bindings, focus_mode):
        """Validate the post-dock starting state before quick-service input.

        v0.12.22 deliberately does NOT try to infer/highlight the service row from
        GuiFocus. A captured, successful VoiceAttack refuel showed GuiFocus stayed
        at 0 while the real menu navigation worked. The actual anchoring sequence
        is performed fresh for each service by _station_select_quick_service().
        """
        current = self._station_gui_focus()
        self._station_worker_put(
            "history", text=(
                f"Station menu start: GuiFocus={current} "
                f"({GUI_FOCUS_NAMES.get(current, 'Unknown')}). "
                "VoiceAttack-style anchoring will not depend on GuiFocus changing."
            )
        )
        if current not in (0, 5):
            raise RuntimeError(
                f"Unsafe station-menu starting focus GuiFocus={current} "
                f"({GUI_FOCUS_NAMES.get(current, 'Unknown')}); expected the normal docked menu."
            )
        return True

    def _station_cancel_guard(self):
        if self.station_automation_active_generation != self.station_automation_generation:
            raise RuntimeError("Station automation cancelled by cockpit owner change.")

    def _station_tap(self, binding):
        self._station_cancel_guard()
        if not self.key_sender.elite_foreground():
            raise RuntimeError("Elite lost foreground focus; station automation aborted.")
        self.key_sender.send_binding(binding)
        time.sleep(0.07)

    def _station_hold(self, binding, seconds):
        self._station_cancel_guard()
        if not self.key_sender.elite_foreground():
            raise RuntimeError("Elite lost foreground focus; station automation aborted.")
        self.key_sender.send_binding_hold(binding, hold_seconds=seconds)
        time.sleep(0.04)

    def _station_select_quick_service(self, service_row, bindings):
        """Run the proven VoiceAttack quick-service choreography.

        Recorder evidence from a successful VoiceAttack Auto Refuel showed:
          Up x3 -> hold Left about 1.08 s -> Right xN -> Select
        while Status.json remained GuiFocus=0. We intentionally reproduce that
        geometry instead of waiting for GuiFocus=5.

        Refuel=0 Right steps, Repair=1, Rearm=2. The full anchor is repeated for
        every service because selecting one service may move the menu cursor.
        """
        focus = self._station_gui_focus()
        if focus not in (0, 5):
            raise RuntimeError(
                f"Unsafe focused panel before station service selection "
                f"(GuiFocus={focus} {GUI_FOCUS_NAMES.get(focus, 'Unknown')})."
            )

        label = service_row.get("label") or service_row.get("service") or "Service"
        right_steps = int(service_row.get("index", 0))
        self._station_worker_put(
            "history", text=(
                f"{label}: VoiceAttack pattern -> Up x3 -> hold Left 1.05s -> "
                f"Right x{right_steps} -> Select."
            )
        )

        for _ in range(3):
            self._station_tap(bindings["UI_Up"])
        self._station_hold(bindings["UI_Left"], 1.05)
        for _ in range(right_steps):
            self._station_tap(bindings["UI_Right"])

        # Final safety check is only foreground/docking state. GuiFocus is not a
        # valid confirmation signal for this menu, as proven by the capture.
        if not self.state_data.flag("Docked"):
            raise RuntimeError("Ship is no longer docked before station service Select.")
        if not self.key_sender.elite_foreground():
            raise RuntimeError("Elite lost foreground focus before station service Select.")
        self._station_tap(bindings["UI_Select"])

    def _run_station_automation_worker(self, snapshot):
        token = snapshot["token"]
        generation = snapshot["generation"]
        station = snapshot["station"]
        bindings = snapshot["bindings"]
        focus_mode = snapshot["focus_mode"]
        confirmations = {
            "refuel": "RefuelAll",
            "repair": "RepairAll",
            "rearm": "BuyAmmo",
        }
        confirmed_rows = []
        try:
            title = self.key_sender.focus_elite()
            self._station_worker_put(
                "history", text=f"Elite focused for station maintenance: {title}"
            )
            self._station_worker_put(
                "status", status="STATION SERVICE | Anchoring station menu...", current="Panel"
            )
            self._station_acquire_services_panel(bindings, focus_mode)
            for row in snapshot["plan"]:
                if generation != self.station_automation_generation:
                    raise RuntimeError("Docking state changed; station automation cancelled.")
                if not self.state_data.flag("Docked"):
                    raise RuntimeError("Ship is no longer docked; station automation cancelled.")
                service = row["service"]
                label = row["label"]
                evt = self.station_service_confirmations[service]
                evt.clear()
                self.station_service_confirmation_payload.pop(service, None)
                self.station_automation_expected_service = service
                self.station_automation_expected_event = confirmations[service]
                confirm_timeout = 2.0 if service == "refuel" else 3.0
                self.station_automation_confirmation_deadline = time.monotonic() + confirm_timeout + 2.0
                self._station_worker_put(
                    "status", status=f"STATION SERVICE | {label}...", current=label
                )
                self._station_select_quick_service(row, bindings)
                confirmed = False
                confirm_deadline = time.monotonic() + confirm_timeout
                while time.monotonic() < confirm_deadline:
                    self._station_cancel_guard()
                    if evt.wait(timeout=min(0.10, max(0.0, confirm_deadline - time.monotonic()))):
                        confirmed = True
                        break
                if confirmed:
                    payload = dict(self.station_service_confirmation_payload.get(service) or {})
                    detail_bits = []
                    if payload.get("Amount") is not None:
                        try:
                            detail_bits.append(f"{float(payload['Amount']):.2f} t")
                        except Exception:
                            detail_bits.append(f"Amount={payload['Amount']}")
                    if payload.get("Cost") is not None:
                        try:
                            detail_bits.append(f"{int(payload['Cost']):,} CR")
                        except Exception:
                            detail_bits.append(f"Cost={payload['Cost']}")
                    detail = " • ".join(detail_bits) if detail_bits else confirmations[service]
                    confirmed_rows.append(f"{label}: {detail}")
                    self._station_worker_put(
                        "history", text=f"{label} confirmed by {confirmations[service]}: {detail}"
                    )
                else:
                    self._station_worker_put(
                        "history",
                        text=(
                            f"{label}: no {confirmations[service]} journal confirmation within {confirm_timeout:.0f} seconds; "
                            + ("tank may already be full; " if service == "refuel" else "")
                            + "no retry was sent."
                        ),
                    )
                self.station_automation_expected_service = "-"
                self.station_automation_expected_event = "-"
                self.station_automation_confirmation_deadline = 0.0
                time.sleep(0.20)

            notice = (
                "STATION SERVICE: " + " | ".join(confirmed_rows)
                if confirmed_rows
                else "STATION SERVICE: maintenance sequence finished with no journal confirmations."
            )
            self._station_worker_put(
                "done", token=token, status="Station maintenance sequence complete.", notice=notice
            )
        except Exception as exc:
            self._station_worker_put(
                "done",
                token=token,
                status=f"Station maintenance aborted: {exc}",
                notice=f"STATION SERVICE: aborted safely • {exc}",
                error=True,
            )
        finally:
            self.station_automation_worker_done.set()

    def _drain_station_automation_results(self):
        changed = False
        while True:
            try:
                row = self.station_automation_results.get_nowait()
            except queue.Empty:
                break
            changed = True
            kind = row.get("kind")
            if kind == "status":
                self.station_automation_status = row.get("status") or self.station_automation_status
                self.station_automation_current_service = row.get("current") or "-"
            elif kind == "history":
                self._station_automation_log(row.get("text") or "Station automation update")
            elif kind == "done":
                self.station_automation_busy = False
                self.station_automation_started_mono = 0.0
                self.station_automation_current_service = "-"
                self.station_automation_expected_service = "-"
                self.station_automation_expected_event = "-"
                self.station_automation_confirmation_deadline = 0.0
                self.station_automation_status = row.get("status") or "Station maintenance complete."
                self.station_automation_last_action = self.station_automation_status
                self.station_automation_completed_token = row.get("token") or self.station_automation_dock_token
                self.station_automation_notice = row.get("notice") or "STATION SERVICE: complete"
                self.station_automation_notice_expires = time.monotonic() + (22.0 if row.get("error") else 15.0)
                self._station_automation_log(self.station_automation_status)
                self._sfx_play("automation_confirm", cooldown=0.0)
                message = (
                    "Ship services aborted. Check Bridge status."
                    if row.get("error") else "Ship services complete."
                )
                voice_key = "station_service_aborted" if row.get("error") else "station_service_complete"
                try:
                    self.after(300, lambda msg=message, key=voice_key: self._voice_say(
                        "LOW", msg, kind="STATION SERVICE", key=key, cooldown=2.0
                    ))
                except Exception:
                    self._voice_say(
                        "LOW", message, kind="STATION SERVICE", key=voice_key, cooldown=2.0
                    )
        if changed:
            self.refresh_preferences_widgets()

    def _refresh_command_run_banner(self):
        banner = getattr(self, "command_run_banner", None)
        if banner is None:
            return
        now = time.monotonic()
        if self.egress_phase != "IDLE":
            banner.configure(
                text=f"EMERGENCY OWNER • {self.egress_phase} • {self.egress_status}",
                bg="#8f1d1d", fg="white",
            )
            return
        if self.station_automation_busy:
            service = self.station_automation_current_service
            service_text = f" • {service}" if service not in ("", "-") else ""
            elapsed = max(0, int(now - float(self.station_automation_started_mono or now)))
            banner.configure(
                text=(
                    f"AUTOMATION RUNNING • Station Maintenance{service_text} • {elapsed}s • "
                    "Bridge is using station UI controls; avoid manual UI navigation"
                ),
                bg="#9a5a12", fg="white",
            )
            return
        if self.native_command_busy:
            elapsed = max(0, int(now - float(self.native_command_started_mono or now)))
            banner.configure(
                text=(
                    f"COMMAND RUNNING • {self.native_command_name} • {elapsed}s • "
                    "Bridge owns cockpit controls until this sequence finishes"
                ),
                bg="#8a5a12", fg="white",
            )
            return
        if self.station_automation_pending:
            delay = max(0.0, float(self.station_automation_pending_due or 0.0) - now)
            banner.configure(
                text=f"AUTOMATION QUEUED • Station Maintenance • starts when safe ({delay:.1f}s hold)",
                bg="#6b5a1f", fg="white",
            )
            return
        banner.configure(
            text="CONTROL READY • No Bridge command is using cockpit controls",
            bg="#355c45", fg="white",
        )

    def refresh_preferences_widgets(self):
        if not hasattr(self, "station_automation_status_var"):
            return
        if hasattr(self, "setup_health_tree"):
            try:
                self._refresh_setup_preflight()
            except Exception:
                pass
        s = self.state_data
        if hasattr(self, "profile_detected_commander_var"):
            self.profile_detected_commander_var.set(s.commander or "-")
        if hasattr(self, "profile_status_var"):
            self.profile_status_var.set(f"Bridge will address you as: {self._commander_address()}")
        if self.controller_summary_var is not None:
            bound = len(self.controller_bindings)
            conflicts = len(self.controller_manager.conflicts())
            extra = f" • {conflicts} conflict(s)" if conflicts else ""
            self.controller_summary_var.set(
                f"{self.controller_manager.connected_summary()} • {bound}/{len(BRIDGE_HOTKEY_SPECS)} Bridge actions bound{extra}"
            )
        if hasattr(self, "voice_input_status_var"):
            ptt = self.controller_bindings.get("push_to_talk")
            required = (
                f"PTT READY • {ptt.get('device_name')} • {BridgeControllerManager.binding_label(ptt)}"
                if isinstance(ptt, dict) else
                "PTT MISSING • map a required Push-to-Talk control in COMMAND MAP / HOTAS"
            )
            copilot_state = str(getattr(self, "copilot_status", "-") or "-")
            self.voice_input_status_var.set(
                f"{required}\nMic: {self.voice_input_status}\nLast transcript: {self.voice_input_last_text}\nCopilot: {copilot_state}"
            )
            if hasattr(self, "voice_latency_var"):
                self.voice_latency_var.set(self.voice_latency_last)
        if hasattr(self, "audio_default_device_var"):
            self.audio_default_device_var.set(
                f"Windows/default input: {self.audio_default_input}  •  output: {self.audio_default_output}"
            )
        if hasattr(self, "sfx_status_var"):
            self.sfx_manager.tick()
            self.sfx_status_var.set(
                f"{self.sfx_manager.status} • {'enabled' if self.sfx_enabled_var.get() else 'disabled'} • "
                f"volume {int(round(float(self.sfx_volume_var.get())))}% • played {self.sfx_manager.play_count} • "
                f"priority drops {self.sfx_manager.drop_count}"
            )
            self.sfx_last_var.set(
                f"{self.sfx_manager.last_sound} • {self.sfx_manager.last_file}"
                if self.sfx_manager.last_sound != "-" else "-"
            )
        if hasattr(self, "voice_status_var"):
            cfg = self.voice_engine.config_snapshot()
            self.voice_status_var.set(
                f"{self.voice_engine.status} • selected {cfg.get('engine')} / {cfg.get('voice')} • "
                f"character {cfg.get('effect')} {cfg.get('effect_strength')}% • "
                f"volume {cfg.get('volume')}% • speed {cfg.get('speed'):.2f}x • quality {cfg.get('quality')} • "
                f"last backend {self.voice_engine.last_backend} • spoken {self.voice_engine.spoken_count} • "
                f"dropped {self.voice_engine.dropped_count} • dedupe suppressed {self.voice_suppressed_count}"
            )
            self.voice_last_var.set(
                f"{self.voice_last_kind}: {self.voice_last_announcement}" if self.voice_last_announcement != "-" else "-"
            )
        self.station_automation_status_var.set(self.station_automation_status)
        self.station_automation_station_var.set(
            f"{'YES' if s.flag('Docked') else 'NO'} • {s.station}"
        )
        if getattr(s, "station_services_explicit", False):
            services = ", ".join(sorted(s.station_services)) or "none reported"
        else:
            services = "waiting for a Docked event with StationServices"
        self.station_automation_services_var.set(services)
        if self.bindings.path:
            self.station_automation_binding_source_var.set(
                f"{self.bindings.source_kind}: {self.bindings.path}"
            )
        else:
            self.station_automation_binding_source_var.set(self.bindings.error or "No bindings loaded")
        self.station_automation_bindings_watch_var.set(
            f"{self.bindings_watch_status} • last reload: {self.bindings_watch_last_reload}"
        )
        mode = self.bindings.ui_focus_mode()
        mode_short = "Hold" if "hold" in mode.casefold() else ("Toggle" if "toggle" in mode.casefold() else mode)
        self.station_automation_uifocus_var.set(
            f"{self.bindings.binding_display('UIFocus')} • mode: {mode_short}"
        )
        controls = []
        for action in ("UI_Up", "UI_Left", "UI_Right", "UI_Select"):
            controls.append(
                f"{BindingsManager.DISPLAY_NAMES.get(action, action)}={self.bindings.binding_display(action)}"
            )
        self.station_automation_ui_controls_var.set(" • ".join(controls))
        fuel = self._current_main_fuel()
        cap = s.fuel_capacity_main
        fuel_text = (
            f"Fuel {fuel:.2f}/{cap:.2f} t" if fuel is not None and cap is not None
            else "Fuel unknown"
        )
        hull_text = f"Hull {float(s.hull_health) * 100:.1f}%" if s.hull_health is not None else "Hull unknown"
        self.station_automation_ship_var.set(f"{fuel_text} • {hull_text}")

        self.station_automation_history_text.configure(state="normal")
        self.station_automation_history_text.delete("1.0", "end")
        for line in list(self.station_automation_history)[-80:]:
            self.station_automation_history_text.insert("end", line + "\n")
        self.station_automation_history_text.see("end")
        self.station_automation_history_text.configure(state="disabled")

