    @staticmethod
    def _market_pad_label(value):
        """Translate API pad codes to Elite-friendly labels."""
        if value is None:
            return "?"
        text = str(value).strip().upper()
        mapping = {
            "1": "S", "2": "M", "3": "L",
            "S": "S", "SMALL": "S",
            "M": "M", "MEDIUM": "M",
            "L": "L", "LARGE": "L",
        }
        return mapping.get(text, text or "?")

    def _current_ship_pad_requirement(self):
        """Return (minimum pad code, display name).

        Important: Elite's ShipName field is the commander's custom nickname.
        Pad compatibility must be based on the actual ship type in state.ship.

        We currently map only ship types we have positively identified in live
        telemetry, and keep unknown ships unfiltered rather than risking a
        false exclusion.
        """
        ship_type = str(getattr(self.state_data, "ship", "") or "").strip()
        ship_name = str(getattr(self.state_data, "ship_name", "") or "").strip()

        def norm(value):
            return (
                str(value or "")
                .casefold()
                .replace(" ", "")
                .replace("_", "")
                .replace("-", "")
            )

        key = norm(ship_type)

        # Elite journal telemetry for the user's current ship:
        #   Ship: panthermkii
        if key in ("panthermkii", "pantherclippermkii", "pantherclippermk2"):
            display = "Panther Clipper Mk II"
            if ship_name:
                display += f" ({ship_name})"
            return 3, display

        display = ship_type or "Unknown ship"
        if ship_name and ship_name.casefold() != display.casefold():
            display += f" ({ship_name})"
        return None, display

    @staticmethod
    def _market_pad_code(value):
        text = str(value or "").strip().upper()
        mapping = {
            "1": 1, "S": 1, "SMALL": 1,
            "2": 2, "M": 2, "MEDIUM": 2,
            "3": 3, "L": 3, "LARGE": 3,
        }
        return mapping.get(text)

    def _market_filter_ship_compatible(self, rows):
        required, ship_name = self._current_ship_pad_requirement()
        if not self.market_search_ship_compatible_var.get() or required is None:
            return list(rows), 0, required, ship_name

        kept = []
        removed = 0
        for row in rows:
            pad_code = self._market_pad_code(row.get("pad"))
            # Unknown pad is kept. We would rather flag uncertainty than hide a
            # potentially valid market.
            if pad_code is not None and pad_code < required:
                removed += 1
                continue
            kept.append(row)
        return kept, removed, required, ship_name

    @staticmethod
    def _norm_market_price_scores(rows, mode):
        prices = [float(r.get("price") or 0) for r in rows if float(r.get("price") or 0) > 0]
        if not prices:
            return {}
        lo, hi = min(prices), max(prices)
        span = max(1.0, hi - lo)
        scores = {}
        for idx, r in enumerate(rows):
            p = float(r.get("price") or 0)
            if mode == "BUY":
                scores[idx] = max(0.0, min(1.0, (hi - p) / span))
            else:
                scores[idx] = max(0.0, min(1.0, (p - lo) / span))
        return scores

    def _score_market_rows(self, rows, query):
        """Add a 0-100 practical score and return three useful picks.

        Weighting intentionally favors price, while still penalizing long
        supercruise trips, long inter-system travel, stale data, and thin stock.
        """
        if not rows:
            return rows, {}

        mode = query.get("mode", "BUY")
        max_distance = max(1.0, float(query.get("max_distance") or 100))
        max_days = max(1.0, float(query.get("max_days") or 7))
        min_volume = max(1.0, float(query.get("min_volume") or 1))
        price_scores = self._norm_market_price_scores(rows, mode)

        for idx, row in enumerate(rows):
            price_score = price_scores.get(idx, 0.0)

            ly = row.get("distance_ly")
            if ly is None:
                distance_score = 0.25
            else:
                distance_score = max(0.0, 1.0 - min(float(ly), max_distance) / max_distance)

            arrival = row.get("arrival_ls")
            if arrival is None:
                arrival_score = 0.35
            else:
                arrival = max(0.0, float(arrival))
                # Log scaling: 10 LS is barely penalized; 100k+ LS is heavily penalized.
                arrival_score = max(0.0, 1.0 - math.log10(1.0 + arrival) / 6.0)

            age_s = market_age_seconds(row.get("updated_at"))
            if age_s is None:
                freshness_score = 0.25
            else:
                freshness_score = max(
                    0.0,
                    1.0 - min(float(age_s), max_days * 86400.0) / (max_days * 86400.0)
                )

            volume = float(row.get("volume") or 0)
            if row.get("infinite_volume"):
                volume_score = 1.0
            else:
                # All displayed rows already meet minimum volume. Extra volume is
                # only a small confidence/cushion bonus, capped at 4 full loads.
                volume_score = min(1.0, volume / (min_volume * 4.0))

            score = (
                0.50 * price_score
                + 0.20 * distance_score
                + 0.15 * arrival_score
                + 0.10 * freshness_score
                + 0.05 * volume_score
            )
            row["practical_score"] = round(score * 100.0, 1)
            row["pick_tags"] = []

        # Best practical.
        practical = max(rows, key=lambda r: r.get("practical_score", 0.0))

        # Cheapest for BUY, highest-paying for SELL.
        if mode == "BUY":
            price_pick = min(rows, key=lambda r: int(r.get("price") or 10**18))
            best_price = float(price_pick.get("price") or 0)
            good = [
                r for r in rows
                if float(r.get("price") or 10**18) <= best_price * 1.10
            ]
        else:
            price_pick = max(rows, key=lambda r: int(r.get("price") or 0))
            best_price = float(price_pick.get("price") or 0)
            good = [
                r for r in rows
                if float(r.get("price") or 0) >= best_price * 0.90
            ]

        # "Closest good" means within 10% of the best price, then closest LY,
        # then shortest supercruise.
        def travel_key(r):
            ly = r.get("distance_ly")
            arrival = r.get("arrival_ls")
            return (
                float(ly) if ly is not None else 10**9,
                float(arrival) if arrival is not None else 10**12,
            )

        closest = min(good or rows, key=travel_key)

        picks = {
            "practical": practical,
            "price": price_pick,
            "closest": closest,
        }

        for tag, row in picks.items():
            if tag == "practical":
                row["pick_tags"].append("BEST")
            elif tag == "price":
                row["pick_tags"].append("PRICE")
            elif tag == "closest":
                row["pick_tags"].append("CLOSE")

        return rows, picks

    @staticmethod
    def _compact_provider_error(text):
        text = str(text or "")
        provider = text.split(":", 1)[0].strip() or "Provider"
        http = re.search(r"HTTP\s+(\d{3})", text, flags=re.I)
        if http:
            return f"{provider} unavailable (HTTP {http.group(1)})"
        if "timed out" in text.lower():
            return f"{provider} timed out"
        if "connection" in text.lower():
            return f"{provider} connection failed"
        return f"{provider} unavailable"

    def _market_provider_summary(self):
        provider = self.market_search_engine.last_provider or "-"
        errors = list(self.market_search_engine.last_provider_errors or [])
        if errors:
            compact = ", ".join(self._compact_provider_error(e) for e in errors)
            return f"{provider} fallback | {compact}"
        return provider

    @staticmethod
    def _market_pick_text(label, row, mode):
        if not row:
            return f"{label}: -"
        price_word = "pay" if mode == "BUY" else "receive"
        ly = row.get("distance_ly")
        ly_text = "?" if ly is None else f"{float(ly):.1f} LY"
        arrival = row.get("arrival_ls")
        arrival_text = "?" if arrival is None else f"{float(arrival):,.0f} LS"
        return (
            f"{label}: {row.get('station')} / {row.get('system')} | "
            f"{int(row.get('price') or 0):,} CR {price_word} | {ly_text} | "
            f"{arrival_text} | {market_age_text(row.get('updated_at'))} | "
            f"score {float(row.get('practical_score') or 0):.1f}"
        )

    def market_search_plot_pick(self, key):
        row = self.market_pick_rows.get(key)
        if not row:
            messagebox.showinfo("Market Search", "Run a market search first.")
            return
        system = row.get("system")
        station = row.get("station")
        if not system or system == "?":
            messagebox.showerror("Market Search", "That pick does not contain a usable system name.")
            return
        self.nav_destination_var.set(system)
        self.nav_log(
            f"Smart Market Pick selected {key}: {station} / {system} | "
            f"price={int(row.get('price') or 0):,} | score={row.get('practical_score')}."
        )
        self.nav_portable_route_current()

    def _build_market_search_tab(self):
        top = ttk.LabelFrame(self.market_search_tab, text="Galaxy Commodity Search", padding=10)
        top.pack(fill="x", pady=(0, 8))

