    def market_search_use_current_system(self):
        system = self.state_data.system
        if system and system != "-":
            self.market_search_system_var.set(system)
            self.market_search_follow_current_var.set(True)
            self.market_search_status_var.set(f"Search origin set to current system: {system}")

    def refresh_market_search_widgets(self):
        if not hasattr(self, "market_search_system_var"):
            return
        if self.market_search_follow_current_var.get():
            system = self.state_data.system
            if system and system != "-" and self.market_search_system_var.get() != system:
                self.market_search_system_var.set(system)

        required_pad, ship_name = self._current_ship_pad_requirement()
        if required_pad == 3:
            self.market_ship_status_var.set(f"{ship_name} requires a Large pad.")
        elif required_pad == 2:
            self.market_ship_status_var.set(f"{ship_name} requires a Medium or Large pad.")
        elif required_pad == 1:
            self.market_ship_status_var.set(f"{ship_name} can use any standard pad.")
        else:
            self.market_ship_status_var.set(
                f"{ship_name}: pad requirement not mapped yet, so unknown pads/results are not hidden."
            )

        snap = self.eddn_listener.snapshot()
        if snap["available"]:
            state = "LIVE" if snap["connected"] else "WAITING"
            self.eddn_status_var.set(
                f"EDDN {state} | all messages {snap['total_messages']:,} | commodity snapshots {snap['commodity_messages']:,} | "
                f"cache {snap['cached_markets']:,} markets / {snap['cached_rows']:,} commodity rows | "
                f"last market {snap['last_market']} | {snap['status']}"
            )
        else:
            self.eddn_status_var.set(
                f"EDDN disabled because pyzmq is unavailable: {snap['last_error'] or ZMQ_IMPORT_ERROR}. "
                "The launcher can install pyzmq automatically."
            )


    def _local_market_snapshot_for_search(self, commodity):
        s = self.state_data
        key = market_commodity_key(commodity)
        for item in list(s.market_items):
            display = item.get("Name_Localised") or item.get("Name")
            if market_commodity_key(display) != key:
                continue
            return {
                "market_id": s.market_id,
                "system": s.market_system,
                "station": s.market_station,
                "commodity_key": key,
                "buy_price": _market_int(item.get("BuyPrice"), 0),
                "sell_price": _market_int(item.get("SellPrice"), 0),
                "buy_price_meaning": "commander purchase price from market",
                "sell_price_meaning": "market offer when commander sells",
                "stock": _market_int(item.get("Stock"), 0),
                "demand": _market_int(item.get("Demand"), 0),
                "stock_bracket": _market_int(item.get("StockBracket"), 0),
                "demand_bracket": _market_int(item.get("DemandBracket"), 0),
                "updated_at": s.market_timestamp,
            }
        return None

    def market_search_run(self):
        if self.market_search_busy:
            self.market_search_status_var.set("A market search is already running.")
            return

        system = self.market_search_system_var.get().strip()
        commodity = self.market_search_commodity_var.get().strip()
        mode = self.market_search_mode_var.get().strip().upper()
        if not system or system == "-":
            messagebox.showerror("Market Search", "No origin system is available yet.")
            return
        if not commodity:
            messagebox.showerror("Market Search", "Enter a commodity name, for example Silver.")
            return
        try:
            min_volume = max(1, int(self.market_search_volume_var.get().strip() or "1"))
            max_distance = max(1, min(500, int(self.market_search_distance_var.get().strip() or "100")))
            max_days = max(1, min(14, int(self.market_search_age_var.get().strip() or "1")))
        except ValueError:
            messagebox.showerror("Market Search", "Min tons, Max LY, and Max age days must be whole numbers.")
            return
        if mode not in ("BUY", "SELL"):
            mode = "BUY"

        # Snap local station data on the Tk thread before the background REST query starts.
        local_market = self._local_market_snapshot_for_search(commodity)
        origin_coords = self.state_data.system_pos
        exclude_carriers = bool(self.market_search_exclude_carriers_var.get())
        query = {
            "system": system, "commodity": commodity, "mode": mode,
            "min_volume": min_volume, "max_distance": max_distance,
            "max_days": max_days, "exclude_carriers": exclude_carriers,
        }
        self.market_search_busy = True
        self.market_search_button.configure(state="disabled")
        action = "buy" if mode == "BUY" else "sell"
        self.market_search_status_var.set(
            f"Searching for places to {action} {commodity} within {max_distance} LY of {system}... "
            "Ardent primary, EDData fallback."
        )

        def worker():
            try:
                rows = self.market_search_engine.search(
                    system, commodity, mode, min_volume, max_distance, max_days,
                    exclude_carriers, local_market=local_market,
                    origin_coords=origin_coords,
                )
                self.after(0, lambda: self._market_search_complete(query, rows, None))
            except Exception as exc:
                self.after(0, lambda exc=exc: self._market_search_complete(query, [], str(exc)))

        threading.Thread(target=worker, daemon=True, name="MarketSearch").start()

    def _market_search_complete(self, query, rows, error):
        self.market_search_busy = False
        self.market_search_button.configure(state="normal")
        self.market_last_query = query
        self.market_last_error = error or ""
        self.market_last_search_time = datetime.now().strftime("%H:%M:%S")
        self.market_search_result_map = {}
        self.market_pick_rows = {}

        for item in self.market_search_tree.get_children():
            self.market_search_tree.delete(item)

        mode = query["mode"]
        self.market_search_tree.heading("Price", text="You pay" if mode == "BUY" else "You receive")
        self.market_search_tree.heading("Volume", text="Stock" if mode == "BUY" else "Demand")

        if error:
            self.market_search_results = []
            self.market_best_var.set("Best practical: -")
            self.market_cheapest_var.set("Cheapest / best price: -")
            self.market_closest_var.set("Closest good option: -")
            self.market_search_status_var.set(f"Market search failed: {error}")
            return

        # Hide stations that definitely cannot accept the current ship. Unknown
        # pad values remain visible rather than risking false negatives.
        filtered, removed, required_pad, ship_name = self._market_filter_ship_compatible(rows)

        # Score only the usable/visible result set so recommendations cannot
        # point to a station the Panther cannot land at.
        filtered, picks = self._score_market_rows(filtered, query)
        self.market_search_results = filtered
        self.market_pick_rows = picks

        for idx, row in enumerate(filtered, start=1):
            distance = row.get("distance_ly")
            distance_text = "?" if distance is None else f"{distance:.1f}"
            arrival = row.get("arrival_ls")
            arrival_text = "?" if arrival is None else f"{arrival:,.0f}"
            volume_text = "∞" if row.get("infinite_volume") else f"{_market_int(row.get('volume')):,}"
            tags = "+".join(row.get("pick_tags") or [])
            iid = f"market_{idx}"
            self.market_search_result_map[iid] = row
            self.market_search_tree.insert("", "end", iid=iid, values=(
                idx,
                tags,
                row.get("system", "?"),
                row.get("station", "?"),
                f"{_market_int(row.get('price')):,}",
                volume_text,
                distance_text,
                arrival_text,
                market_age_text(row.get("updated_at")),
                self._market_pad_label(row.get("pad")),
                f"{float(row.get('practical_score') or 0):.1f}",
                row.get("source") or "?",
            ))

        provider_summary = self._market_provider_summary()
        ship_note = ""
        if removed:
            ship_note = f" | hid {removed} incompatible station(s) for {ship_name}"

        if filtered:
            practical = picks.get("practical")
            price_pick = picks.get("price")
            closest = picks.get("closest")

            self.market_best_var.set(
                self._market_pick_text("Best practical", practical, mode)
            )
            self.market_cheapest_var.set(
                self._market_pick_text(
                    "Cheapest" if mode == "BUY" else "Best price",
                    price_pick, mode
                )
            )
            self.market_closest_var.set(
                self._market_pick_text("Closest good option", closest, mode)
            )

            self.market_search_status_var.set(
                f"{len(filtered)} usable result(s) | {provider_summary}{ship_note}"
            )
        else:
            self.market_best_var.set("Best practical: -")
            self.market_cheapest_var.set("Cheapest / best price: -")
            self.market_closest_var.set("Closest good option: -")
            self.market_search_status_var.set(
                f"No usable results matched those filters | {provider_summary}{ship_note}. "
                "Try increasing Max age/Max LY or lowering minimum tons."
            )


    def market_search_plot_selected(self):
        selected = self.market_search_tree.selection()
        if not selected:
            messagebox.showinfo("Market Search", "Select a market result first.")
            return
        row = self.market_search_result_map.get(selected[0])
        if not row:
            return
        system = row.get("system")
        station = row.get("station")
        if not system or system == "?":
            messagebox.showerror("Market Search", "That result does not contain a usable system name.")
            return
        self.nav_destination_var.set(system)
        self.nav_log(
            f"Market Search selected {station} / {system} | source={row.get('source')} | "
            f"price={_market_int(row.get('price')):,} | age={market_age_text(row.get('updated_at'))}."
        )
        self.nav_portable_route_current()

    def _on_close_bridge(self):
        # v0.12.81 safety net: Preferences/Audio choices are already saved by
        # their controls, but write one final snapshot so the current state is
        # always the next-launch default on this machine.
        try:
            self._capture_windowed_geometry()
            self._save_automation_config()
        except Exception:
            pass
        try:
            self.voice_input_record_stop.set()
            self.always_listen_stop.set()
        except Exception:
            pass
        try:
            self.controller_manager.stop()
        except Exception:
            pass
        try:
            self.bridge_hotkeys.stop()
        except Exception:
            pass
        try:
            self.eddn_listener.stop()
        except Exception:
            pass
        try:
            self.voice_engine.stop()
        except Exception:
            pass
        try:
            self.sfx_manager.stop()
        except Exception:
            pass
        self.destroy()

