    def latest_journal(self):
        files=list(JOURNAL_DIR.glob("Journal.*.log"))
        return max(files,key=lambda p:p.stat().st_mtime) if files else None

    def _journal_event_is_live_for_side_effects(self, event):
        """True only for fresh journal rows that may trigger audible/control side effects.

        Elite journal history is replayed at startup to rebuild state. It can also be
        reread if a journal is replaced/truncated. In both cases old rows must remain
        silent and must not retrigger automation.
        """
        ts = parse_ts((event or {}).get("timestamp"))
        if ts is None:
            return False
        try:
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
            else:
                ts = ts.astimezone(timezone.utc)
            # Anything written before this Bridge process started is catch-up history.
            if ts < self.live_side_effect_cutoff_utc:
                return False
            # A second recency gate protects against a later journal rewind/replay.
            age = (datetime.now(timezone.utc) - ts).total_seconds()
            return -5.0 <= age <= 30.0
        except Exception:
            return False

    def seed_journal_state(self,path):
        try:
            with path.open("r",encoding="utf-8",errors="replace") as f:
                for line in f:
                    line=line.strip()
                    if not line: continue
                    try: e=json.loads(line)
                    except Exception: continue
                    self.state_data.process_event(e,seed=True)
                self.journal_pos=f.tell()
        except Exception as exc:
            self.state_data.add_log("BridgeError",f"Journal seed failed: {exc}")

    def poll_journal(self):
        path=self.latest_journal()
        if path is None:
            self.state_data.journal_connected=False
            return
        self.state_data.journal_connected=True
        self.state_data.last_journal=path.name
        if self.current_journal != path:
            self.current_journal=path
            self.journal_pos=0
            self.state_data=EliteState()
            self.advisor=DryRunAdvisor()
            self.last_status_mtime=None
            self.last_market_mtime=None
            self.last_navroute_mtime=None
            self.last_modulesinfo_mtime=None
            self.ai_last_status_flags=None
            self.ai_pending_trigger=None
            self.station_safety_pips_active = False
            self.station_safety_pips_context = "-"
            self.station_safety_pips_seen_mass_lock = False
            self.station_safety_pips_started_mono = 0.0
            self._clear_pending_trade_loop_route(
                "New Elite journal detected; pending auto-route cleared for safety.", log=False
            )
            self.seed_journal_state(path)
            self.state_data.add_log("Bridge",f"Watching {path.name}")
            return
        try:
            size=path.stat().st_size
            if self.journal_pos>size: self.journal_pos=0
            with path.open("r",encoding="utf-8",errors="replace") as f:
                f.seek(self.journal_pos)
                while True:
                    line=f.readline()
                    if not line: break
                    self.journal_pos=f.tell()
                    line=line.strip()
                    if not line: continue
                    try: e=json.loads(line)
                    except json.JSONDecodeError: continue
                    self.state_data.process_event(e,seed=False)
                    if self._journal_event_is_live_for_side_effects(e):
                        self.consider_travel_event(e)
                        self.consider_voice_event(e)
                        self.consider_sfx_event(e)
                        self.consider_station_safety_event(e)
                        self.consider_ai_event(e)
                        self.consider_trade_loop_event(e)
                        self.consider_station_automation_event(e)
                    else:
                        self.historical_side_effect_rows_suppressed += 1
        except Exception as exc:
            self.state_data.journal_connected=False
            self.state_data.add_log("BridgeError",f"Journal read failed: {exc}")

    def poll_status(self):
        if not STATUS_FILE.exists():
            self.state_data.status_connected=False
            return
        try:
            mtime=STATUS_FILE.stat().st_mtime_ns
            if mtime != self.last_status_mtime:
                s=json.loads(STATUS_FILE.read_text(encoding="utf-8",errors="replace"))
                new_flags=int(s.get("Flags",0) or 0)
                old_flags=self.ai_last_status_flags
                old_legal = self.sfx_last_legal_state
                self.state_data.update_status(s)
                self.last_status_mtime=mtime
                self.ai_last_status_flags=new_flags
                new_legal = str(s.get("LegalState") or "").strip().casefold()
                self.sfx_last_legal_state = new_legal
                if old_legal is not None and old_legal != "hostile" and new_legal == "hostile":
                    self._sfx_play("danger", cooldown=12.0)
                if old_flags is not None:
                    self.consider_ai_status_transition(old_flags,new_flags)
            self.state_data.status_connected=True
        except Exception:
            self.state_data.status_connected=False

    def poll_cargo_file(self):
        """Read Elite's Cargo.json authoritative inventory sidecar.

        Frontier's later journal Cargo events may only indicate that this file
        changed, so commodity-level cargo tracking cannot rely on the journal
        event alone.
        """
        if not CARGO_FILE.exists():
            self.state_data.cargo_file_connected = False
            return

        try:
            mtime = CARGO_FILE.stat().st_mtime_ns
            if mtime == self.last_cargo_mtime:
                self.state_data.cargo_file_connected = True
                return

            # Do not save mtime until parsing succeeds. Elite can briefly expose
            # partially-written JSON, just like NavRoute.json.
            raw = CARGO_FILE.read_text(encoding="utf-8", errors="replace")
            data = json.loads(raw)

            old_manifest = [
                (
                    market_commodity_key(i.get("Name_Localised") or i.get("Name")),
                    int(i.get("Count", 0) or 0),
                )
                for i in self.state_data.cargo
                if isinstance(i, dict)
            ]

            if self.state_data.update_cargo_file(data):
                self.last_cargo_mtime = mtime

                new_manifest = [
                    (
                        market_commodity_key(i.get("Name_Localised") or i.get("Name")),
                        int(i.get("Count", 0) or 0),
                    )
                    for i in self.state_data.cargo
                    if isinstance(i, dict)
                ]

                if new_manifest != old_manifest:
                    manifest_text = ", ".join(
                        f"{pretty_name(i.get('Name_Localised') or i.get('Name'))} x{int(i.get('Count', 0) or 0):,}"
                        for i in self.state_data.cargo
                        if isinstance(i, dict)
                    ) or "Empty"
                    self.state_data.add_log(
                        "CargoFile",
                        f"{self.state_data.cargo_count:,} t",
                        data.get("timestamp"),
                        "\n".join([
                            f"Cargo: {manifest_text}",
                            f"Vessel: {data.get('Vessel') or 'Ship'}",
                            f"Source: {CARGO_FILE}",
                        ]),
                    )

        except json.JSONDecodeError:
            # Retry next 500 ms cycle if Elite is mid-write.
            self.state_data.cargo_file_connected = CARGO_FILE.exists()
        except Exception as exc:
            self.state_data.cargo_file_connected = False
            self.state_data.add_log(
                "BridgeError",
                f"Cargo.json read failed: {exc}",
            )

    def poll_modulesinfo_file(self):
        if not MODULESINFO_FILE.exists():
            return
        try:
            mtime = MODULESINFO_FILE.stat().st_mtime_ns
            if mtime == self.last_modulesinfo_mtime:
                return
            data = json.loads(MODULESINFO_FILE.read_text(encoding="utf-8", errors="replace"))
            self.last_modulesinfo_mtime = mtime
            self.state_data.add_log(
                "ModulesInfo", f"{len(data.get('Modules') or [])} module row(s)", data.get("timestamp"),
                f"Source: {MODULESINFO_FILE}"
            )
        except Exception:
            pass

    def poll_market(self):
        if not MARKET_FILE.exists():
            self.state_data.market_connected=False
            return
        try:
            mtime=MARKET_FILE.stat().st_mtime_ns
            if mtime != self.last_market_mtime:
                m=json.loads(MARKET_FILE.read_text(encoding="utf-8",errors="replace"))
                self.state_data.update_market(m)
                self.last_market_mtime=mtime
            self.state_data.market_connected=True
        except Exception:
            self.state_data.market_connected=False

    def poll_navroute_file(self):
        """
        Read Elite's NavRoute.json whenever it changes.

        The journal's NavRoute event does not reliably contain the actual route
        list. NavRoute.json is the authoritative route payload we need for
        destination verification.
        """
        if not NAVROUTE_FILE.exists():
            self.state_data.nav_route_file_connected = False
            return

        try:
            mtime = NAVROUTE_FILE.stat().st_mtime_ns
            if mtime == self.last_navroute_mtime:
                self.state_data.nav_route_file_connected = True
                return

            # Do not advance the saved mtime until JSON parsing succeeds.
            # This lets the next 500 ms poll retry if Elite is mid-write.
            raw = NAVROUTE_FILE.read_text(encoding="utf-8", errors="replace")
            data = json.loads(raw)

            route = data.get("Route")
            destination = "-"
            route_len = 0
            normalized_route = []

            if isinstance(route, list):
                route_len = len(route)
                for raw_row in route:
                    if not isinstance(raw_row, dict):
                        continue
                    system_name = (
                        raw_row.get("StarSystem")
                        or raw_row.get("SystemName")
                        or raw_row.get("Name")
                        or "-"
                    )
                    star_class = self._travel_normalize_star_class(
                        raw_row.get("StarClass") or raw_row.get("StarType")
                    )
                    normalized_route.append({
                        "system": str(system_name),
                        "star_class": star_class,
                        "scoopable": self._travel_star_is_scoopable(star_class),
                        "star_pos": raw_row.get("StarPos"),
                    })
                if route:
                    last = route[-1] if isinstance(route[-1], dict) else {}
                    destination = (
                        last.get("StarSystem")
                        or last.get("SystemName")
                        or last.get("Name")
                        or "-"
                    )

            s = self.state_data
            old_dest = s.nav_route_destination
            old_len = s.nav_route_len

            s.nav_route_destination = destination
            s.nav_route_len = route_len
            s.nav_route_source = "NavRoute.json"
            s.nav_route_file_timestamp = data.get("timestamp") or "-"
            s.nav_route_file_connected = True
            s.nav_revision += 1

            self.last_navroute_mtime = mtime

            # Preserve non-empty route star metadata for travel/fuel intelligence.
            # Do not erase it on Elite's transient empty NavRoute writes during
            # the final leg; the arrival state machine will naturally supersede it.
            if destination != "-" and normalized_route:
                self.travel_route_entries = normalized_route

            # Travel Announcer is intentionally downstream of NavRoute.json.
            # It never participates in plotting or keypresses. If this route came
            # from the conservative post-undock gate, we can truthfully include
            # "mass lock clear" and "clear to jump" in the announcement.
            if destination != "-" and (destination != old_dest or route_len != old_len):
                safe_departure = self._same_system_name(
                    destination, self.travel_safe_departure_target
                ) and bool(self.travel_safe_departure_started_mono)
                self._travel_route_ready(destination, route_len, safe_departure=safe_departure)
                if safe_departure:
                    self.travel_safe_departure_target = "-"
                    self.travel_safe_departure_started_mono = 0.0

            if destination != "-" or route_len:
                s.add_log(
                    "NavRouteFile",
                    destination,
                    data.get("timestamp"),
                    "\n".join([
                        f"Route destination: {destination}",
                        f"Route entries: {route_len}",
                        f"Source: {NAVROUTE_FILE}",
                        f"Previous destination: {old_dest}",
                        f"Previous entries: {old_len}",
                    ]),
                )
            else:
                s.add_log(
                    "NavRouteFile",
                    "Route empty / cleared",
                    data.get("timestamp"),
                    f"Source: {NAVROUTE_FILE}",
                )

        except json.JSONDecodeError:
            # Elite may briefly expose a partially-written JSON file. Leave the
            # mtime untouched so the next poll retries it.
            self.state_data.nav_route_file_connected = True
        except Exception as exc:
            self.state_data.nav_route_file_connected = False
            self.state_data.add_log(
                "BridgeError",
                f"NavRoute.json read failed: {exc}",
            )

    def update_tree(self,tree,rows):
        for item in tree.get_children():
            tree.delete(item)
        for row in rows:
            tree.insert("", "end", values=row)

    def refresh_market_tree(self):
        s=self.state_data
        filt=self.market_filter.get().strip().lower()
        rows=[]
        for item in s.market_items:
            commodity=pretty_name(item.get("Name_Localised") or item.get("Name"))
            category=pretty_name(item.get("Category_Localised") or item.get("Category"))
            if filt and filt not in commodity.lower() and filt not in category.lower():
                continue
            rows.append((
                commodity,
                f"{int(item.get('BuyPrice',0) or 0):,}",
                f"{int(item.get('SellPrice',0) or 0):,}",
                f"{int(item.get('Stock',0) or 0):,}",
                f"{int(item.get('Demand',0) or 0):,}",
                category,
                "YES" if item.get("Producer") else "",
                "YES" if item.get("Consumer") else "",
            ))
        rows.sort(key=lambda r: r[0].lower())
        self.update_tree(self.market_tree,rows)

